KB.lade("vietnam",[{"id":"vietnam-pho-bo","name":"Phở Bò","originalname":"Phở bò","kueche":"vietnam","region":"Hanoi / Nordvietnam (im ganzen Land verbreitet)","beliebtheit":97,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"suppe","kurz":"Vietnams Nationalgericht: eine glasklare, tief aromatische Rinderbrühe mit Sternanis, Zimt und geröstetem Ingwer, dazu weiche Reisbandnudeln und hauchdünn geschnittenes Rindfleisch, das erst in der Schüssel gar wird.","hintergrund":"Phở entstand Ende des 19. und Anfang des 20. Jahrhunderts im Norden Vietnams, vermutlich im Raum Hanoi und Nam Định, und verbindet die vietnamesische Reisnudel-Tradition mit der kolonialen Rindfleischküche. Nach der Teilung des Landes 1954 brachten Flüchtlinge das Gericht in den Süden, wo es mit mehr Kräutern, Sprossen, Hoisin- und Chilisauce gegessen wird; die Hanoi-Version bleibt dagegen schlicht mit Frühlingszwiebel, Pfeffer und Limette. In Vietnam isst man Phở traditionell zum Frühstück, aber ebenso gern zu jeder anderen Tageszeit. Das TasteAtlas-Ranking führte Phở bò zuletzt unter den besten Nudelsuppen der Welt auf Platz 7 und unter den Top-100-Gerichten Asiens auf Platz 27. Das Herz des Gerichts ist die Brühe: Sie wird stundenlang bei kaum sichtbarem Köcheln gezogen und erst am Ende kräftig gewürzt.","portionen":6,"zeit":{"vorbereitung":60,"garen":240,"ruhen":60},"schwierigkeit":3,"zutaten":[{"gruppe":"Für die Brühe","liste":[{"menge":2.5,"einheit":"kg","name":"Rinderknochen (Mark- und Kniegelenkknochen, Ochsenschwanz-Stücke möglich)","hinweis":"beim Metzger vorbestellen und in 6–8 cm Stücke sägen lassen"},{"menge":600,"einheit":"g","name":"Rinderbrust oder Beinscheibe am Stück","hinweis":"Brisket, Querrippe oder Wadenfleisch funktionieren ebenfalls"},{"menge":2,"einheit":"Stück","name":"mittelgroße Zwiebeln, ungeschält (zusammen ca. 450 g)","hinweis":""},{"menge":100,"einheit":"g","name":"frischer Ingwer, ungeschält, in 2 Stücken","hinweis":""},{"menge":5,"einheit":"Stück","name":"Sternanis","hinweis":"ganze, unversehrte Sterne"},{"menge":6,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stange","name":"Zimtstange (Cassia), ca. 8 cm","hinweis":"Cassia ist im Asialaden günstig und passt besser als Ceylon-Zimt"},{"menge":1,"einheit":"TL","name":"Fenchelsamen","hinweis":"optional, bringt eine feine Süße"},{"menge":5,"einheit":"l","name":"kaltes Wasser, zum Kochen","hinweis":"plus Wasser zum Vorkochen der Knochen"},{"menge":1.5,"einheit":"EL","name":"feines Meersalz","hinweis":"zum Abschmecken am Ende anpassen"},{"menge":4,"einheit":"EL","name":"Fischsauce","hinweis":"gute Qualität mit hohem Fischanteil, z. B. Red Boat oder Three Crabs"},{"menge":30,"einheit":"g","name":"gelber Kandiszucker (Đường phèn)","hinweis":"ersatzweise 2 TL hellbrauner Zucker"}]},{"gruppe":"Für die Schüssel","liste":[{"menge":300,"einheit":"g","name":"Rinderhüfte, Rumpsteak oder Filet, sehr kalt","hinweis":"für das rohe Fleisch, das in der Schüssel gar zieht"},{"menge":600,"einheit":"g","name":"frische Reisbandnudeln (Bánh phở), ersatzweise 350 g getrocknete, 3 mm breit","hinweis":"im Asialaden, getrocknete Nudeln vorher einweichen"},{"menge":1,"einheit":"Stück","name":"kleine rote oder weiße Zwiebel, hauchdünn gehobelt","hinweis":""},{"menge":4,"einheit":"Stück","name":"Frühlingszwiebeln, in feine Ringe geschnitten","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander, grob gehackt","hinweis":""},{"menge":null,"einheit":"","name":"frisch gemahlener schwarzer Pfeffer","hinweis":"reichlich"}]},{"gruppe":"Für den Tisch","liste":[{"menge":2,"einheit":"Stück","name":"Limetten, in Spalten","hinweis":""},{"menge":2,"einheit":"Stück","name":"rote Vogelaugen-Chilis, in Ringen","hinweis":""},{"menge":200,"einheit":"g","name":"Mungobohnensprossen","hinweis":""},{"menge":1,"einheit":"Bund","name":"Thai-Basilikum","hinweis":"optional; dazu gern Sägekoriander (Ngò gai)"},{"menge":null,"einheit":"","name":"Hoisinsauce und Sriracha","hinweis":"nach Süd-Art, optional"}]}],"ausruestung":["großer Topf (mindestens 10–12 Liter)","feinmaschiges Sieb und Passiertuch oder Mulltuch","Schaumlöffel und Schöpfkelle","Gasflamme, Grillpfanne oder Backofengrill zum Anrösten","scharfes, langes Messer","kleiner Topf zum Blanchieren der Nudeln, Nudelsieb"],"schritte":[{"titel":"Mise en place: Zutaten bereitstellen","aktion":"vorbereiten","text":"Wiege Knochen, Fleisch und Gewürze ab und stelle alles in Reichweite bereit, denn die Brühe braucht später keine hektischen Handgriffe. Die Zwiebeln und den Ingwer lässt du ungeschält und ungeschnitten, nur den Ingwer teilst du in zwei Stücke, damit er flach auf dem Rost liegt. Prüfe, ob dein größter Topf (10 bis 12 Liter) die Knochen mit Wasser abdeckt – Knochen, die oben herausragen, kochen später trocken und trüben die Brühe. Das rohe Rindfleisch für die Schüssel bleibt bis kurz vor dem Schneiden im Kühlschrank, denn es muss später eiskalt aufgeschnitten werden. Bestelle die Knochen am besten ein bis zwei Tage vorher, damit der Metzger sie sägen kann.","dauer":0,"tipp":"Mische Knochenarten: Markknochen geben Fülle und Fett, Knie- und Gelenkknochen Kollagen, damit die Brühe seidig im Mund wirkt."},{"titel":"Knochen wässern","aktion":"einlegen","text":"Lege die Knochen in eine große Schüssel oder den Topf und bedecke sie vollständig mit kaltem Wasser. Lass sie mindestens 60 Minuten darin liegen und wechsle das Wasser einmal, sobald es sich rosa bis rot gefärbt hat. Das Wasser zieht Blut und lösliche Eiweiße aus dem Mark und den Fleischresten; genau diese würden später als graue Flocken aufsteigen und die Brühe eintrüben. Wenn du die Knochen frisch vom Metzger bekommst, ist dieser Schritt besonders wichtig, bei tiefgefrorenen Knochen reicht eine kürzere Zeit. Am Ende sollte das Wasser nur noch schwach rosa aussehen.","dauer":60,"tipp":"Wer es eilig hat, lässt die Knochen 30 Minuten wässern und kocht sie dafür etwas länger vor."},{"titel":"Knochen vorkochen und Topf reinigen","aktion":"blanchieren","text":"Gib die gewässerten Knochen in den sauberen Topf, bedecke sie mit frischem kaltem Wasser und bringe es bei hoher Hitze zum kräftigen Kochen. Lass es 5 bis 7 Minuten sprudelnd kochen; an der Oberfläche bildet sich dabei dicker, grau-brauner Schaum, der nach Eiweiß und Blut riecht. Gieße alles in ein großes Sieb ab und spüle jeden Knochen unter fließend heißem Wasser ab, bis keine dunklen Reste mehr anhaften. Schrubbe auch den Topf aus, denn an der Wand haftet geronnenes Eiweiß, das sonst später in die Brühe gelangt. Dieser Schritt ist der wichtigste für die Klarheit der Brühe.","dauer":15,"tipp":"Bei Phở ist Klarheit ein Qualitätsmerkmal: lieber einmal gründlich vorkochen als später stundenlang abschöpfen."},{"titel":"Zwiebel und Ingwer anrösten","aktion":"grillen","text":"Röste die ungeschälten Zwiebeln und den Ingwer direkt über der Gasflamme, auf dem Holzkohlegrill oder unter dem Backofengrill (Oberhitze 250 °C, oberste Schiene) 15 bis 20 Minuten lang, bis die Schale schwarz und blasig ist und das Innere weich. Wende alles regelmäßig, damit es rundum gleichmäßig gebräunt ist. Der Duft verändert sich von scharf-rau zu süßlich-rauchig; genau das ist das typische Phở-Aroma. Streife die schwarze Haut unter fließendem Wasser ab, schneide bei den Zwiebeln die Enden ab und klopfe den Ingwer mit der Messerflanke leicht platt, damit er sein Aroma abgibt.","dauer":20,"tipp":"Nur die Oberfläche soll verkohlen; verkohlte Reste vollständig abspülen, sonst schmeckt die Brühe bitter."},{"titel":"Gewürze rösten","aktion":"anbraten","text":"Erhitze eine trockene Pfanne bei mittlerer Hitze und röste Sternanis, Nelken, Zimtstange und Fenchelsamen etwa 1 bis 2 Minuten, bis sie intensiv duften und der Sternanis leicht dunkler wird. Schwenke die Pfanne dabei laufend, denn Nelken und Fenchel verbrennen schnell und werden dann bitter. Fülle die Gewürze in einen Teebeutel aus Mull oder ein Gewürzei, damit du sie später mühelos entfernen kannst und keine Bruchstücke in der Brühe schwimmen. Das Rösten weckt die ätherischen Öle und macht die Gewürze runder; ungeröstet wirken sie flach und herb.","dauer":3,"tipp":"Nimm die Gewürze nach 45 bis 60 Minuten Kochzeit wieder heraus, wenn du eine zurückhaltendere Brühe möchtest – Sternanis dominiert sonst schnell."},{"titel":"Brühe ansetzen und abschäumen","aktion":"kochen","text":"Gib die vorgekochten Knochen zurück in den Topf, gieße 5 Liter kaltes Wasser auf und erhitze es langsam, ohne Deckel, bis kleine Bläschen aufsteigen. Sobald sich ein feiner heller Schaum bildet, schöpfst du ihn mit einer Kelle oder einem Sieb ab; das dauert in den ersten 20 bis 30 Minuten immer wieder. Reduziere dann die Hitze so weit, dass die Oberfläche nur noch leise „lächelt“ – etwa 90 bis 95 °C. Starkes Sprudeln würde Fett und Eiweiß emulgieren und die Brühe milchig machen. Lege nun die angerösteten Zwiebeln und den Ingwer sowie das Gewürzsäckchen in den Topf.","dauer":30,"tipp":"Ein Deckel, der einen Spalt offen bleibt, hält die Temperatur, ohne dass die Brühe überkocht."},{"titel":"Rindfleisch mitgaren","aktion":"koecheln","text":"Lege das Stück Rinderbrust oder Beinscheibe in den Topf, sobald die Brühe ruhig simmert, und lass es 75 bis 90 Minuten leise mitziehen. Es ist gar, wenn ein Holzspieß ohne großen Widerstand eindringt, das Fleisch aber noch Biss hat; es darf nicht zerfasern, weil es später in dünne Scheiben geschnitten wird. Nimm das Fleisch dann heraus und lege es 10 Minuten in kaltes Wasser. Das stoppt das Garen, verhindert eine graue Oberfläche und macht die Scheiben später saftiger. Trockne das Fleisch ab, wickle es in Folie und stelle es kühl, damit es sich später sauber schneiden lässt.","dauer":90,"tipp":"Die Garzeit hängt vom Stück ab: Brust braucht länger als Wadenfleisch. Immer mit dem Spieß prüfen, nicht nach der Uhr allein."},{"titel":"Brühe weiter ziehen lassen und würzen","aktion":"koecheln","text":"Lass die Brühe mit den Knochen weitere 60 bis 90 Minuten leise simmern, insgesamt also etwa 3 bis 3,5 Stunden. Die Flüssigkeit sinkt, die Farbe wird bernsteinfarben und im Duft verbinden sich Rauch, Süße und Gewürze. Gib in den letzten 30 Minuten Fischsauce, Salz und Kandiszucker dazu; früh zugegeben würde die Fischsauce an Frische verlieren. Fülle bei Bedarf kochendes Wasser nach, damit die Knochen bedeckt bleiben. Beim Probieren sollte die Brühe etwas zu kräftig sein, denn Nudeln und Fleisch in der Schüssel sind ungewürzt und verdünnen sie.","dauer":90,"tipp":"Probiere vor der Zugabe der Fischsauce: Der Eigengeschmack nach Rind und Röstaromen soll vor dem Würzen schon deutlich da sein."},{"titel":"Brühe abseihen","aktion":"abseihen","text":"Nimm Knochen, Zwiebeln, Ingwer und Gewürzsäckchen mit einer Zange oder einem Schaumlöffel heraus und lege sie beiseite. Gieße die Brühe vorsichtig durch ein feines Sieb, das mit einem sauberen Passiertuch ausgelegt ist, in einen zweiten Topf; drücke dabei nicht auf die Feststoffe, sonst gelangen Trübstoffe in die Brühe. Wenn du etwas Sehnenfleisch oder weiche Knorpel an den Knochen findest, hebe sie auf: In Vietnam gehören sie als besondere Zugabe in die Schüssel. Die fertige Brühe soll klar und goldbraun sein, ohne Schwebeteilchen.","dauer":15,"tipp":"Schöpfe die Brühe mit der Kelle ab, statt den Topf zu kippen – so bleibt Bodensatz im Topf zurück."},{"titel":"Entfetten und abschmecken","aktion":"abschmecken","text":"Lass die Brühe etwas abkühlen und schöpfe das oben schwimmende Fett mit einer flachen Kelle ab; ein dünner Fettfilm darf bleiben, denn er trägt Aroma. Am einfachsten gelingt das Entfetten, wenn du die Brühe über Nacht in den Kühlschrank stellst und das erstarrte Fett am nächsten Tag abhebst. Erhitze die Brühe danach wieder und stelle die Würze ein: mehr Fischsauce für Tiefe, mehr Salz für Schärfe, eine Messerspitze Zucker für Rundung. Die Brühe sollte tief, warm und leicht süßlich schmecken, aber nicht dominant nach einem einzelnen Gewürz.","dauer":10,"tipp":"Phở-Brühe schmeckt am zweiten Tag oft noch besser; bis zu 4 Tage im Kühlschrank, portionsweise eingefroren mehrere Monate."},{"titel":"Fleisch und Beilagen schneiden","aktion":"schneiden","text":"Lege das rohe Rindfleisch 15 bis 20 Minuten ins Gefrierfach, bis es außen fest, aber nicht durchgefroren ist. Schneide es mit einem sehr scharfen Messer quer zur Faser in etwa 2 mm dünne Scheiben und lege sie ausgebreitet auf einen Teller. Schneide die gegarte Brust ebenfalls in dünne Scheiben. Hobele die Zwiebel so dünn wie möglich und lege sie 15 Minuten in Eiswasser, damit sie knackig wird und die Schärfe verliert. Schneide Frühlingszwiebeln in Ringe, hacke den Koriander und richte Sprossen, Basilikum, Limettenspalten und Chili auf einem Teller an.","dauer":0,"tipp":"Die Scheiben sollen so dünn sein, dass die Brühe sie in Sekunden gar zieht – lieber zu dünn als zu dick."},{"titel":"Nudeln vorbereiten","aktion":"blanchieren","text":"Getrocknete Reisbandnudeln weichst du in lauwarmem Wasser 20 bis 30 Minuten ein, bis sie biegsam und leicht trüb sind; frische Nudeln trennst du nur voneinander und spülst sie kurz. Koche einen Topf Wasser auf und blanchiere eine Portion Nudeln in einem Sieb 10 bis 20 Sekunden, bis sie weich, glatt und etwas durchscheinend sind. Schüttle das Wasser gut ab und gib die Nudeln sofort in eine vorgewärmte Schüssel. Mehrere Portionen nacheinander arbeiten, damit die Nudeln nicht zusammenkleben und die Schüsseln nicht erkalten.","dauer":5,"tipp":"Wärme die Schüsseln mit heißem Wasser vor; kalte Keramik kühlt die Brühe sofort ab."},{"titel":"Schüsseln bauen und servieren","aktion":"anrichten","text":"Lege auf die Nudeln das gekochte Fleisch und zuletzt das rohe Rind, dazu Sehnenstücke, Zwiebelringe, Frühlingszwiebeln und Koriander. Bringe die Brühe in einem Topf erneut zum kräftigen Kochen; sie muss wirklich sprudeln, damit sie das rohe Fleisch gar zieht. Schöpfe sie sofort in die Schüsseln, bis alles bedeckt ist: Das Rind wird in Sekunden von rosa zu hellbraun-rosa. Gib frisch gemahlenen Pfeffer darüber und serviere sofort, getrennt davon Limette, Chili, Sprossen und Kräuter. Am Tisch presst jeder Gast Limette hinein und isst Fleisch und Nudeln zuerst, bevor er die Brühe trinkt.","dauer":0,"tipp":"In Hanoi gibt es kein Hoisin in der Schüssel; die Brühe soll für sich stehen. Soßen gehören in kleine Extraschalen zum Dippen."}],"profitipps":["Klarheit entsteht durch drei Dinge: Knochen wässern, hart vorkochen und gründlich spülen, danach nur noch leise simmern. Nie stark kochen lassen.","Ungeschälte Zwiebeln und Ingwer anzurösten bringt Süße und Rauch; nur die Außenhaut verkohlen lassen, nichts davon im Topf lassen.","Das Fleisch nach dem Garen kurz in kaltes Wasser legen, so bleibt es hell und saftig.","Brühe leicht überwürzen, weil Nudeln und Beilagen ungewürzt sind.","Brühe über Nacht kühlen und entfetten; das Fett lässt sich dann sauber abheben und der Geschmack setzt sich.","Das rohe Fleisch nur mit wirklich sprudelnd heißer Brühe übergießen, sonst bleibt es roh und schmeckt fad."],"varianten":["Phở bò chín (Hanoi): nur gegartes Fleisch, ohne rohe Scheiben","Phở tái: rohes Rindfleisch, das in der Schüssel gar zieht","Phở nam (Süden): mit Hoisinsauce, Sriracha und viel Kräutern am Tisch","Phở gà: Hühnerbrühe statt Rind (siehe eigenes Rezept)"],"beilagen":["Kräuterteller mit Basilikum, Sägekoriander, Sprossen","Limettenspalten und Chili","Quẩy (frittierte Teigstangen) zum Tunken, wie in Hanoi üblich"],"getraenk":"Eistee, Jasmintee oder ein leichtes helles Bier (z. B. Bia Hà Nội, Pils)","koeche":[{"name":"Andrea Nguyen","bezug":"Beschreibt in ihrem Phở-Rezept eine heimtaugliche Methode: Knochen kurz vorkochen und spülen, Zwiebel und Ingwer anrösten, mit Sternanis, Nelken und Zimt etwa 3 Stunden köcheln und die Brühe zum Entfetten über Nacht kühlen; die Brühe soll etwas kräftiger gewürzt sein, weil Nudeln und Beilagen ungesalzen sind.","quelle":"https://www.vietworldkitchen.com/wprm_print/beef-pho-pho-bo"},{"name":"Luke Nguyen","bezug":"Seine Hanoi-Phở stammt aus der Familienküche (Eltern führten ein Phở-Restaurant in Cabramatta): Ochsenschwanz und Brisket, Aromaten etwa 15 Minuten angegrillt, Gewürze einzeln trocken geröstet und im Mulltuch mitgegart, etwa 3 Stunden Garzeit.","quelle":"https://www.sbs.com.au/food/recipes/vietnamese-beef-pho"}],"quellen":[{"titel":"Beef Pho (Phở Bò) – Andrea Nguyen, Viet World Kitchen","url":"https://www.vietworldkitchen.com/wprm_print/beef-pho-pho-bo"},{"titel":"Vietnamese beef pho – Luke Nguyen, SBS Food","url":"https://www.sbs.com.au/food/recipes/vietnamese-beef-pho"},{"titel":"Pho Bo: Vietnamese Beef Noodle Soup – Cook's Gazette","url":"https://cooksgazette.com/?p=3797"},{"titel":"22 Vietnamese noodle soups named among world's best by TasteAtlas – VOV","url":"https://vov.gov.vn/22-vietnamese-noodle-soups-named-among-worlds-best-by-tasteatlas-dtnew-1096974"},{"titel":"TasteAtlas picks out seven Vietnamese dishes among Top 100 Asian foods – VOV","url":"https://vov.gov.vn/tasteatlas-picks-out-seven-vietnamese-dishes-among-top-100-asian-foods-dtnew-1079501"}],"bild":"ramen","farben":["#8b5a2b","#e8d5a8","#5b8a3c"],"schlagworte":["Nationalgericht","Nudelsuppe","Frühstück","Brühe","Rind"],"vegetarisch_moeglich":false},{"id":"vietnam-banh-mi","name":"Bánh Mì","originalname":"Bánh mì thịt nướng","kueche":"vietnam","region":"Saigon / Südvietnam (landesweit verbreitet)","beliebtheit":94,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"snack","kurz":"Das vietnamesische Baguette-Sandwich: knusprige Kruste, luftiges Inneres, gegrilltes Zitronengras-Schwein, Pastete, süßsauer eingelegtes Gemüse, Koriander und ein Hauch Chili.","hintergrund":"Bánh mì bedeutet schlicht „Brot“ und bezeichnet in Vietnam das aus der französischen Kolonialzeit übernommene Baguette, das dort mit Reismehl leichter und knuspriger gebacken wird. Aus dem Brot mit Butter und Pastete wurde in Saigon im 20. Jahrhundert ein eigenständiges Sandwich, das mit vietnamesischen Zutaten gefüllt wird: Schweinefleisch, Wurst, Pastete, Gurke, Koriander, eingelegte Möhren und Rettich, Chili und eine Würze aus Sojasauce oder Maggi. Im TasteAtlas-Ranking der besten Gerichte Asiens erscheint Bánh mì thịt auf Platz 41. Die Füllungen sind regional sehr verschieden; die Grundidee bleibt der Gegensatz aus Fett, Salz, Süße, Säure und Frische in einem Bissen.","portionen":4,"zeit":{"vorbereitung":45,"garen":15,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Fleisch","liste":[{"menge":400,"einheit":"g","name":"Schweinenacken (ohne Knochen), in 4–5 mm dicke Scheiben geschnitten","hinweis":"Nackenscheiben vom Metzger oder Schweinebauch"},{"menge":2,"einheit":"Stange","name":"Zitronengras, nur der weiße untere Teil, sehr fein gehackt","hinweis":"ersatzweise Zitronengraspaste"},{"menge":2,"einheit":"Stück","name":"Schalotten, fein gehackt","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":2,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1.5,"einheit":"EL","name":"Zucker","hinweis":"für schöne Karamellisierung am Grill"},{"menge":1,"einheit":"EL","name":"helle Sojasauce","hinweis":""},{"menge":1,"einheit":"EL","name":"neutrales Öl","hinweis":""},{"menge":0.5,"einheit":"TL","name":"frisch gemahlener schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Für die eingelegten Möhren und Rettich (Đồ chua)","liste":[{"menge":150,"einheit":"g","name":"Möhren, in feine Streifen geschnitten","hinweis":""},{"menge":150,"einheit":"g","name":"Daikon (weißer Rettich), in feine Streifen geschnitten","hinweis":"ersatzweise Mairübe oder milder weißer Rettich"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":"zum Entwässern"},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":"zum Entwässern"},{"menge":120,"einheit":"ml","name":"Reisessig oder milder Weißweinessig","hinweis":""},{"menge":120,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":"für die Lake"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":"für die Lake"}]},{"gruppe":"Mayonnaise und Aufstrich","liste":[{"menge":1,"einheit":"Stück","name":"sehr frisches Eigelb","hinweis":""},{"menge":120,"einheit":"ml","name":"neutrales Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Zitronensaft","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Dijon-Senf","hinweis":"stabilisiert die Emulsion"},{"menge":80,"einheit":"g","name":"Leberpastete oder feine Leberwurst","hinweis":"alternativ Hühnerleberpastete"}]},{"gruppe":"Zum Füllen","liste":[{"menge":4,"einheit":"Stück","name":"kleine, sehr knusprige Baguettebrötchen (ca. 20 cm)","hinweis":"oder 2 Baguettes, halbiert; Reismehl-Baguette aus dem Asialaden ist ideal"},{"menge":0.5,"einheit":"Stück","name":"Salatgurke, in lange Streifen","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander, mit Stielen","hinweis":""},{"menge":2,"einheit":"Stück","name":"rote Chilischoten, in feinen Ringen","hinweis":""},{"menge":2,"einheit":"Stück","name":"Frühlingszwiebeln, in Streifen","hinweis":""},{"menge":null,"einheit":"","name":"Maggi-Würze oder helle Sojasauce","hinweis":"einige Tropfen"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"zum Beträufeln"}]}],"ausruestung":["Grillpfanne oder Holzkohlegrill","Schneebesen oder Stabmixer","Backblech","scharfes Messer","Einmachglas für die Pickles"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Lege alle Zutaten auf der Arbeitsfläche bereit, denn die einzelnen Komponenten werden zeitversetzt zubereitet und am Ende in Sekunden zusammengebaut. Schneide Möhren und Rettich in 5 cm lange, 3 mm dicke Streifen; gleichmäßige Größe sorgt dafür, dass das Gemüse gleichzeitig durchzieht. Hacke Zitronengras (nur die weiche Mitte), Schalotten und Knoblauch fein, damit die Marinade das Fleisch durchdringt. Nimm das Eigelb für die Mayonnaise aus dem Kühlschrank, damit es Raumtemperatur annimmt und besser bindet.","dauer":0,"tipp":"Von Zitronengras nur den unteren, hellen Teil verwenden, die grünen Blätter sind faserig und bitter."},{"titel":"Đồ chua ansetzen","aktion":"einlegen","text":"Vermenge Möhren und Rettich in einer Schüssel mit Salz und 1 EL Zucker und knete sie mit den Händen etwa 3 Minuten, bis sie Wasser abgeben und biegsam werden. Spüle sie kurz ab und drücke sie gut trocken. Rühre Essig, Wasser, 3 EL Zucker und 1 TL Salz bis zum Auflösen, gib das Gemüse in ein Glas und gieße die Lake darüber, sodass alles bedeckt ist. Lass es mindestens 1 Stunde bei Raumtemperatur ziehen; über Nacht im Kühlschrank wird der Geschmack runder. Das Gemüse soll knackig, süßsauer und leicht transparent sein, kein Weichgemüse.","dauer":60,"tipp":"Die Pickles halten sich im Kühlschrank mehrere Wochen und sind auch für andere Gerichte (Bún, Cơm) nützlich."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Vermische Zitronengras, Schalotten, Knoblauch, Fischsauce, Zucker, Sojasauce, Öl und Pfeffer zu einer feuchten Paste und knete sie in die Schweinenackenscheiben, bis jedes Stück rundum bedeckt ist. Der Zucker sorgt später für eine glänzende, leicht karamellisierte Kruste; die Fischsauce würzt tief ins Fleisch. Decke die Schüssel ab und lass das Fleisch mindestens 1 Stunde im Kühlschrank durchziehen, besser 3 bis 4 Stunden. Nimm es 20 Minuten vor dem Braten heraus, damit es nicht eiskalt auf die heiße Fläche kommt.","dauer":60,"tipp":"Längeres Marinieren als 12 Stunden macht das Fleisch durch die Fischsauce zu salzig und trocken."},{"titel":"Mayonnaise aufschlagen","aktion":"aufschlagen","text":"Gib Eigelb, Zitronensaft, Senf und eine Prise Salz in eine Schüssel und verrühre alles kräftig. Träufle das Öl zunächst tropfenweise, dann in dünnem Faden unter ständigem Schlagen dazu, bis die Masse dick und glänzend ist. Fällt sie in sich zusammen, gib 1 TL Wasser zu und rühre weiter. Schmecke mit Salz und einigen Tropfen Zitrone ab. Wer es eilig hat, nimmt fertige Mayonnaise mit hoher Fettstufe; Light-Mayo ist zu dünn und zu sauer für dieses Sandwich.","dauer":10,"tipp":"Alle Zutaten sollten Zimmertemperatur haben, sonst gerinnt die Emulsion leichter."},{"titel":"Fleisch grillen","aktion":"grillen","text":"Erhitze eine Grillpfanne oder den Holzkohlegrill, bis die Fläche sehr heiß ist (ca. 220 °C), und tupfe überschüssige Marinade vom Fleisch ab, damit Knoblauch und Zucker nicht sofort verbrennen. Lege die Scheiben ohne Gedränge auf den Rost und lass sie 2 bis 3 Minuten pro Seite braten, bis sie schöne dunkle Grillstreifen haben und am Rand leicht karamellisieren. Es duftet nach Zitronengras und geröstetem Zucker. Lass das Fleisch 3 Minuten ruhen und schneide es in mundgerechte Streifen. Es soll innen durchgegart, aber saftig sein.","dauer":10,"tipp":"Bei Pfanne statt Grill: große Pfanne sehr heiß vorheizen und das Fleisch in zwei Durchgängen braten, damit es nicht kocht."},{"titel":"Baguette knusprig backen","aktion":"backen","text":"Heize den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor und backe die Brötchen oder Baguettestücke 3 bis 5 Minuten, bis die Kruste hörbar knackt und leicht gebräunt ist. Das Innere soll weich und luftig bleiben, die Kruste dünn und splitternd. Schneide sie seitlich auf, ohne ganz durchzuschneiden, und drücke bei Bedarf etwas Krume heraus, damit mehr Füllung hineinpasst. Bestreiche die untere Hälfte mit Pastete, die obere mit Mayonnaise: Fett schützt das Brot davor, von der Füllung durchzuweichen.","dauer":5,"tipp":"Das vietnamesische Baguette wird mit etwas Reismehl gebacken und ist dadurch leichter; in Deutschland funktionieren helle, dünnwandige Baguettes am besten."},{"titel":"Frische Zutaten schneiden","aktion":"schneiden","text":"Halbiere die Gurke längs, schneide sie in 10 cm lange, fingerdicke Streifen und tupfe sie trocken. Zupfe den Koriander in kleine Büschel, hacke die Stiele nicht, sie sind das Aroma. Schneide Chilis in feine Ringe und Frühlingszwiebeln in dünne Streifen. Lass die Pickles abtropfen, damit keine Lake ins Brot läuft. Die Zutaten sollen rund, knackig und trocken sein, damit das Sandwich nicht durchweicht.","dauer":0,"tipp":""},{"titel":"Sandwich zusammenbauen","aktion":"schichten","text":"Schichte auf die mit Pastete bestrichene Brothälfte zuerst das warme Fleisch, dann Gurke, Pickles, Koriander, Frühlingszwiebel und Chili. Träufle einige Tropfen Maggi oder Sojasauce und etwas Limettensaft darüber; dieser Hauch Umami und Säure bringt alles zusammen. Klappe das Brot zu, drücke leicht an, damit die Füllung hält, und serviere sofort. Das Sandwich sollte warm, knusprig, fettig, süßsauer und frisch zugleich sein; wer den Kontrast schätzt, isst es innerhalb von Minuten.","dauer":0,"tipp":"Wenig Mayonnaise reicht; sie soll verbinden, nicht dominieren."}],"profitipps":["Die Kruste ist das Rückgrat: Brot kurz im heißen Ofen aufbacken, bis es knackt.","Pickles immer erst salzen und kneten, dann in Lake legen – so bleiben sie knackig statt weich.","Fett (Pastete, Mayo) auf beide Brothälften verhindert, dass das Brot durchweicht.","Kontrast ist alles: warm und kalt, fettig und sauer, weich und knusprig.","Koriander mit Stielen verwenden, die Stiele tragen das Aroma.","Chili sparsam einsetzen und erst am Tisch nachlegen."],"varianten":["Bánh mì chả lụa: mit vietnamesischer Schweinewurst und Pastete","Bánh mì thịt nguội: mit Aufschnitt, Schinken und Pastete (Klassiker aus Saigon)","Bánh mì gà: mit Hühnchen","Bánh mì chay: mit Tofu und Pilzen (vegetarisch)"],"beilagen":["Eistee oder Zitronenlimonade","Gurken-Chili-Salat","Hühnerbrühe oder Phở als Mittagessen"],"getraenk":"Vietnamesischer Eiskaffee (Cà phê sữa đá) oder ein leichtes Pils","koeche":[{"name":"Andrea Nguyen","bezug":"Hat dem Sandwich ein ganzes Buch gewidmet: „The Banh Mi Handbook“ (Ten Speed Press, 2014) mit über fünfzig Rezepten; das Buch umfasst auch Rezepte für Pickles und Aufstriche.","quelle":"https://www.penguinrandomhouse.com/books/225437/the-banh-mi-handbook-by-andrea-nguyen/"},{"name":"Luke Nguyen","bezug":"Zeigt in seiner SBS-Serie ein Bánh mì mit selbst gemachter Schweinepastete (Chả lụa) im Bananenblatt, gefüllt mit Gurke, Koriander, Frühlingszwiebel und Chili.","quelle":"https://www.sbs.com.au/food/recipes/pork-terrine-baguette-banh-mi-cha-lua"}],"quellen":[{"titel":"The Banh Mi Handbook – Andrea Nguyen, Penguin Random House","url":"https://www.penguinrandomhouse.com/books/225437/the-banh-mi-handbook-by-andrea-nguyen/"},{"titel":"Banh Mi – Culinary Anthropologist","url":"https://www.culinaryanthropologist.org/banh-mi/"},{"titel":"Pork terrine baguette (Banh mi cha lua) – Luke Nguyen, SBS Food","url":"https://www.sbs.com.au/food/recipes/pork-terrine-baguette-banh-mi-cha-lua"},{"titel":"TasteAtlas picks out seven Vietnamese dishes among Top 100 Asian foods – VOV","url":"https://vov.gov.vn/tasteatlas-picks-out-seven-vietnamese-dishes-among-top-100-asian-foods-dtnew-1079501"}],"bild":"sandwich","farben":["#d9a45b","#7a4b2a","#6fa04b"],"schlagworte":["Streetfood","Sandwich","Saigon","Baguette","Kolonialerbe"],"vegetarisch_moeglich":true},{"id":"vietnam-goi-cuon","name":"Gỏi Cuốn (Sommerrollen)","originalname":"Gỏi cuốn","kueche":"vietnam","region":"Südvietnam / Saigon (landesweit verbreitet)","beliebtheit":92,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"vorspeise","kurz":"Durchsichtige, frische Reispapierrollen mit Garnele, zartem Schweinefleisch, Reisnudeln, Salat und viel frischen Kräutern – dazu eine cremige Erdnuss-Hoisin-Sauce.","hintergrund":"Gỏi cuốn heißt wörtlich „Salat-Rolle“ und wird regional auch „Nem cuốn“ genannt. Das Gericht ist ein Beispiel für die Vorliebe der vietnamesischen Küche für frische Kräuter und für Speisen zum Selbstrollen: Man isst es kalt oder bei Zimmertemperatur, ohne Frittieren, oft als leichte Vorspeise oder Snack. Typisch sind Schweinefleisch, Garnele, Reisvermicelli (Bún), Salat, Minze, Koriander und Thai-Basilikum, dazu eine Dip-Sauce aus Hoisin und Erdnüssen oder die klassische Nước chấm. Im Ausland ist es zur Ikone der vietnamesischen Küche geworden, weil es leicht, frisch und optisch ansprechend ist. Beim Rollen gilt der Grundsatz, dass das Papier nur kurz benetzt wird und beim Rollen weiter weich wird.","portionen":4,"zeit":{"vorbereitung":60,"garen":25,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Rollen (12 Stück)","liste":[{"menge":12,"einheit":"Stück","name":"Reispapier (Bánh tráng), rund, ca. 22 cm","hinweis":"im Asialaden; dünnes Papier ohne Tapiokaanteil lässt sich leichter rollen"},{"menge":150,"einheit":"g","name":"Reisvermicelli (Bún), dünn","hinweis":""},{"menge":280,"einheit":"g","name":"Schweinenacken oder magerer Schweinebauch am Stück","hinweis":""},{"menge":18,"einheit":"Stück","name":"mittelgroße bis große Garnelen, geschält","hinweis":"mit oder ohne Schwanz, Darm entfernt"},{"menge":12,"einheit":"Blatt","name":"Blattsalat (Eichblatt oder Kopfsalat), dicke Rippen entfernt","hinweis":""},{"menge":1,"einheit":"Bund","name":"Minze, Blätter gezupft","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander, Blätter gezupft","hinweis":""},{"menge":1,"einheit":"Bund","name":"Thai-Basilikum, Blätter gezupft","hinweis":""},{"menge":12,"einheit":"Stück","name":"lange Halme Knoblauchschnittlauch oder Schnittlauch","hinweis":"optional, ragt als Dekoration aus der Rolle"},{"menge":1,"einheit":"Handvoll","name":"Mungobohnensprossen","hinweis":"optional"},{"menge":null,"einheit":"","name":"Salz","hinweis":"für Kochwasser"}]},{"gruppe":"Für die Erdnuss-Hoisin-Sauce","liste":[{"menge":3,"einheit":"EL","name":"cremige Erdnussbutter (ungesüßt)","hinweis":""},{"menge":3,"einheit":"EL","name":"Hoisinsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":1,"einheit":"TL","name":"Reisessig oder weißer Essig","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch, fein gerieben","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Chilischote, fein gehackt","hinweis":"optional"},{"menge":150,"einheit":"ml","name":"Wasser","hinweis":"nach Bedarf anpassen"},{"menge":1,"einheit":"EL","name":"geröstete Erdnüsse, grob gehackt","hinweis":"zum Bestreuen"}]}],"ausruestung":["Topf für Schweinefleisch und Nudeln","flache Schale mit lauwarmem Wasser für das Reispapier","Kunststoff- oder Holzbrett (nicht Holz mit Maserung)","feuchtes Küchentuch","scharfes Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Sommerrollen gelingen nur, wenn alles griffbereit liegt, bevor das erste Reispapier nass wird. Wasche Salat und Kräuter, schüttle sie trocken und tupfe sie mit einem Tuch ab, denn Wasser auf den Blättern macht das Reispapier rutschig und lässt die Rollen reißen. Zupfe die Kräuterblätter von den Stielen und trenne Salat in handgroße Stücke ohne Rippen. Lege die Garnelen vor dich, entferne bei Bedarf den Darm und stelle einen Topf mit Salzwasser bereit. Die Arbeitsfläche sollte glatt und trocken sein, am besten ein Brett aus Kunststoff.","dauer":0,"tipp":"Zeichne in Gedanken eine Linie: links Papier, in der Mitte die Füllung, rechts die fertigen Rollen – so geht das Rollen später im Fluss."},{"titel":"Nudeln garen","aktion":"kochen","text":"Übergieße die Reisvermicelli in einer Schüssel mit kochendem Wasser und lass sie 6 bis 8 Minuten ziehen, bis sie weich, aber noch leicht elastisch sind. Gieße sie ab und spüle sie unter kaltem Wasser, bis sie vollständig abgekühlt sind; das stoppt das Garen und löst überschüssige Stärke, die sonst verklebt. Lass sie gut abtropfen und teile sie mit den Fingern in lockere Nester, damit sich später Portionen leicht nehmen lassen. Feuchte, aber nicht nasse Nudeln sind ideal.","dauer":8,"tipp":"Gut abgetropfte Nudeln verhindern, dass das Reispapier von innen durchweicht."},{"titel":"Schweinefleisch garen","aktion":"koecheln","text":"Lege das Schweinefleisch in einen Topf, bedecke es mit kaltem Wasser, füge 1 TL Salz hinzu und bringe es langsam zum Kochen. Reduziere dann auf leises Simmern und gare es 20 bis 25 Minuten, bis die Kerntemperatur etwa 65 bis 70 °C erreicht; der austretende Saft soll klar sein. Nimm das Fleisch heraus, lass es 10 Minuten ruhen und schneide es quer zur Faser in dünne, etwa 3 mm starke Scheiben. Das Kochwasser kannst du für eine Suppe aufbewahren. Schnitte, die zu dick sind, lassen sich nicht sauber einrollen.","dauer":25,"tipp":"Fleisch in kaltem Wasser anzusetzen sorgt für ein gleichmäßigeres Garen und zartere Scheiben."},{"titel":"Garnelen pochieren","aktion":"blanchieren","text":"Bringe frisches Salzwasser zum Kochen, nimm den Topf vom Herd und gib die Garnelen hinein. Lass sie ca. 3 Minuten ziehen, bis sie überall rosa und fest, aber nicht gummiartig sind. Schrecke sie sofort in Eiswasser ab, damit sie nicht nachgaren und saftig bleiben. Tupfe sie trocken und halbiere sie längs; so sind sie flach, sehen im durchsichtigen Papier schön aus und rollen sich leichter. Zu stark gegarte Garnelen schmecken fad und zäh.","dauer":5,"tipp":"Halbiere die Garnelen mit einem scharfen Messer in einem Zug längs und lege sie mit der Schnittseite nach oben, sie schimmern dann schön durch das Papier."},{"titel":"Kräuter und Salat portionieren","aktion":"schneiden","text":"Lege für jede Rolle ein Salatblatt, einige Blätter Minze, Koriander und Thai-Basilikum sowie ein paar Sprossen bereit. Teile die Nudeln in zwölf kleine Portionen und lege sie zusammen mit den Schweinescheiben, Garnelenhälften und Schnittlauchhalmen in Schalen vor dich. Wenn du alles portioniert hast, kannst du zügig rollen, ohne zu suchen. Die Kräuter sind wichtig: Sie machen den Geschmack und sollten großzügig verwendet werden.","dauer":5,"tipp":""},{"titel":"Erdnuss-Hoisin-Sauce anrühren","aktion":"mischen","text":"Zerdrücke Knoblauch und Chili mit einer Prise Salz zu einer Paste, rühre dann Erdnussbutter, Hoisinsauce, Tomatenmark und Essig ein und gib das Wasser nach und nach unter ständigem Rühren dazu. Die Sauce soll cremig sein und vom Löffel fließen, ohne zu tropfen; ist sie zu dick, gib esslöffelweise Wasser dazu. Schmecke mit etwas mehr Essig oder Hoisin ab: süß, salzig, nussig und mit einem Hauch Säure. Streue vor dem Servieren die gehackten Erdnüsse darüber.","dauer":5,"tipp":"Wer nichts von Erdnüssen hält, serviert klassische Nước chấm (Fischsauce, Limette, Zucker, Wasser, Knoblauch, Chili)."},{"titel":"Reispapier befeuchten","aktion":"vorbereiten","text":"Fülle eine flache Schale mit lauwarmem Wasser. Tauche ein Reispapier nur 2 bis 3 Sekunden ein, bis es auf beiden Seiten nass ist, und lege es sofort auf das Brett. Das Papier fühlt sich noch fest an, wird aber in den nächsten Sekunden weich und klebrig; genau so soll es sein. Wenn du es zu lange einweichst, reißt es beim Rollen oder klebt am Brett. Wische überschüssiges Wasser vom Brett ab und halte die Hände leicht feucht.","dauer":0,"tipp":"Immer nur ein Blatt vorbereiten, damit es nicht austrocknet oder verklebt."},{"titel":"Rollen","aktion":"rollen","text":"Lege ein Salatblatt auf das untere Drittel des Reispapiers und belege es mit Nudeln, Minze, Koriander, Basilikum, Sprossen und zwei Scheiben Schweinefleisch. Klappe die untere Kante über die Füllung und rolle einmal fest, dann falte die Seiten ein. Lege auf den noch freien Bereich drei Garnelenhälften mit der Schnittseite nach oben und füge einen Schnittlauchhalm hinzu, sodass er am Ende herausschaut, dann rolle zu einer festen Zigarre. Die Garnelen schimmern später durch das Papier. Lege fertige Rollen nebeneinander und decke sie mit einem feuchten Tuch ab.","dauer":0,"tipp":"Nicht zu viel Füllung: Zu dick gefüllte Rollen platzen. Lieber eine Rolle mehr machen."},{"titel":"Servieren","aktion":"anrichten","text":"Serviere die Rollen sofort, am besten innerhalb von 30 Minuten, oder decke sie mit einem feuchten Tuch und Frischhaltefolie ab und stelle sie bis zu 4 Stunden kühl. Halbiere sie schräg, damit die Füllung sichtbar wird. Reiche die Erdnuss-Hoisin-Sauce und, wenn du magst, Nước chấm zum Dippen. Gäste tauchen die Rolle mit den Fingern in die Sauce und essen sie in zwei bis drei Bissen. Reste halten sich nicht lange: Das Reispapier wird im Kühlschrank hart und zäh.","dauer":0,"tipp":"Rollen nicht einfrieren: Das Reispapier wird beim Auftauen zäh und gummiartig."}],"profitipps":["Reispapier nur 2 bis 3 Sekunden eintauchen; es wird beim Rollen von allein weich.","Nicht auf Holzbrett rollen, es zieht Feuchtigkeit aus dem Papier und das Papier klebt.","Zutaten abtropfen und trockentupfen, sonst reißt das Papier.","Fleisch quer zur Faser dünn schneiden, damit es sich leicht rollen lässt.","Kräuter großzügig einsetzen: Sie sind das Aroma des Gerichts.","Fertige Rollen mit feuchtem Tuch abdecken, damit sie nicht austrocknen."],"varianten":["Gỏi cuốn tôm thịt: klassisch mit Garnele und Schwein","Gỏi cuốn chay: mit Tofu, Pilzen und viel Gemüse (vegetarisch)","Bì cuốn: mit Schweinehaut-Streifen und Fischsauce-Dip","Nem nướng cuốn: mit gegrilltem Schweinefleisch aus Nha Trang"],"beilagen":["Nước chấm als zweite Sauce","gerösteter Sesam oder gehackte Erdnüsse","kalter Reisnudelsalat"],"getraenk":"Eistee, Jasmintee oder trockener Riesling","koeche":[],"quellen":[{"titel":"Vietnamese Summer Rolls (Gỏi Cuốn) – America's Test Kitchen","url":"https://www.americastestkitchen.com/recipes/11899-vietnamese-summer-rolls-goi-cuon"},{"titel":"Vietnamese Summer Rolls (Gỏi Cuốn) – Kitchen Dreaming","url":"https://kitchendreaming.com/vietnamese-summer-rolls-goi-cuon-easy-fresh-spring-rolls/"}],"bild":"wrap","farben":["#f2e8c9","#6fa04b","#e07b53"],"schlagworte":["frisch","Vorspeise","Reispapier","Kräuter","Streetfood"],"vegetarisch_moeglich":true},{"id":"vietnam-cha-gio","name":"Chả Giò (Frittierte Frühlingsrollen)","originalname":"Chả giò / Nem rán","kueche":"vietnam","region":"Südvietnam (im Norden: Nem rán)","beliebtheit":90,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"vorspeise","kurz":"Knusprig-blasige Reispapierrollen mit würziger Schweinefüllung, Glasnudeln, Möhren und Morcheln, in Salat und Kräuter gewickelt und in süßsaure Nước chấm getunkt.","hintergrund":"Im Süden Vietnams heißen sie Chả giò, im Norden Nem rán; gemeint sind frittierte Röllchen aus Reispapier mit einer Füllung aus Schweinehack, Glasnudeln, Möhren und Mu-Err-Pilzen. Anders als die dicken chinesischen Frühlingsrollen mit Weizenteig bekommen sie durch das Reispapier eine feine, blasige, sehr knusprige Kruste. Gegessen werden sie nicht pur: Man wickelt sie in Salatblätter mit Minze, Koriander und Perilla und taucht sie in Nước chấm. Im TasteAtlas-Ranking der besten frittierten Gerichte der Welt kamen die vietnamesischen Frühlingsrollen auf Platz 43 (4,3 von 5 Sternen) und standen zuvor in einer Liste der 100 beliebtesten Vorspeisen weltweit. Im Norden gehören Nem rán traditionell zum Bún chả.","portionen":5,"zeit":{"vorbereitung":60,"garen":30,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Füllung (ca. 20 Rollen)","liste":[{"menge":450,"einheit":"g","name":"Schweinehack (nicht zu mager, ca. 20 % Fett)","hinweis":"gemischtes Hack ist ebenfalls möglich"},{"menge":50,"einheit":"g","name":"Glasnudeln aus Mungobohnenstärke (getrocknet)","hinweis":""},{"menge":30,"einheit":"g","name":"getrocknete Mu-Err-Pilze (Wolkenohrpilze)","hinweis":"ca. 1/3 Tasse eingeweicht und gehackt"},{"menge":2,"einheit":"Stück","name":"mittelgroße Möhren (ca. 190 g), fein gerieben","hinweis":""},{"menge":3,"einheit":"Stück","name":"Schalotten, fein gehackt","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":1,"einheit":"TL","name":"frischer Ingwer, gerieben","hinweis":""},{"menge":1,"einheit":"Stück","name":"Eiweiß","hinweis":"bindet die Füllung"},{"menge":1,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.25,"einheit":"TL","name":"weißer Pfeffer","hinweis":""},{"menge":1,"einheit":"EL","name":"neutrales Öl","hinweis":""}]},{"gruppe":"Zum Rollen und Frittieren","liste":[{"menge":20,"einheit":"Stück","name":"Reispapier (Bánh tráng), rund, ca. 22 cm","hinweis":"gibt es als Reispapier zum Frittieren (Bánh tráng chiên) im Asialaden"},{"menge":2,"einheit":"TL","name":"Zucker, in 300 ml warmem Wasser gelöst","hinweis":"Zuckerwasser fürs Reispapier"},{"menge":1.5,"einheit":"l","name":"neutrales Frittieröl (Erdnuss- oder Rapsöl)","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":1,"einheit":"Stück","name":"grüner Blattsalat","hinweis":"zum Einwickeln"},{"menge":1,"einheit":"Bund","name":"Minze, Koriander oder Thai-Basilikum","hinweis":"gemischt"},{"menge":3,"einheit":"EL","name":"Limettensaft","hinweis":"für die Nước chấm"},{"menge":2.5,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":60,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Vogelaugen-Chili, fein gehackt","hinweis":"optional"}]}],"ausruestung":["Wok oder hoher Topf zum Frittieren","Fett-/Frittierthermometer","Abtropfgitter oder Küchenpapier","flache Schale für Zuckerwasser","Teller oder Brett zum Rollen"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Hack und Gemüse ab und stelle Schalen für alle Komponenten bereit. Das Frittieren geht schnell und verträgt keine Unterbrechungen. Lege den Frittiertopf, Thermometer, Abtropfgitter und eine Schale mit Zuckerwasser vorab hin. Reibe die Möhren fein, hacke Schalotten und Knoblauch sehr klein und halte Eiweiß und Gewürze bereit. Jede Zutat muss fein sein, damit die Füllung kompakt bleibt und die Rollen später nicht reißen. Stelle auch ein Tablett mit Backpapier für die fertigen Rollen bereit.","dauer":0,"tipp":"Fülle Zucker und Wasser in eine flache Schale, damit sich das Reispapier später leicht eintauchen lässt."},{"titel":"Glasnudeln und Pilze einweichen","aktion":"einlegen","text":"Lege die Glasnudeln 30 Minuten in lauwarmes Wasser, bis sie glasig und biegsam sind, und schneide sie danach mit der Schere in etwa 1,5 cm lange Stücke. Weiche die Mu-Err-Pilze in heißem Wasser 20 bis 30 Minuten ein, bis sie auf ein Vielfaches gequollen sind, schneide harte Ansätze weg und hacke sie sehr fein. Drücke beides gut aus, denn jede Restfeuchte macht die Füllung nass und lässt die Rollen beim Frittieren spritzen. Die Nudeln sollen die Füllung auflockern, die Pilze liefern Biss.","dauer":30,"tipp":"Glasnudeln aus Mungbohnenstärke verwenden; Sorten aus Kartoffel- oder Süßkartoffelstärke zerfallen beim Frittieren."},{"titel":"Füllung mischen","aktion":"mischen","text":"Gib Hack, Glasnudeln, Pilze, Möhren, Schalotten, Knoblauch, Ingwer, Eiweiß, Fischsauce, Zucker, Salz, Pfeffer und Öl in eine große Schüssel und knete alles mit der Hand 2 bis 3 Minuten kräftig durch, bis sich eine klebrige, homogene Masse bildet. Das Kneten löst Eiweiß aus dem Fleisch, das die Füllung beim Frittieren zusammenhält. Die Masse darf nicht trocken wirken; sie soll leicht an den Fingern haften. Teile sie in 20 gleich große Portionen zu je etwa 40 g.","dauer":5,"tipp":"Brate ein kleines Probestück in der Pfanne an und schmecke ab; die Füllung darf kräftig gewürzt sein, weil später in Salat und Dip gedippt wird."},{"titel":"Reispapier befeuchten","aktion":"vorbereiten","text":"Tauche ein Reispapier 5 bis 10 Sekunden in das Zuckerwasser, bis es biegsam, aber noch nicht schlaff ist, und lege es auf ein glattes Brett. Der Zucker sorgt später für eine goldbraune Farbe und macht die Oberfläche blasig und knusprig. Das Papier wird nach wenigen Sekunden weicher; nicht zu lange eintauchen, sonst reißt es beim Rollen. Tupfe überschüssiges Wasser am Rand ab. Weil das Papier schnell trocknet, arbeite immer nur mit einem Blatt.","dauer":0,"tipp":"Überschüssiges Wasser auf dem Papier lässt das Öl beim Frittieren heftig spritzen."},{"titel":"Füllen und rollen","aktion":"rollen","text":"Forme eine Portion Füllung zu einer Wurst und lege sie ans untere Drittel des Papiers. Klappe die untere Kante über die Füllung, rolle eine volle Umdrehung und drücke Lufttaschen heraus. Falte die Seiten ein und rolle fest zu Ende; das Papier klebt von selbst, wenn es noch leicht feucht ist. Die Rollen sollen fest, aber nicht prall gefüllt sein, denn die Füllung dehnt sich beim Garen aus. Lege fertige Rollen mit Abstand nebeneinander, damit sie nicht aneinanderkleben.","dauer":20,"tipp":"Nicht überfüllen: Zu viel Füllung lässt die Rollen beim Frittieren platzen."},{"titel":"Rollen kühlen","aktion":"kuehlen","text":"Stelle die Rollen auf einem Tablett, locker abgedeckt, mindestens 1 Stunde in den Kühlschrank. Dabei trocknet das Papier an der Oberfläche leicht an, die Rolle festigt sich und platzt später beim Frittieren seltener. Nimm sie 15 Minuten vor dem Frittieren heraus, damit sie nicht eiskalt ins Öl kommen und die Temperatur zu stark abfällt. Wer vorbereiten möchte, kann die Rollen auch einfrieren und direkt aus dem Gefrierfach frittieren, mit etwa 1 Minute mehr Garzeit.","dauer":60,"tipp":"Zum Einfrieren erst auf einem Tablett vorfrieren, dann umfüllen, sonst kleben die Rollen zusammen."},{"titel":"Nước chấm anrühren","aktion":"mischen","text":"Rühre Zucker, Fischsauce, Limettensaft und Wasser in einer Schale, bis sich der Zucker vollständig löst, und gib Knoblauch und Chili hinein. Probiere: Die Sauce soll gleichzeitig süß, sauer, salzig und leicht scharf schmecken, wobei keine Note dominiert. Ist sie zu salzig, gib etwas Wasser dazu; ist sie zu süß, mehr Limette. Lass sie bis zum Servieren ziehen, damit die Aromen sich verbinden.","dauer":5,"tipp":"Frische Limette statt Zitrone verwenden; Limette gibt das typische Aroma."},{"titel":"Erstes Frittieren","aktion":"frittieren","text":"Erhitze das Öl in einem Wok oder hohen Topf auf 170 °C. Gib 3 bis 4 Rollen vorsichtig hinein und frittiere sie 5 bis 6 Minuten, bis sie hellgolden sind, und wende sie dabei gelegentlich. Drängele nicht, sonst fällt die Öltemperatur ab und die Rollen saugen Fett. Hebe sie mit einer Spinne heraus und lass sie auf einem Gitter abtropfen. In dieser ersten Phase gart die Füllung durch; die Kruste soll noch nicht dunkel sein.","dauer":20,"tipp":"Reißt das Reispapier oder zerfällt es, ist das Öl zu heiß oder die Rolle zu nass."},{"titel":"Zweites Frittieren und Servieren","aktion":"frittieren","text":"Erhitze das Öl auf 175 °C und frittiere alle Rollen kurz vor dem Servieren nochmals 1,5 bis 2 Minuten, bis sie tief goldbraun und krustig sind. Dieses doppelte Frittieren entzieht die restliche Feuchtigkeit und sorgt für die typische blasige, laut knackende Kruste, die auch nach einigen Minuten knusprig bleibt. Lass sie kurz abtropfen und serviere sie mit Salat, Kräutern und Nước chấm. Zum Essen wickelt man die Rolle in ein Salatblatt mit Kräutern und taucht sie in den Dip.","dauer":5,"tipp":"Beim Aufschneiden dürfen die Rollen dampfen: Die Füllung soll saftig, aber nicht flüssig sein."}],"profitipps":["Doppelt frittieren: erst bei 170 °C durchgaren, dann bei 175 °C knusprig bräunen.","Zuckerwasser statt klarem Wasser für das Reispapier: es bräunt schöner und macht die Oberfläche blasig.","Füllung gründlich kneten, damit sie zusammenhält und nicht zerfällt.","Rollen vor dem Frittieren kühlen und nicht überfüllen.","Frittieröl nicht zu heiß werden lassen: Reispapier verbrennt schneller als Weizenteig.","Mit Salat und Kräutern einwickeln: Die Frische balanciert das frittierte Fett."],"varianten":["Nem rán (Nordvietnam): regionale Version mit leicht anderer Füllung, klassische Beilage zu Bún chả","Chả giò chay: vegetarisch mit Taro, Möhren, Pilzen und Tofu","Chả giò tôm: mit Garnelen statt Hack","Mit Weizenteigblättern (Frühlingsrollenteig): einfacher zu rollen, aber glatter und weniger blasig"],"beilagen":["Nước chấm","Bún chả oder Reisnudelsalat (Bún)","Salat und Kräuterteller"],"getraenk":"Leichtes Pils oder Eistee","koeche":[],"quellen":[{"titel":"Cha Gio (Vietnamese Fried Spring Rolls) – The Woks of Life","url":"https://thewoksoflife.com/wprm_print/cha-gio-vietnamese-fried-spring-rolls"},{"titel":"Easy Vietnamese Fried Spring Rolls – Cha Gio – Wandercooks","url":"https://www.wandercooks.com/?p=2960"},{"titel":"TasteAtlas praises Vietnamese spring rolls on global list of best fried-dishes – VOV","url":"https://vov.gov.vn/tasteatlas-praises-vietnamese-spring-rolls-on-global-list-of-best-fried-dishes-dtnew-1061457"}],"bild":"teller","farben":["#c8742a","#f0c36a","#6fa04b"],"schlagworte":["frittiert","Vorspeise","Streetfood","Party"],"vegetarisch_moeglich":true},{"id":"vietnam-bun-cha","name":"Bún Chả","originalname":"Bún chả Hà Nội","kueche":"vietnam","region":"Hanoi / Nordvietnam","beliebtheit":88,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Hanois berühmtes Mittagessen: über Holzkohle gegrillte Schweinefleischbällchen und Bauchscheiben, die in einer warmen, süßsauren Fischsaucenbrühe schwimmen, dazu Reisnudeln und ein Berg frischer Kräuter.","hintergrund":"Bún chả gilt als das Mittagsgericht Hanois: An den Straßenecken der Altstadt steigt ab Vormittag Rauch von kleinen Holzkohlegrills auf, auf denen Fleischbällchen (chả viên) und dünne Bauchscheiben (chả miếng) braun werden. Das Fleisch wird zusammen mit der warmen Dip-Sauce in einer Schale serviert; getrennt dazu gibt es Reisnudeln (bún), Salat und Kräuter, die jeder nach Belieben hineinstippt. Typisch ist die Beilage Nem rán (frittierte Frühlingsrollen). Das Gericht erlangte weltweite Bekanntheit, als der damalige US-Präsident Barack Obama 2016 in Hanoi mit Anthony Bourdain Bún chả aß. Im TasteAtlas-Ranking der besten Nudelgerichte der Welt steht Bún chả auf Platz 12.","portionen":4,"zeit":{"vorbereitung":50,"garen":20,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Fleischbällchen (Chả viên)","liste":[{"menge":400,"einheit":"g","name":"Schweinehack (nicht zu mager, ca. 20 % Fett)","hinweis":"ideal vom Nacken oder Schulter, selbst gewolft"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"bindet das Hack"},{"menge":2,"einheit":"Stück","name":"Schalotten, sehr fein gehackt","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":3,"einheit":"Stück","name":"Frühlingszwiebeln, fein geschnitten","hinweis":""},{"menge":1,"einheit":"Bund","name":"Knoblauchschnittlauch (Hẹ), fein geschnitten","hinweis":"ersatzweise Schnittlauch"}]},{"gruppe":"Für die Bauchscheiben (Chả miếng)","liste":[{"menge":400,"einheit":"g","name":"Schweinebauch ohne Schwarte, in 3 mm dünne Scheiben geschnitten","hinweis":"beim Metzger auf der Aufschnittmaschine schneiden lassen; angefroren lässt er sich leichter schneiden"}]},{"gruppe":"Marinade (für beide Fleischsorten)","liste":[{"menge":4,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Austernsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"dunkle Sojasauce","hinweis":"für Farbe"},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer, frisch gemahlen","hinweis":""},{"menge":1,"einheit":"EL","name":"neutrales Öl","hinweis":""}]},{"gruppe":"Für die Nước chấm (Dip-Brühe)","liste":[{"menge":50,"einheit":"ml","name":"Fischsauce","hinweis":""},{"menge":50,"einheit":"ml","name":"Reisessig","hinweis":""},{"menge":30,"einheit":"g","name":"Zucker","hinweis":""},{"menge":200,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":50,"einheit":"ml","name":"Limettensaft","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch, gehackt","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Chilischote, in Ringen","hinweis":""},{"menge":40,"einheit":"g","name":"Möhre, in dünne Scheiben oder Streifen","hinweis":""},{"menge":40,"einheit":"g","name":"grüne Papaya oder Kohlrabi, in dünne Streifen","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":400,"einheit":"g","name":"Reisvermicelli (Bún), frisch oder getrocknet","hinweis":""},{"menge":1,"einheit":"Stück","name":"Salatherz oder Kopfsalat","hinweis":""},{"menge":1,"einheit":"Bund","name":"Minze, Koriander, Perilla, Thai-Basilikum","hinweis":"gemischt"},{"menge":200,"einheit":"g","name":"Mungobohnensprossen","hinweis":"optional"},{"menge":null,"einheit":"","name":"Nem rán (frittierte Frühlingsrollen)","hinweis":"optional, siehe Rezept Chả Giò"}]}],"ausruestung":["Holzkohlegrill oder Grillpfanne","Grillkorb zum Wenden (optional)","große Schüssel","Topf für Nudeln und Sauce","kleine Servierschalen"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle Marinade, Nudeln und Kräuter getrennt bereit. Schneide Schalotten, Knoblauch, Frühlingszwiebeln und Knoblauchschnittlauch sehr fein, denn grob geschnittene Stücke fallen später beim Grillen aus den Bällchen. Lasse den Metzger den Schweinebauch dünn aufschneiden oder friere ihn 45 Minuten an und schneide ihn selbst auf 3 mm. Dünne Scheiben bräunen am Grill in Minuten, ohne trocken zu werden. Stelle den Grill zeitig bereit, damit die Kohle rechtzeitig durchglüht.","dauer":0,"tipp":"Das Fleisch lässt sich leichter schneiden, wenn es außen fest, innen noch weich ist."},{"titel":"Marinade anrühren","aktion":"mischen","text":"Verrühre Fischsauce, Austernsauce, dunkle Sojasauce, Zucker, Pfeffer und Öl in einer Schale, bis sich der Zucker auflöst. Probiere ein winziges bisschen: Die Marinade soll stark salzig-süß schmecken, denn das Fleisch wird später nur kurz gegrillt und sie ist die einzige Würze. Teile die Marinade in zwei Hälften: Die erste kommt später ins Hackfleisch, die zweite zu den Bauchscheiben. Der Zucker karamellisiert beim Grillen, gibt Farbe und die typische, leicht süße Kruste.","dauer":5,"tipp":"Wer Karamellsauce (Nước màu) hat, kann 1 TL zugeben für dunklere Farbe und tieferen Geschmack."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Mische das Hack mit Ei, Schalotten, Knoblauch, Frühlingszwiebeln, Knoblauchschnittlauch und der Hälfte der Marinade und knete es 2 Minuten kräftig, bis es klebrig wird. Wende die Bauchscheiben in der übrigen Marinade, sodass jedes Stück benetzt ist. Decke beides ab und lass es mindestens 2 Stunden im Kühlschrank durchziehen, besser über Nacht. Das Salz und der Zucker dringen ein, das Fleisch wird würziger und beim Grillen entsteht ein schöner Glanz. Nimm es 20 Minuten vor dem Grillen heraus.","dauer":120,"tipp":"Klebriges Hack lässt sich besser formen; mit nassen Händen arbeiten."},{"titel":"Nước chấm kochen","aktion":"kochen","text":"Gib Zucker, Fischsauce, Essig und Wasser in einen kleinen Topf und erhitze, bis der Zucker gelöst ist und die Flüssigkeit kurz aufwallt. Nimm den Topf vom Herd und rühre Limettensaft, Knoblauch und Chili ein; Limette erst jetzt zugeben, damit ihr Aroma frisch bleibt. Lege dünne Möhren- und Papayastreifen in die Brühe, damit sie knackig-sauer anziehen. Die Sauce soll süß, sauer, salzig und leicht scharf sein; schmecke ab und gleiche aus. Sie wird warm serviert.","dauer":10,"tipp":"Die Sauce sollte dünner sein als Fischsauce pur: lieber mehr Wasser als zu salzig."},{"titel":"Nudeln und Kräuter vorbereiten","aktion":"blanchieren","text":"Koche Reisvermicelli nach Packungsanleitung (meist 3 bis 5 Minuten), bis sie weich sind, aber noch leicht Biss haben. Spüle sie sofort kalt ab und lass sie gut abtropfen. Teile sie in Nester auf einer Platte. Wasche Salat und Kräuter, trockne sie gut und richte alles getrennt auf Tellern an. In Hanoi stehen Kräuter und Salat in großen Mengen auf dem Tisch, und jeder nimmt nach Geschmack.","dauer":10,"tipp":"Nudeln nicht zu lange stehen lassen, sonst kleben sie zusammen."},{"titel":"Bällchen formen","aktion":"formen","text":"Mit angefeuchteten Händen formst du aus dem marinierten Hack kleine, flache Frikadellen von etwa 5 cm Durchmesser und 1 cm Dicke. Drücke sie fest zusammen, damit sie beim Wenden nicht zerfallen. Lege sie auf ein Tablett und bestreiche sie leicht mit Öl, das verhindert Ankleben am Grillrost. Dünne, flache Bällchen garen schnell und werden außen knusprig, innen saftig; dicke Kugeln bleiben im Kern roh.","dauer":10,"tipp":""},{"titel":"Grill vorbereiten","aktion":"grillen","text":"Entzünde die Holzkohle und warte, bis sie mit weißer Asche bedeckt ist und gleichmäßig glüht. Die Hitze sollte mittel bis hoch sein. Reibe den Rost mit einem geölten Lappen ein, damit nichts anklebt. In Hanoi stehen Bällchen und Bauch in Grillzangen und Grillkörben, die man beim Wenden zusammenklappt; ein Grillrost tut es auch. Wer keinen Kohlegrill hat, nimmt eine sehr heiße Grillpfanne oder Eisenpfanne und lüftet gut, denn der Rauch gehört zum Aroma.","dauer":20,"tipp":"Je rauchiger, desto authentischer. Etwas Fett vom Bauch auf der Kohle erzeugt Rauch."},{"titel":"Fleisch grillen","aktion":"grillen","text":"Lege Bällchen und Bauchscheiben getrennt auf den heißen Rost. Grille die Bauchscheiben etwa 2 Minuten pro Seite, bis sie braun, am Rand leicht dunkel und knusprig sind; die Bällchen brauchen 3 bis 4 Minuten pro Seite, bis sie durchgegart und außen gebräunt sind. Es duftet nach Röstaromen, Knoblauch und Fischsauce. Wende nur einmal, damit eine Kruste entsteht. Nimm das Fleisch ab und lege es sofort in die warme Nước chấm, damit es die Brühe aufsaugt.","dauer":15,"tipp":"Bauchscheiben nicht überbacken: Sie sollen saftig und leicht knusprig, nicht trocken sein."},{"titel":"Anrichten und essen","aktion":"anrichten","text":"Gib das gegrillte Fleisch mit Brühe in kleine Schalen und lege Möhren und Papaya dazu. Stelle Nudeln, Salat, Kräuter und gegebenenfalls frittierte Frühlingsrollen daneben. Jeder nimmt sich eine Portion Nudeln, legt ein Salatblatt und Kräuter dazu, pickt mit den Stäbchen ein Stück Fleisch und taucht alles in die Brühe. Die Kombination aus warmem Fleisch, kalten Nudeln, frischen Kräutern und süßsaurer Sauce ist das Besondere: Alles in einem Bissen.","dauer":0,"tipp":"Nicht alles auf einmal in die Schale geben; die Nudeln bleiben getrennt und werden je Bissen getunkt."}],"profitipps":["Hanoi-typisch: Fleisch und Sauce zusammen servieren, Nudeln und Kräuter getrennt, der Gast mischt selbst.","Dünne Bauchscheiben und flache Bällchen: so garen sie in Minuten und karamellisieren am Grill.","Rauch ist Geschmack: über Holzkohle grillen, ein wenig Fett darf auf die Glut tropfen.","Sauce warm servieren und Limette erst nach dem Kochen zugeben.","Schmecke Nước chấm erst ab, wenn sie lauwarm ist; heiß wirkt sie salziger.","Knoblauchschnittlauch (Hẹ) gibt den typischen Geschmack; Schnittlauch ist der Ersatz."],"varianten":["Bún chả ohne Bällchen, nur mit Bauchscheiben","Bún chả mit Nem rán als Beilage (Hanoi-Standard)","Chả cá Lã Vọng: Fisch mit Kurkuma und Dill, ebenfalls aus Hanoi","Bún thịt nướng (Südvietnam): mit trockenem Fleisch statt Brühe, siehe eigenes Rezept"],"beilagen":["Nem rán (frittierte Frühlingsrollen)","frische Kräuter und Salat","Knoblauch-Essig-Chili-Soße zum Nachwürzen"],"getraenk":"Bia Hơi (leichtes Fassbier), Pils oder Eistee","koeche":[{"name":"Luke Nguyen","bezug":"Zeigt in seiner Fernsehreise durch Vietnam („Luke Nguyen’s Vietnam“ und „Railway Vietnam“) Bún chả in Hanoi und veröffentlicht dazu auf SBS Food sein Rezept: Hack und Bauchscheiben getrennt mariniert, Fleisch über Holzkohle gegrillt, dazu eine warme süßsaure Nước chấm.","quelle":"https://www.sbs.com.au/food/recipes/bun-cha-char-grilled-pork-noodles-and-nuoc-cham"}],"quellen":[{"titel":"Bun cha (char-grilled pork, noodles and nuoc cham) – Luke Nguyen, SBS Food","url":"https://www.sbs.com.au/food/recipes/bun-cha-char-grilled-pork-noodles-and-nuoc-cham"},{"titel":"Chargrilled pork patties with Vietnamese herbs (bun cha) – SBS Food","url":"https://www.sbs.com.au/food/recipes/chargrilled-pork-patties-vietnamese-herbs-bun-cha"},{"titel":"Vietnamese Bun Cha Recipe – Grantourismo","url":"https://grantourismotravels.com/vietnamese-bun-cha-recipe/"},{"titel":"14 Vietnamese dishes listed among world's 100 best rated noodles – Nhân Dân","url":"https://en.cand.vn/culture-travel/14-vietnamese-dishes-listed-among-worlds-100-best-rated-noodles-i594053"}],"bild":"nudeln","farben":["#a3541e","#f2e8c9","#6fa04b"],"schlagworte":["Hanoi","Streetfood","Grill","Nudeln","Kräuter"],"vegetarisch_moeglich":false},{"id":"vietnam-bo-luc-lac","name":"Bò Lúc Lắc (Shaking Beef)","originalname":"Bò lúc lắc","kueche":"vietnam","region":"Südvietnam / Saigon","beliebtheit":86,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Zarte Rinderwürfel, im glühend heißen Wok kurz angebraten und „geschüttelt“, mit Zwiebel, Knoblauch und süß-salziger Sauce – serviert auf knackiger Brunnenkresse mit Limetten-Pfeffer-Dip.","hintergrund":"„Lúc lắc“ bedeutet „schütteln“ und beschreibt die Technik: Der Koch schwenkt den Wok so, dass die Rinderwürfel durch die Luft wirbeln und gleichmäßig von allen Seiten Hitze bekommen. Das Gericht gilt als südvietnamesischer Restaurantklassiker, der durch französischen Einfluss (Butter, Filet) und vietnamesische Aromen (Fischsauce, Knoblauch, Limette) geprägt ist. Charles Phan, Gründer des Slanted Door in San Francisco, machte es in den USA mit seiner Version berühmt, die auf Filet, Butter am Schluss und Brunnenkresse setzt. Im TasteAtlas-Ranking der besten Gerichte Asiens steht Bò lúc lắc auf Platz 52. In Vietnam isst man es oft mit Reis oder Pommes frites und Tomaten.","portionen":4,"zeit":{"vorbereitung":30,"garen":12,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Rindfleisch","liste":[{"menge":700,"einheit":"g","name":"Rinderfilet (Mittelstück), in 3 cm große Würfel geschnitten","hinweis":"alternativ Hüftsteak oder Rumpsteak, Fett abgeschnitten"},{"menge":3,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":1,"einheit":"TL","name":"frisch gemahlener schwarzer Pfeffer","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"neutrales Öl","hinweis":"zum Marinieren"}]},{"gruppe":"Für die Sauce","liste":[{"menge":1.5,"einheit":"EL","name":"Reisessig oder weißer Essig","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":3,"einheit":"EL","name":"helle Sojasauce","hinweis":""},{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"TL","name":"Reiswein oder trockener Sherry","hinweis":""}]},{"gruppe":"Zum Braten","liste":[{"menge":6,"einheit":"EL","name":"neutrales Öl (z. B. Erdnussöl)","hinweis":"in zwei Portionen"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel, in dünne Ringe","hinweis":""},{"menge":3,"einheit":"Stück","name":"Frühlingszwiebeln, in 3 cm Stücke","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, gehackt","hinweis":""},{"menge":2,"einheit":"EL","name":"kalte Butter","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":1,"einheit":"Bund","name":"Brunnenkresse, gewaschen","hinweis":"ersatzweise Rucola oder Feldsalat"},{"menge":2,"einheit":"Stück","name":"Tomaten, in Scheiben","hinweis":"optional"},{"menge":320,"einheit":"g","name":"Jasminreis (roh)","hinweis":"optional, als Beilage"},{"menge":3,"einheit":"EL","name":"frischer Limettensaft","hinweis":"für den Dip"},{"menge":1,"einheit":"TL","name":"grobes Salz","hinweis":"für den Dip"},{"menge":0.5,"einheit":"TL","name":"frisch gemahlener Pfeffer","hinweis":"für den Dip"}]}],"ausruestung":["Wok oder große schwere Pfanne (Gusseisen)","Wokschaufel oder Zange","kleine Dip-Schälchen","Küchenpapier"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Bereite alle Zutaten komplett vor, bevor du die Pfanne erhitzt, denn der eigentliche Garvorgang dauert nur wenige Minuten und lässt keine Zeit zum Schneiden. Schneide das Rindfleisch in gleich große, 3 cm dicke Würfel, damit alle gleichmäßig garen. Entferne Fett und Sehnen, denn sie werden beim kurzen Braten nicht weich. Schneide Zwiebeln, Frühlingszwiebeln und Knoblauch und lege sie in getrennte Schälchen. Wasche die Brunnenkresse und trockne sie, denn Wasser auf den Blättern würde die Sauce verdünnen.","dauer":0,"tipp":"Das Fleisch 20 Minuten vor dem Braten aus dem Kühlschrank nehmen, damit es nicht eiskalt in die Pfanne kommt."},{"titel":"Rind marinieren","aktion":"marinieren","text":"Vermenge die Rinderwürfel mit Knoblauch, Pfeffer, Zucker, Salz und 1 EL Öl und knete alles kurz mit den Händen durch. Lass das Fleisch mindestens 1 Stunde bei Raumtemperatur ziehen, besser 2 Stunden; in einer warmen Küche stelle es gekühlt. Das Öl schützt das Fleisch beim Braten, der Zucker hilft beim Bräunen, Salz und Knoblauch würzen von innen. Zu langes Marinieren mit Salz zieht Saft heraus, deshalb nicht über Nacht. Tupfe die Würfel vor dem Braten leicht trocken, damit sie sofort Röstaroma bekommen.","dauer":90,"tipp":"Reste der Marinade mit Knoblauchstücken nicht mitbraten: Das Fleisch nur abtupfen, sonst verbrennt der Knoblauch."},{"titel":"Sauce mischen","aktion":"mischen","text":"Rühre Essig, Zucker, Sojasauce, Fischsauce und Reiswein in einer Schale, bis sich der Zucker aufgelöst hat. Probiere: Die Sauce soll salzig, süß und leicht sauer sein; sie wird beim Kochen konzentriert und überzieht das Fleisch als glänzender Film. Stelle die Schale direkt neben den Herd, denn du musst sie in Sekunden erreichen können. Wenn die Sauce zu salzig wirkt, wird sie durch die Butter am Ende etwas gemildert.","dauer":3,"tipp":"Fischsauce nicht überdosieren; sie ist stark und kann das Gericht dominieren."},{"titel":"Limetten-Pfeffer-Dip anrühren","aktion":"mischen","text":"Gib Salz und frisch gemahlenen Pfeffer in ein kleines Schälchen und gieße den Limettensaft darüber. Rühre kurz um, das Salz löst sich teilweise auf, der Pfeffer schwimmt oben. Dieser einfache Dip (muối tiêu chanh) ist typisch für Vietnam und bringt Säure und Schärfe: Man tunkt die Fleischwürfel kurz hinein. Du kannst ein Stück Chili ergänzen. Stelle den Dip auf den Tisch, damit jeder selbst würzt.","dauer":2,"tipp":"Frisch gepresster Limettensaft ist Pflicht, Saft aus der Flasche schmeckt flach."},{"titel":"Reis und Salatbett vorbereiten","aktion":"kochen","text":"Koche den Jasminreis nach Packungsanleitung oder im Reiskocher, damit er fertig ist, wenn das Fleisch aus der Pfanne kommt. Richte die Brunnenkresse und Tomatenscheiben auf einer großen Platte oder vier Tellern an. Die Kresse dient als Bett: Sie nimmt den Bratensaft auf und bringt Schärfe und Frische. Halte die Teller warm, am besten bei 60 °C im Ofen, damit das Fleisch nicht abkühlt.","dauer":15,"tipp":"Rucola ist ein guter Ersatz, wenn keine Brunnenkresse zu finden ist."},{"titel":"Wok glühend heiß machen","aktion":"wok","text":"Erhitze Wok oder Pfanne bei höchster Stufe 2 bis 3 Minuten, bis sie fast raucht, gib dann 3 EL Öl dazu und warte, bis es zu rauchen beginnt. Erst bei dieser Temperatur (ca. 230 °C) entsteht das Röstaroma, das das Gericht ausmacht. Eine zu kalte Pfanne lässt das Fleisch Wasser ziehen und kochen statt braten. Stelle den Dunstabzug auf die höchste Stufe und öffne das Fenster, denn es raucht stark.","dauer":3,"tipp":"Eine Gusseisenpfanne speichert Hitze besser als eine beschichtete Pfanne."},{"titel":"Rind scharf anbraten","aktion":"anbraten","text":"Gib die Hälfte der Rinderwürfel in einer einzigen Lage in den Wok; sie dürfen sich nicht stapeln. Lass sie 1 bis 2 Minuten unberührt braten, bis sich eine dunkle Kruste bildet, und wende sie dann. Brate sie insgesamt 3 bis 4 Minuten, bis sie rundum gebräunt und innen medium-rare sind. Das Fleisch nicht ständig bewegen, denn jede Berührung kühlt es ab. Das Fleisch bleibt im Wok und wird im nächsten Schritt sofort weiterverarbeitet.","dauer":8,"tipp":"Zwei Durchgänge sind besser als ein überfüllter Wok: Zu viel Fleisch drückt die Temperatur und das Fleisch kocht."},{"titel":"Schwenken, würzen und Butter zugeben","aktion":"wok","text":"Gib Zwiebelringe, Frühlingszwiebeln und Knoblauch zum Fleisch und schwenke den Wok etwa 30 Sekunden. Gieße die Hälfte der Sauce hinein, sie zischt und verdampft sofort und karamellisiert am Fleisch. Gib die kalte Butter dazu und schwenke weiter, bis sie geschmolzen ist und die Sauce zu einem glänzenden Überzug bindet. Das Schwenken macht dem Gericht seinen Namen: Mit einem Handgelenkdreh werden die Würfel durch die Luft gewirbelt. Nimm den Wok sofort vom Feuer, sonst gart das Fleisch durch. Wische den Wok aus und wiederhole alles mit der zweiten Hälfte.","dauer":3,"tipp":"Butter zum Schluss gibt der Sauce Glanz und rundet die Salzigkeit ab; sie darf nicht lange kochen."},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile das Fleisch samt Sauce sofort über das vorbereitete Bett aus Brunnenkresse und Tomaten, damit die Blätter leicht zusammenfallen, aber noch knackig sind. Serviere mit Reis und dem Limetten-Pfeffer-Dip. Das Fleisch soll innen rosa, außen dunkel gebräunt, die Sauce glänzend sein. Jeder tunkt die Würfel kurz in den Dip. Serviere sofort, denn das Gericht schmeckt am besten frisch aus dem heißen Wok.","dauer":0,"tipp":""}],"profitipps":["Der Wok muss rauchheiß sein; sonst kocht das Fleisch statt zu bräunen.","In zwei Portionen braten, damit die Temperatur nicht abfällt.","Filet oder Hüftsteak verwenden; Würfel nicht größer als 3 cm.","Butter erst am Ende einarbeiten: sie gibt Glanz und Rundung.","Brunnenkresse als Bett: Sie nimmt den Bratensaft auf und liefert Schärfe.","Fleisch sofort servieren, es gart sonst durch."],"varianten":["Mit Tomaten und Zwiebeln auf Reis (Cơm bò lúc lắc)","Mit Pommes frites statt Reis, wie in Saigon üblich","Mit Rinderhüfte statt Filet für ein günstigeres Gericht","Mit etwas Chili und Zitronengras in der Marinade für mehr Würze"],"beilagen":["Jasminreis","Pommes frites","Brunnenkresse, Tomaten und Gurke","Limetten-Pfeffer-Dip"],"getraenk":"Kühler Pinot Gris, ein Pils oder grüner Tee","koeche":[{"name":"Charles Phan","bezug":"Sein Shaking Beef aus dem Slanted Door in San Francisco ist ein Signature-Gericht und im Buch „The Slanted Door: Modern Vietnamese Food“ dokumentiert: Filetwürfel werden etwa 2 Stunden mariniert, im rauchheißen Wok in zwei Portionen gebräunt und mit Sauce und Butter geschwenkt, serviert auf Brunnenkresse mit Limetten-Salz-Pfeffer-Dip.","quelle":"https://www.7x7.com/slanted-door-shaking-beef-recipe-1781315078.html"}],"quellen":[{"titel":"Slanted Door at Home: Charles Phan's signature shaking beef – 7x7","url":"https://www.7x7.com/slanted-door-shaking-beef-recipe-1781315078.html"},{"titel":"Bo Luc Lac (Shaking Beef) – Saveur","url":"https://www.saveur.com/recipes/bo-luc-lac-shaking-beef/"},{"titel":"Shaking beef from The Slanted Door: Modern Vietnamese Food – Eat Your Books","url":"https://www.eatyourbooks.com/library/recipes/1366012/shaking-beef"},{"titel":"Vietnamese Shaking Beef Recipe – Gastronomy Blog","url":"https://gastronomyblog.com/2016/01/07/vietnamese-shaking-beef-recipe/"},{"titel":"TasteAtlas picks out seven Vietnamese dishes among Top 100 Asian foods – VOV","url":"https://vov.gov.vn/tasteatlas-picks-out-seven-vietnamese-dishes-among-top-100-asian-foods-dtnew-1079501"}],"bild":"pfanne","farben":["#8b3a1e","#c9a064","#4f8f3a"],"schlagworte":["Wok","Rind","Restaurantklassiker","Saigon"],"vegetarisch_moeglich":false},{"id":"vietnam-bun-bo-hue","name":"Bún Bò Huế","originalname":"Bún bò Huế","kueche":"vietnam","region":"Huế / Zentralvietnam","beliebtheit":84,"hauptkategorie":"fleisch","fleischsorte":"gemischt","gang":"suppe","kurz":"Die feurige Rindernudelsuppe aus der alten Kaiserstadt: kräftige Brühe mit Zitronengras, Garnelenpaste und rotem Chiliöl, dicke runde Reisnudeln, zartes Rind, Schweinehaxe und frische Kräuter.","hintergrund":"Bún bò Huế stammt aus Huế, der alten Kaiserstadt in Zentralvietnam, und ist die würzige, scharfe Antwort der Region auf das mildere Phở aus dem Norden. Die Brühe wird aus Rinder- und Schweineknochen gekocht, mit reichlich Zitronengras aromatisiert und mit fermentierter Garnelenpaste (mắm ruốc) gewürzt, deren kräftiger, salziger Charakter typisch für die Küche Huếs ist. Ihre leuchtend rote Farbe stammt von Öl, das mit Annattosamen, Zitronengras und Chili aromatisiert wird. Statt der dünnen Phở-Nudeln werden dicke, runde Reisnudeln (Bún) verwendet. Im TasteAtlas-Ranking der besten Nudelsuppen der Welt kam die Suppe auf Platz 53.","portionen":6,"zeit":{"vorbereitung":60,"garen":180,"ruhen":60},"schwierigkeit":3,"zutaten":[{"gruppe":"Für die Brühe","liste":[{"menge":1,"einheit":"kg","name":"Rinderknochen (Mark- und Gelenkknochen)","hinweis":"beim Metzger kleinsägen lassen"},{"menge":800,"einheit":"g","name":"Rinderbeinscheibe oder Wade am Stück","hinweis":"mit Sehnenanteil, bleibt zart"},{"menge":800,"einheit":"g","name":"Schweinehaxe oder Eisbein (ungepökelt), in dicke Scheiben gesägt","hinweis":"gibt Gelatine und Süße"},{"menge":5,"einheit":"l","name":"kaltes Wasser","hinweis":"plus Wasser zum Vorkochen"},{"menge":2,"einheit":"Stück","name":"Zwiebeln, halbiert und angeröstet","hinweis":""},{"menge":6,"einheit":"Stange","name":"Zitronengras, 4 davon angeklopft und halbiert, 2 fein gehackt","hinweis":""},{"menge":50,"einheit":"g","name":"Ingwer, geschält und angeklopft","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Ananas (kleine Stücke), optional","hinweis":"mildert die Würze und gibt Frucht"},{"menge":2,"einheit":"EL","name":"Mắm ruốc (fermentierte Garnelenpaste aus Huế)","hinweis":"ersatzweise 1 EL Garnelenpaste oder 1 EL Fischsauce zusätzlich"},{"menge":4,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":30,"einheit":"g","name":"gelber Kandiszucker","hinweis":""},{"menge":1,"einheit":"EL","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Für das rote Öl","liste":[{"menge":5,"einheit":"EL","name":"neutrales Öl","hinweis":""},{"menge":1,"einheit":"EL","name":"Annattosamen (Achiote)","hinweis":"im Asia- oder Lateinamerika-Laden; ersatzweise 1 TL Paprikapulver edelsüß"},{"menge":3,"einheit":"Zehe","name":"Knoblauch, gehackt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Schalotten, gehackt","hinweis":""},{"menge":2,"einheit":"EL","name":"Chiliflocken oder Chilipaste (Sa tế)","hinweis":"nach Schärfe-Wunsch"}]},{"gruppe":"Für die Schüssel","liste":[{"menge":600,"einheit":"g","name":"dicke, runde Reisnudeln (Bún bò Huế, ca. 3 mm)","hinweis":"im Asialaden; dünne Vermicelli sind ein Notbehelf"},{"menge":0.25,"einheit":"Stück","name":"Rotkohl, fein gehobelt","hinweis":"ersetzt Bananenblüte"},{"menge":200,"einheit":"g","name":"Mungobohnensprossen","hinweis":""},{"menge":1,"einheit":"Bund","name":"Minze und Vietnamesischer Koriander (Rau răm) oder Koriander","hinweis":""},{"menge":3,"einheit":"Stück","name":"Limetten, in Spalten","hinweis":""},{"menge":4,"einheit":"Stück","name":"Frühlingszwiebeln, in Ringen","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Zwiebel, in dünnen Ringen","hinweis":"kurz in Eiswasser gelegt"}]}],"ausruestung":["großer Topf (mind. 10 Liter)","feines Sieb und Mulltuch","kleine Pfanne für das Öl","Schaumlöffel","Topf zum Blanchieren der Nudeln"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle sie bereit. Klopfe die Zitronengrasstangen mit der Messerflanke an, damit sie ihr Aroma abgeben, und halbiere sie auf die Länge deines Topfs. Röste die Zwiebelhälften mit der Schnittfläche nach unten in einer trockenen Pfanne 5 bis 8 Minuten, bis sie dunkelbraun sind und süßlich riechen. Schneide Rotkohl fein, wasche Kräuter und Sprossen und lege alles beiseite. Prüfe, ob dein Topf groß genug ist: Die Knochen müssen mit 5 Litern Wasser reichlich bedeckt sein.","dauer":0,"tipp":"Das Anrösten der Zwiebeln liefert einen runden, süßlichen Grundton, der die Schärfe später ausgleicht."},{"titel":"Knochen vorkochen","aktion":"blanchieren","text":"Lege Rinderknochen, Beinscheibe und Schweinehaxe in den Topf, bedecke sie mit kaltem Wasser und bringe es zum kräftigen Kochen. Lass es 5 bis 7 Minuten sprudeln, bis sich dicker grauer Schaum bildet. Gieße alles ab, spüle jedes Stück unter fließendem Wasser sauber und schrubbe den Topf aus. Dieser Schritt entfernt Blut und Eiweiß und ist die Voraussetzung für eine klare Brühe. Danach alles zurück in den sauberen Topf geben.","dauer":15,"tipp":"Wasser und Schaum nie in der Brühe lassen: Er verleiht ihr einen bitteren, trüben Beigeschmack."},{"titel":"Brühe ansetzen","aktion":"kochen","text":"Gieße 5 Liter frisches kaltes Wasser auf, bringe es langsam zum Kochen und schöpfe den aufsteigenden Schaum ab. Gib angeröstete Zwiebeln, angeklopftes Zitronengras (4 Stangen), Ingwer und Ananasstücke dazu. Reduziere die Hitze, bis die Oberfläche nur leicht blubbert, und lege den Deckel schräg auf. Die Brühe soll hellgolden bleiben; sprudeln trübt sie. Lass sie nun ruhig weiterziehen.","dauer":30,"tipp":"Zitronengras sollte sich in der Brühe öffnen, nicht zerfallen."},{"titel":"Fleisch garen","aktion":"koecheln","text":"Lass Beinscheibe und Haxe 60 bis 90 Minuten leise garen. Die Beinscheibe ist fertig, wenn ein Spieß leicht eindringt, aber das Fleisch noch fest ist; nimm sie dann heraus, lege sie 10 Minuten in kaltes Wasser, damit sie hell und saftig bleibt, und stelle sie kühl. Die Haxe gart weiter, bis die Haut weich und das Fleisch am Knochen locker ist (etwa 2 bis 2,5 Stunden). Lass die Knochen in der Brühe, sie geben Kollagen und Tiefe.","dauer":90,"tipp":"Gut durchgekühltes Fleisch lässt sich später dünner und sauberer aufschneiden."},{"titel":"Garnelenpaste vorbereiten","aktion":"mischen","text":"Rühre 2 EL Mắm ruốc mit 250 ml Wasser an und lass die Mischung 30 Minuten absetzen. Gieße die klare Flüssigkeit über der Paste ab, ohne den Bodensatz aufzuwirbeln, und seihe sie durch ein feines Sieb in den Topf. Die Paste ist sehr salzig und riecht intensiv; das Absetzen entfernt Schwebeteilchen, die die Brühe trüben würden. Gib davon zunächst die Hälfte in die Brühe, damit du die Intensität steuern kannst; man kann immer nachwürzen, aber nicht zurücknehmen.","dauer":30,"tipp":"Wenn keine Mắm ruốc zu finden ist, nimm 1 EL Garnelenpaste und etwas mehr Fischsauce."},{"titel":"Rotes Chiliöl herstellen","aktion":"braten","text":"Erhitze das Öl in einer kleinen Pfanne bei mittlerer Hitze und gib Annattosamen dazu. Lass sie 1 bis 2 Minuten ziehen, bis das Öl leuchtend orangerot wird, und siebe die Samen ab. Gib Knoblauch, Schalotten, gehacktes Zitronengras (2 Stangen) und Chili in das Öl und brate 1 Minute unter Rühren, bis alles duftet, aber nicht dunkel wird. Das rote Öl gibt der Suppe Farbe und Aroma und schwimmt später in leuchtenden Augen auf der Brühe.","dauer":5,"tipp":"Nicht zu heiß werden lassen: Verbrannter Knoblauch macht das Öl bitter."},{"titel":"Brühe würzen","aktion":"abschmecken","text":"Gib die vorbereitete Garnelenpaste-Flüssigkeit, Fischsauce, Kandiszucker und Salz in den Topf und lass die Brühe weitere 30 Minuten ziehen. Rühre dann das rote Öl ein. Probiere: Die Brühe soll kräftig, salzig, leicht süß und scharf-aromatisch schmecken. Wenn sie flach wirkt, hilft Fischsauce; zu salzig? Mit heißem Wasser verdünnen. Das Zitronengras bringt Frische, die Garnelenpaste die fermentierte Tiefe, das Chiliöl Schärfe und Farbe.","dauer":30,"tipp":"Die Brühe sollte etwas kräftiger sein, weil die Nudeln die Würze verdünnen."},{"titel":"Brühe abseihen","aktion":"abseihen","text":"Hebe Knochen, Haxe, Zitronengras, Ingwer und Zwiebeln aus dem Topf und gieße die Brühe durch ein feines, mit Mulltuch ausgelegtes Sieb in einen zweiten Topf. Schöpfe überschüssiges Fett ab, lass aber ein wenig rotes Öl auf der Oberfläche. Löse das Fleisch der Haxe vom Knochen und schneide es in mundgerechte Stücke. Halte die Brühe heiß, aber nicht kochend.","dauer":15,"tipp":"Das Fett nicht komplett abschöpfen; es trägt die Aromen und die rote Farbe."},{"titel":"Fleisch und Beilagen schneiden","aktion":"schneiden","text":"Schneide die abgekühlte Beinscheibe quer zur Faser in 3 mm dünne Scheiben. Hobele den Rotkohl so fein wie möglich. Lege die rote Zwiebel 10 Minuten in Eiswasser, damit sie mild und knackig wird. Zupfe Kräuterblätter von den Stielen und richte sie mit Sprossen und Limetten auf einem Teller an. Alle Beilagen sollen frisch, knackig und trocken sein.","dauer":5,"tipp":""},{"titel":"Nudeln garen","aktion":"blanchieren","text":"Koche die dicken Reisnudeln nach Packungsangabe in reichlich Wasser (meist 5 bis 8 Minuten) und probiere eine: Sie sollen weich, aber noch leicht elastisch sein. Gieße sie ab und spüle sie kurz mit heißem Wasser ab, damit die Stärke abgespült wird. Portioniere sie in vorgewärmte Schüsseln. Die Nudeln sollen nicht zusammenkleben und nicht matschig sein.","dauer":8,"tipp":"Nicht vorkochen und lange stehen lassen; Reisnudeln werden schnell klebrig."},{"titel":"Schüsseln bauen und servieren","aktion":"anrichten","text":"Lege Nudeln in die Schüsseln, gib Rindfleischscheiben, Schweinefleischstücke, Frühlingszwiebeln und Zwiebelringe darauf und gieße die kochend heiße Brühe darüber. Das rote Öl soll in Augen auf der Oberfläche schwimmen. Stelle Kräuter, Sprossen, Rotkohl, Limetten und Chili auf den Tisch, damit jeder nach Geschmack würzt. Presse Limette in die Suppe, gib eine Handvoll Kräuter und Kohl dazu und mische. Die Mischung aus scharf, salzig, sauer und frisch ist das Markenzeichen der Suppe.","dauer":0,"tipp":"Wer es noch schärfer mag, rührt am Tisch einen Löffel Chilipaste (Sa tế) ein."}],"profitipps":["Knochen gründlich vorkochen und spülen: Das ist die Basis für eine klare Brühe.","Garnelenpaste vorher in Wasser absetzen lassen und nur die klare Flüssigkeit verwenden.","Annattoöl liefert Farbe, nicht Schärfe; die Schärfe kommt von Chili und lässt sich steuern.","Rindfleisch nach dem Garen kalt abschrecken, damit es hell und saftig bleibt.","Brühe nur leise köcheln lassen, nie sprudeln.","Dicke runde Nudeln verwenden: Sie halten die kräftige Brühe aus."],"varianten":["Mit Chả Huế (Schweinewurst) und Blutwürfeln (Huyết), wie in Huế üblich","Mit Krebsfleischbällchen (Chả cua)","Mit Bananenblüte statt Rotkohl","Mildere Version ohne Chili für Kinder"],"beilagen":["Kräuter- und Gemüseteller","Limetten und Chili","Sa-tế-Chilipaste"],"getraenk":"Leichtes Pils, Eistee oder ein Glas kalter Riesling","koeche":[],"quellen":[{"titel":"22 Vietnamese noodle soups named among world's best by TasteAtlas – VOV","url":"https://vov.gov.vn/22-vietnamese-noodle-soups-named-among-worlds-best-by-tasteatlas-dtnew-1096974"},{"titel":"Savoury Vietnamese Pancakes in Huế – Luke Nguyen's Railway Vietnam (Kontext: Luke sucht in Huế die scharfe Rindernudelsuppe)","url":"https://www.fubo.tv/welcome/program/EP034349680008/savoury-vietnamese-pancakes-in-hue?irmp=67192"}],"bild":"ramen","farben":["#b3361e","#e8c39e","#6fa04b"],"schlagworte":["Huế","scharf","Nudelsuppe","Zitronengras","Garnelenpaste"],"vegetarisch_moeglich":false},{"id":"vietnam-pho-ga","name":"Phở Gà","originalname":"Phở gà","kueche":"vietnam","region":"Hanoi / Nordvietnam","beliebtheit":83,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"suppe","kurz":"Die helle, zarte Schwester des Phở bò: goldene Hühnerbrühe mit geröstetem Ingwer und Sternanis, Reisbandnudeln, saftiges Hühnerfleisch und viel frische Kräuter.","hintergrund":"Phở gà ist die Hühnerversion des vietnamesischen Nationalgerichts und entstand im Norden, wo es lange als leichtere, feinere Alternative zum Rind-Phở galt. Die Brühe wird aus einem ganzen Huhn gekocht, das schon nach kurzer Zeit gar ist, anschließend aber noch weiter ausgekocht wird, damit die Brühe Tiefe bekommt. Typisch sind Limettenblätter, Vietnamesischer Koriander (Rau răm) und eine Spur Zwiebel, dazu Pfeffer, Chili und Limette. Im TasteAtlas-Ranking der besten Nudelsuppen der Welt steht Phở gà auf Platz 22. Andrea Nguyen zeigt in ihrer Phở-Arbeit, dass sich auch die Hühnerbrühe mit einfachen Mitteln, nämlich gerösteten Aromaten, Koriandersamen und Nelken, zu einer klaren, duftenden Brühe entwickeln lässt.","portionen":5,"zeit":{"vorbereitung":40,"garen":150,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Brühe","liste":[{"menge":1.7,"einheit":"kg","name":"Suppenhuhn oder ganzes Bio-Hähnchen","hinweis":"Suppenhuhn gibt mehr Geschmack, braucht aber länger"},{"menge":500,"einheit":"g","name":"Hühnerkarkassen oder Hühnerflügel","hinweis":"für mehr Körper, optional"},{"menge":3,"einheit":"l","name":"kaltes Wasser","hinweis":"plus Wasser zum Vorkochen"},{"menge":2,"einheit":"Stück","name":"mittelgroße Zwiebeln, ungeschält","hinweis":""},{"menge":80,"einheit":"g","name":"Ingwer, ungeschält","hinweis":""},{"menge":3,"einheit":"Stück","name":"Sternanis","hinweis":""},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stange","name":"Zimtstange (Cassia)","hinweis":""},{"menge":1,"einheit":"EL","name":"Koriandersamen","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander (Stiele und Wurzeln)","hinweis":""},{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Salz","hinweis":"nach Geschmack"},{"menge":20,"einheit":"g","name":"gelber Kandiszucker","hinweis":"oder 1 TL Zucker"}]},{"gruppe":"Für die Schüssel","liste":[{"menge":500,"einheit":"g","name":"frische Reisbandnudeln (Bánh phở) oder 300 g getrocknete","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine weiße Zwiebel, in dünnen Ringen","hinweis":"kurz in Eiswasser legen"},{"menge":4,"einheit":"Stück","name":"Frühlingszwiebeln, in Ringen","hinweis":""},{"menge":6,"einheit":"Blatt","name":"Kaffirlimettenblätter, in feine Streifen","hinweis":"typisch für Phở gà"},{"menge":1,"einheit":"Bund","name":"Vietnamesischer Koriander (Rau răm), ersatzweise Koriander und Minze","hinweis":""},{"menge":2,"einheit":"Stück","name":"Limetten, in Spalten","hinweis":""},{"menge":2,"einheit":"Stück","name":"rote Chilischoten, in Ringen","hinweis":""},{"menge":null,"einheit":"","name":"frisch gemahlener schwarzer Pfeffer","hinweis":"reichlich"}]}],"ausruestung":["großer Topf","feines Sieb und Mulltuch","Schaumlöffel","Schüssel mit Eiswasser","Küchenthermometer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alles ab und stelle Zutaten und Gewürze bereit. Entferne vom Huhn überschüssiges Fett am Hals und an der Öffnung, denn es würde die Brühe fettig und trüb machen. Halbiere die Ingwerstücke der Länge nach und lasse die Zwiebeln ungeschält, so karamellisiert die Schale beim Rösten sauber. Hole das Huhn rechtzeitig aus dem Kühlschrank, damit es nicht ganz kalt ins Wasser kommt. Bereite Schüssel mit Eiswasser für später vor.","dauer":0,"tipp":"Das abgeschnittene Hühnerfett kannst du auslassen und später für Gemüse oder Reis verwenden."},{"titel":"Huhn vorkochen","aktion":"blanchieren","text":"Lege Huhn und Karkassen in den Topf, bedecke sie mit kaltem Wasser und bringe es zum Kochen. Lass es 5 Minuten kräftig kochen, bis sich grauer Schaum bildet, gieße alles ab und spüle Huhn und Karkassen unter fließendem Wasser sauber. Schrubbe den Topf aus. Dieser Schritt entfernt Blut und Eiweiß, die die Brühe trüben. Ohne ihn bleibt die Brühe milchig, nicht golden.","dauer":10,"tipp":"Auch bei Hühnerbrühe gilt: Wer klar kochen will, spült nach dem Vorkochen jedes Stück ab."},{"titel":"Zwiebel und Ingwer rösten","aktion":"grillen","text":"Röste Zwiebeln und Ingwer über der Gasflamme, unter dem Backofengrill (250 °C) oder in einer trockenen Pfanne etwa 15 Minuten, bis die Schale schwarz und blasig ist und das Fleisch weich. Wende sie regelmäßig. Der Duft verändert sich von scharf zu süß und rauchig. Streife die schwarze Schale unter fließendem Wasser ab und klopfe den Ingwer leicht flach. Nur die Oberfläche soll verkohlen; verbrannte Reste gehören nicht in die Brühe.","dauer":15,"tipp":"Röstaromen sind das Gerüst: Sie geben der Hühnerbrühe Tiefe, die sie sonst nicht hätte."},{"titel":"Gewürze rösten","aktion":"anbraten","text":"Röste Koriandersamen, Nelken, Sternanis und Zimtstange in einer trockenen Pfanne bei mittlerer Hitze 2 bis 3 Minuten, bis sie duften. Schwenke dabei laufend, denn Nelken und Koriander verbrennen schnell. Fülle die Gewürze in einen Mullbeutel oder ein Teesieb. Das Rösten weckt ätherische Öle; bei Hühnerbrühe sind die Gewürze zurückhaltender als beim Rind-Phở, damit die Hühneraromen nicht erdrückt werden.","dauer":3,"tipp":"Mit weniger Sternanis anfangen und nach 30 Minuten probieren: Er dominiert bei Hühnerbrühe schnell."},{"titel":"Brühe ansetzen","aktion":"kochen","text":"Lege das Huhn und die Karkassen in den sauberen Topf, gieße 3 Liter kaltes Wasser darauf und erhitze langsam, bis sich kleine Bläschen zeigen. Schöpfe den feinen Schaum ab. Gib Zwiebeln, Ingwer, Gewürzbeutel und Koriander-Stiele dazu. Reduziere die Hitze, sodass die Oberfläche nur leicht zittert (ca. 85 bis 90 °C). Starkes Kochen würde Fett emulgieren und die Brühe trüben.","dauer":20,"tipp":"Ein Thermometer hilft: Ziel sind 85 bis 90 °C."},{"titel":"Huhn pochieren und abschrecken","aktion":"koecheln","text":"Lass das ganze Huhn je nach Größe 35 bis 45 Minuten leise ziehen, bis die Keule beim Einstechen klaren Saft gibt und die Brust 72 °C erreicht hat; ein Suppenhuhn braucht deutlich länger. Hebe das Huhn heraus und lege es 10 Minuten in Eiswasser: Das stoppt das Garen, hält das Fleisch saftig und festigt die Haut. Löse danach Brust und Keulen vom Knochen, zupfe das Fleisch in Streifen und stelle es abgedeckt kühl.","dauer":45,"tipp":"Karkasse und Knochen kommen zurück in den Topf: In ihnen steckt noch viel Geschmack."},{"titel":"Brühe weiter ausziehen und würzen","aktion":"koecheln","text":"Gib die Knochen und Haut zurück in den Topf und lass die Brühe weitere 60 bis 90 Minuten leise köcheln. Sie wird goldgelb, duftet nach Hühnchen und Gewürzen und schmeckt voller. Würze in den letzten 20 Minuten mit Fischsauce, Salz und Kandiszucker. Probiere und stelle ab: kräftig, leicht süßlich, mit klarer Hühnernote. Fülle bei Bedarf kochendes Wasser nach.","dauer":90,"tipp":"Die Brühe schmeckt leicht überwürzt am besten, denn die Nudeln verdünnen."},{"titel":"Abseihen und entfetten","aktion":"abseihen","text":"Hebe Knochen, Zwiebeln, Ingwer und Gewürzbeutel aus dem Topf und seihe die Brühe durch ein feines, mit Tuch ausgelegtes Sieb in einen sauberen Topf. Schöpfe den Fettfilm mit einer flachen Kelle ab, ein wenig Fett darf bleiben, denn es trägt Aroma. Die Brühe soll klar und goldgelb sein. Wenn sie sehr fettig ist, stelle sie kurz in den Kühlschrank, das Fett steigt dann nach oben und ist leicht zu entfernen.","dauer":10,"tipp":"Brühe kann 3 Tage im Kühlschrank oder mehrere Monate eingefroren aufbewahrt werden."},{"titel":"Nudeln und Garnitur vorbereiten","aktion":"blanchieren","text":"Weiche getrocknete Reisbandnudeln 20 Minuten in lauwarmem Wasser ein. Blanchiere eine Portion Nudeln in kochendem Wasser 10 bis 20 Sekunden, bis sie weich sind, und gib sie sofort in vorgewärmte Schüsseln. Schneide Limettenblätter in feine Streifen, hacke Rau răm und Frühlingszwiebeln und lege die Zwiebelringe in Eiswasser. Richte Chili, Limetten und Pfeffer auf dem Tisch an.","dauer":5,"tipp":"Limettenblätter möglichst fein schneiden: Sie sind zäh und geben ihr Aroma über die Schnittfläche."},{"titel":"Schüsseln füllen und servieren","aktion":"anrichten","text":"Lege Hühnerfleisch auf die Nudeln, gib Zwiebelringe, Frühlingszwiebeln und Limettenblätter dazu und gieße kochend heiße Brühe darüber. Gib frisch gemahlenen Pfeffer, Rau răm und Chili dazu und serviere sofort. Am Tisch presst jeder Limettensaft hinein. Die Brühe soll golden und klar, das Fleisch weiß und saftig, die Nudeln weich sein. In Hanoi isst man Phở gà häufig mit etwas Hühnerhaut und frischen Kräutern.","dauer":0,"tipp":"Brühe wirklich kochend heiß eingießen, sonst kühlen Nudeln und Fleisch sie sofort ab."}],"profitipps":["Huhn nach dem Pochieren in Eiswasser legen, damit Haut und Fleisch saftig bleiben.","Knochen nach dem Auslösen zurück in den Topf: Dort entsteht die eigentliche Tiefe.","Brühe nur leise ziehen lassen, nie kräftig kochen.","Gewürze zurückhaltender dosieren als bei Rind-Phở.","Limettenblätter fein schneiden und erst in der Schüssel zugeben.","Brühe leicht überwürzen, da Nudeln und Fleisch ungewürzt sind."],"varianten":["Phở gà trộn: ohne Brühe, mit Hühnerfleisch, Kräutern und Dressing als Nudelsalat","Mit Hühnerklein (Magen, Herz) wie in Hanoi üblich","Mit unreifen Eiern aus dem Huhn (Trứng non) als Spezialität für Kenner","Vegetarische Variante mit Pilzbrühe"],"beilagen":["Kräuterteller mit Rau răm, Minze, Koriander","Limetten und Chili","Chili-Knoblauch-Essig als Tischwürze"],"getraenk":"Jasmintee, Zitronenlimonade oder ein leichtes Pils","koeche":[{"name":"Andrea Nguyen","bezug":"Zeigt in ihrer Hühner-Phở (zum Beispiel als Schnellkochtopf-Version), wie eine klare, aromatische Brühe mit einem ganzen Huhn, geröstetem Ingwer und Zwiebel, angerösteten Koriandersamen und Nelken gelingt; gewürzt wird mit Fischsauce, Salz und Zucker.","quelle":"https://sunset.com/food-wine/kitchen-assistant/pho-soup-recipe"}],"quellen":[{"titel":"Andrea Nguyen cracks the code of making pho for the home cook – Sunset","url":"https://sunset.com/food-wine/kitchen-assistant/pho-soup-recipe"},{"titel":"Pressure Cooker Chicken Pho – Sunset","url":"https://sunset.com/recipe/pressure-cooker-chicken-pho"},{"titel":"22 Vietnamese noodle soups named among world's best by TasteAtlas – VOV","url":"https://vov.gov.vn/22-vietnamese-noodle-soups-named-among-worlds-best-by-tasteatlas-dtnew-1096974"}],"bild":"suppe","farben":["#e8c36a","#f4ead2","#6fa04b"],"schlagworte":["Nudelsuppe","Hühnerbrühe","Hanoi","leicht"],"vegetarisch_moeglich":false},{"id":"vietnam-com-tam","name":"Cơm Tấm (Bruchreis mit Schweinekotelett)","originalname":"Cơm tấm sườn bì chả","kueche":"vietnam","region":"Saigon / Südvietnam","beliebtheit":82,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Der Saigoner Teller schlechthin: duftender Bruchreis mit gegrilltem Zitronengras-Kotelett, gedämpftem Ei-Hackfleisch-Kuchen, Spiegelei, Frühlingszwiebelöl und süßsaurer Fischsauce.","hintergrund":"Cơm tấm heißt „Bruchreis“ und bezeichnet in Saigon sowohl die Reissorte als auch das Gericht, das darauf serviert wird. Der Bruchreis fiel früher bei der Verarbeitung als Abfall an und wurde zur Alltagskost der einfachen Leute, bis er in den Straßenküchen von Saigon zum Kult wurde. Der klassische Teller, „cơm tấm sườn bì chả“, vereint ein über Kohle gegrilltes, mit Zitronengras mariniertes Schweinekotelett (sườn), Streifen von Schweinefleisch und -haut mit geröstetem Reismehl (bì) und einen gedämpften Kuchen aus Hackfleisch, Ei und Glasnudeln (chả trứng). Dazu kommen Spiegelei, Frühlingszwiebelöl (mỡ hành), Gurke, Tomate und süßsaure Nước mắm. Der Reis ist kleiner und weicher als Jasminreis und nimmt Sauce hervorragend auf.","portionen":4,"zeit":{"vorbereitung":50,"garen":50,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Kotelett (Sườn nướng)","liste":[{"menge":700,"einheit":"g","name":"Schweinekoteletts oder Nackensteaks, ca. 1,5 cm dick","hinweis":"Knochen darf dran bleiben"},{"menge":2,"einheit":"Stange","name":"Zitronengras, nur das Weiße, sehr fein gehackt","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Schalotten, fein gehackt","hinweis":""},{"menge":2,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Austernsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Sojasauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Honig","hinweis":""},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"EL","name":"neutrales Öl","hinweis":""},{"menge":0.5,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":""}]},{"gruppe":"Für den Ei-Hackfleisch-Kuchen (Chả trứng)","liste":[{"menge":200,"einheit":"g","name":"Schweinehack","hinweis":""},{"menge":3,"einheit":"Stück","name":"Eier (Größe M)","hinweis":""},{"menge":20,"einheit":"g","name":"Glasnudeln, eingeweicht und kleingeschnitten","hinweis":""},{"menge":10,"einheit":"g","name":"getrocknete Mu-Err-Pilze, eingeweicht und gehackt","hinweis":"optional"},{"menge":1,"einheit":"Stück","name":"Schalotte, fein gehackt","hinweis":""},{"menge":1,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":0.5,"einheit":"TL","name":"weißer Pfeffer","hinweis":""},{"menge":1,"einheit":"Stück","name":"Eigelb zum Bestreichen","hinweis":"für die goldene Oberfläche"}]},{"gruppe":"Reis, Ei und Beilagen","liste":[{"menge":320,"einheit":"g","name":"Bruchreis (Gạo tấm)","hinweis":"im Asialaden; ersatzweise Jasminreis"},{"menge":350,"einheit":"ml","name":"Wasser für den Reis","hinweis":"Bruchreis braucht weniger Wasser als Jasminreis"},{"menge":4,"einheit":"Stück","name":"Eier für Spiegeleier","hinweis":""},{"menge":4,"einheit":"Stück","name":"Frühlingszwiebeln, fein geschnitten","hinweis":"für das Frühlingszwiebelöl"},{"menge":3,"einheit":"EL","name":"neutrales Öl","hinweis":"für das Frühlingszwiebelöl"},{"menge":1,"einheit":"Stück","name":"Salatgurke, in Scheiben","hinweis":""},{"menge":2,"einheit":"Stück","name":"Tomaten, in Scheiben","hinweis":""}]},{"gruppe":"Für die Nước mắm (Würzsauce)","liste":[{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":3,"einheit":"EL","name":"Limettensaft","hinweis":""},{"menge":100,"einheit":"ml","name":"warmes Wasser","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":1,"einheit":"Stück","name":"Chilischote, gehackt","hinweis":"optional"}]}],"ausruestung":["Grillpfanne oder Holzkohlegrill","Dämpfer oder großer Topf mit Dämpfeinsatz","flache hitzefeste Schale (ca. 18 cm)","Reiskocher oder Topf mit Deckel","Pfanne für die Spiegeleier"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Stelle alle Zutaten bereit und plane die Reihenfolge: Das Kotelett braucht Marinierzeit, der Hackkuchen Dämpfzeit, der Reis Ruhezeit. Hacke Zitronengras, Knoblauch und Schalotten fein, weiche Glasnudeln und Pilze in warmem Wasser ein und schneide sie klein. Schneide Gurke und Tomaten in Scheiben und hole die Eier aus dem Kühlschrank, damit sie beim Braten nicht ganz kalt sind. Wasche den Bruchreis in mehreren Wassern, bis es klar bleibt.","dauer":0,"tipp":"Beginne mit der Marinade; sie braucht die längste Zeit."},{"titel":"Kotelett marinieren","aktion":"marinieren","text":"Vermische Zitronengras, Knoblauch, Schalotten, Fischsauce, Austernsauce, Sojasauce, Honig, Zucker, Öl und Pfeffer zu einer Paste. Klopfe die Koteletts mit dem Fleischklopfer auf etwa 1 cm flach, damit sie gleichmäßig garen und zart werden, und schneide am Rand mehrmals ein, damit sie sich beim Grillen nicht wölben. Reibe die Marinade kräftig ein und lass das Fleisch zugedeckt mindestens 2 Stunden, besser über Nacht, im Kühlschrank ziehen. Der Zucker sorgt später für Glanz und eine dunkle Kruste.","dauer":120,"tipp":"Das Plattklopfen ist der Schlüssel: Dünne Koteletts werden zart statt zäh."},{"titel":"Nước mắm anrühren","aktion":"mischen","text":"Löse Zucker im warmen Wasser auf, rühre Fischsauce und Limettensaft ein und gib Knoblauch und Chili dazu. Probiere: Die Sauce soll süß, salzig, sauer und leicht scharf sein, ohne dass ein Geschmack dominiert. Gib bei Bedarf etwas Wasser oder Limette dazu. Sie wird über Reis und Fleisch geträufelt und ist das Bindeglied des Tellers; stelle sie bis zum Servieren beiseite, damit der Knoblauch Zeit zum Ziehen hat.","dauer":5,"tipp":"Lauwarmes Wasser löst Zucker schneller und lässt den Knoblauch milder wirken."},{"titel":"Hackfleischmasse vorbereiten","aktion":"mischen","text":"Verrühre Hack, drei Eier, Glasnudeln, Pilze, Schalotte, Fischsauce, Zucker und Pfeffer kräftig, bis eine homogene Masse entsteht, und fülle sie in eine leicht geölte, flache hitzefeste Schale. Verstreiche die Oberfläche glatt. Verquirle ein weiteres Eigelb und streiche es auf, das gibt später eine goldene Oberfläche. Die Masse sollte weich und gleichmäßig sein, nicht flüssig und nicht fest. Wer mag, drückt einige Pilzstücke oben ein.","dauer":10,"tipp":"Alles gründlich vermischen: Klumpen im Hackfleisch geben später eine bröckelige Textur."},{"titel":"Chả trứng dämpfen","aktion":"daempfen","text":"Stelle die Schale in einen Dämpfer über sprudelnd kochendem Wasser und dämpfe sie zugedeckt 25 bis 30 Minuten. Der Kuchen ist fertig, wenn die Oberfläche fest und goldgelb ist und beim Einstechen mit einem Spieß klarer Saft austritt. Tupfe etwas Kondenswasser vom Deckel ab, damit es nicht auf den Kuchen tropft. Nimm die Schale heraus, lass sie 5 Minuten ruhen und schneide den Kuchen in Rauten oder Quadrate. Wer mag, bräunt die Oberfläche kurz unter dem Backofengrill.","dauer":30,"tipp":"Ein Tuch unter den Deckel legen, damit Kondenswasser nicht in den Kuchen tropft."},{"titel":"Reis kochen","aktion":"kochen","text":"Gib den gewaschenen Bruchreis mit 350 ml Wasser in einen Topf, bringe es zum Kochen, reduziere die Hitze auf kleinste Stufe und lass den Reis zugedeckt 12 bis 15 Minuten garen. Nimm den Topf vom Herd und lass den Reis 10 Minuten zugedeckt nachquellen. Lockere ihn mit einer Gabel auf. Der Reis soll weich und leicht klebrig sein, die Körner kleiner und unregelmäßiger als bei Jasminreis. Halte ihn warm.","dauer":25,"tipp":"Bruchreis braucht wenig Wasser: Zu viel macht ihn matschig."},{"titel":"Frühlingszwiebelöl zubereiten","aktion":"braten","text":"Gib die fein geschnittenen Frühlingszwiebeln mit einer Prise Salz in eine hitzefeste Schale. Erhitze das Öl in einem kleinen Topf, bis es leicht raucht, und gieße es über die Zwiebeln: Es zischt und duftet sofort süßlich nach Zwiebel. Rühre einmal um. Das Öl gart die Zwiebeln kurz an und färbt sich leicht grünlich. Es wird später über Reis und Fleisch geträufelt und gibt dem Teller seinen typischen Glanz.","dauer":5,"tipp":"Das Öl nicht zu heiß werden lassen, sonst verbrennen die Zwiebeln und schmecken bitter."},{"titel":"Kotelett grillen","aktion":"grillen","text":"Heize Holzkohlegrill oder Grillpfanne auf mittlere bis hohe Hitze (ca. 200 °C) und tupfe überschüssige Marinade ab, damit Zucker und Knoblauch nicht verbrennen. Grille die Koteletts 3 bis 4 Minuten pro Seite, bis sie goldbraun und am Rand dunkel karamellisiert sind; die Kerntemperatur sollte 70 °C erreichen. Bestreiche sie während des Grillens mit etwas Marinade oder Honig, damit sie glänzen. Lass sie 3 Minuten ruhen, damit der Saft sich verteilt.","dauer":10,"tipp":"Grill nicht zu heiß: Zucker verbrennt schnell. Lieber etwas länger bei mittlerer Hitze."},{"titel":"Spiegeleier braten","aktion":"braten","text":"Erhitze Öl in einer Pfanne bei mittlerer Hitze, schlage die Eier hinein und brate sie, bis das Eiweiß gestockt und der Rand am Boden leicht knusprig ist, während das Eigelb noch weich ist (ca. 2 bis 3 Minuten). Würze mit einer Prise Salz und Pfeffer. Ein weiches Eigelb dient später als zusätzliche Sauce zum Reis, gerade im Zusammenspiel mit der süßsauren Nước mắm.","dauer":4,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Häufe den Bruchreis auf einen flachen Teller, lege Kotelett, ein Stück Chả trứng, Spiegelei sowie Gurken- und Tomatenscheiben daneben. Träufle Frühlingszwiebelöl über Reis und Fleisch und gib die Nước mắm in ein kleines Schälchen daneben. Gegessen wird mit Löffel und Gabel: Reis mit Sauce beträufeln, ein Stück Kotelett und etwas Ei dazu nehmen. Serviere sofort, damit alles warm bleibt.","dauer":0,"tipp":"Das Frühlingszwiebelöl macht den Unterschied: Nicht sparen."}],"profitipps":["Koteletts dünn klopfen und einschneiden, damit sie gleichmäßig garen und zart werden.","Marinade mit Zucker und Honig sorgt für Glanz und leichte Karamellisierung, aber nicht zu heiß grillen.","Bruchreis braucht weniger Wasser als Jasminreis.","Frühlingszwiebelöl kurz vor dem Servieren zubereiten, damit es frisch duftet.","Hackkuchen langsam dämpfen, damit er gleichmäßig stockt und keine Blasen bekommt.","Nước mắm vorher anrühren und ziehen lassen."],"varianten":["Cơm tấm sườn bì chả: mit Schweinehaut-Streifen (bì) und geröstetem Reismehl (thính)","Cơm tấm gà nướng: mit gegrilltem Hähnchen statt Schwein","Cơm tấm sườn nướng trứng: nur Kotelett und Spiegelei","Cơm tấm mit gegrillten Garnelen statt Kotelett"],"beilagen":["Gurken- und Tomatenscheiben","eingelegte Möhren und Rettich (Đồ chua)","klare Gemüsebrühe (Canh)"],"getraenk":"Eistee, Zuckerrohrsaft oder ein leichtes Pils","koeche":[],"quellen":[{"titel":"Bun cha (char-grilled pork, noodles and nuoc cham) – Luke Nguyen, SBS Food (Kontext: Marinade für gegrilltes Schweinefleisch)","url":"https://www.sbs.com.au/food/recipes/bun-cha-char-grilled-pork-noodles-and-nuoc-cham"},{"titel":"Vietnamese Bun Cha Recipe – Grantourismo (Kontext: Nước-chấm-Verhältnisse)","url":"https://grantourismotravels.com/vietnamese-bun-cha-recipe/"}],"bild":"reis","farben":["#c9843a","#f4ead2","#6fa04b"],"schlagworte":["Saigon","Reisteller","Streetfood","Grill","Frühstück"],"vegetarisch_moeglich":false},{"id":"vietnam-cha-ca-la-vong","name":"Chả Cá Lã Vọng – Hanoi-Fisch mit Kurkuma und Dill","originalname":"Chả Cá Lã Vọng","kueche":"vietnam","region":"Hanoi","beliebtheit":80,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Gelb leuchtende Fischstücke, in Kurkuma und Galgant mariniert und mit Unmengen von Dill und Frühlingszwiebeln in der Pfanne geschwenkt, dazu Reisnudeln, Erdnüsse, Kräuter und eine pikante Dipsauce.","hintergrund":"Chả Cá Lã Vọng ist das Wahrzeichen der Hanoier Küche. Es soll aus einer Familienküche in der Altstadt stammen, deren Restaurant bis heute in der Straße Chả Cá steht. Traditionell wird das Gericht am Tisch gebraten: Auf einem Kohle- oder Gasbrenner steht eine Pfanne, in der die Gäste die gelb marinierten Fischstücke zusammen mit Dill und Frühlingszwiebeln selbst fertig garen. Dazu gibt es Reisnudeln (Bún), geröstete Erdnüsse, frische Kräuter und eine Dipsauce, oft mit der berühmt-berüchtigten fermentierten Garnelenpaste Mắm Tôm. Dill ist in der vietnamesischen Küche sonst selten, hier aber unverzichtbar.","portionen":4,"zeit":{"vorbereitung":35,"garen":15,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch und Marinade","liste":[{"menge":800,"einheit":"g","name":"festfleischiges Fischfilet ohne Haut (Wels, Pangasius, Zander, Seeteufel oder Kabeljau)","hinweis":"in Vietnam Riesenwels (Cá Lăng); in Deutschland gut Wels oder Zander von der Fischtheke"},{"menge":1,"einheit":"EL","name":"Kurkumapulver","hinweis":"oder 3 cm frische Kurkuma, gerieben"},{"menge":2,"einheit":"TL","name":"frischer Galgant, gerieben","hinweis":"Asia-Laden, ersatzweise Ingwer"},{"menge":3,"einheit":"Stück","name":"Schalotten, sehr fein gehackt","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":2,"einheit":"EL","name":"Naturjoghurt","hinweis":"ersetzt das traditionelle Mẻ (fermentierter Reis)"},{"menge":4,"einheit":"EL","name":"neutrales Öl","hinweis":""}]},{"gruppe":"Zum Pfannengaren und Servieren","liste":[{"menge":2,"einheit":"Bund","name":"frischer Dill","hinweis":"mindestens 100 g; wichtigste Zutat, Dill ist hier Gemüse, nicht Garnitur"},{"menge":6,"einheit":"Stück","name":"Frühlingszwiebeln","hinweis":"in 4 cm langen Stücken"},{"menge":250,"einheit":"g","name":"Reisvermicelli (Bún), gekocht","hinweis":""},{"menge":60,"einheit":"g","name":"geröstete Erdnüsse, grob gehackt","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander, Minze oder Thai-Basilikum","hinweis":"frisch"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":""}]},{"gruppe":"Dipsauce","liste":[{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":"oder 1 EL Mắm Tôm für die authentische Variante"},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":3,"einheit":"EL","name":"Limettensaft","hinweis":""},{"menge":100,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":2,"einheit":"Stück","name":"rote Chilischoten","hinweis":""}]}],"ausruestung":["große flache Pfanne oder Wok","Mörser","Schüssel zum Marinieren"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide den Fisch in 3–4 cm große Stücke, damit er in der Pfanne rasch gart und nicht zerfällt. Hacke Schalotten und Knoblauch sehr fein, reibe Galgant und, falls du frische Kurkuma hast, auch diese auf einer Mikroreibe. Schneide die Frühlingszwiebeln in 4 cm Stücke und trenne die weißen von den grünen Teilen, denn die weißen kommen in die Marinade. Zupfe Dill und die anderen Kräuter ab und stelle alle Zutaten in Schüsseln bereit.","dauer":0,"tipp":""},{"titel":"Marinade ansetzen","aktion":"marinieren","text":"Zerstoße die weißen Teile der Frühlingszwiebeln mit Knoblauch, Schalotten, Galgant und Zucker im Mörser zu einer feuchten Paste. Vermenge sie mit Kurkuma, Fischsauce, Joghurt und 2 EL Öl. Die Marinade soll tiefgelb sein und kräftig nach Ingwer und Knoblauch duften. Der Joghurt ersetzt das traditionelle Mẻ und macht den Fisch zart, weil seine milde Säure das Eiweiß etwas aufschließt.","dauer":0,"tipp":""},{"titel":"Fisch marinieren","aktion":"marinieren","text":"Wende die Fischstücke in der Marinade, bis jedes Stück ringsum bedeckt ist, und decke die Schüssel ab. Lass den Fisch mindestens 1 Stunde im Kühlschrank ziehen, bis zu 3 Stunden sind ideal. Kurkuma färbt Finger und Schneidebretter intensiv gelb, deshalb Einweghandschuhe tragen oder gleich spülen. Länger als einen halben Tag solltest du nicht marinieren, sonst wird das Fleisch durch die Säure leicht mehlig.","dauer":60,"tipp":""},{"titel":"Dipsauce anrühren","aktion":"mischen","text":"Löse den Zucker im Wasser, gib Fischsauce und Limettensaft dazu und schmecke ab: Die Sauce soll süß-sauer-salzig im Gleichgewicht sein. Schneide die Chili in feine Ringe, hacke etwas Knoblauch und rühre alles ein. Wer es authentisch mag, rührt 1 EL Mắm Tôm (Garnelenpaste) mit einem Schuss Limette und Zucker glatt; sie riecht sehr intensiv, schmeckt gekocht aber würzig-fruchtig. Fülle die Sauce in kleine Schälchen für jeden Gast.","dauer":0,"tipp":""},{"titel":"Nudeln kochen und Beilagen richten","aktion":"kochen","text":"Koche die Reisvermicelli nach Packungsanleitung in reichlich Wasser 3 bis 5 Minuten, bis sie weich, aber noch leicht bissfest sind, schrecke sie kalt ab und lass sie abtropfen. Dadurch wird die Stärke abgespült und die Nudeln kleben nicht zusammen. Richte sie mit Kräutern, Erdnüssen und Limettenspalten auf einer Platte an, damit jeder am Tisch seine Schüssel zusammenstellen kann.","dauer":5,"tipp":""},{"titel":"Fisch braten","aktion":"braten","text":"Erhitze 2 EL Öl in einer großen Pfanne bei mittlerer bis hoher Hitze, bis es leicht schimmert. Nimm die Fischstücke aus der Marinade, streife überschüssige Paste ab (sie verbrennt) und brate sie 2 bis 3 Minuten auf der ersten Seite, ohne zu bewegen, bis sich eine goldgelbe Kruste gebildet hat. Wende sie vorsichtig mit einem Fischspatel, bevor sie am Boden haften; ein Fisch löst sich von allein, wenn die Kruste fertig ist. Brate die zweite Seite noch 1 bis 2 Minuten.","dauer":5,"tipp":"Nicht zu viele Stücke gleichzeitig braten, sonst dünstet der Fisch statt zu braten."},{"titel":"Dill und Frühlingszwiebeln zugeben","aktion":"braten","text":"Gib die grünen Frühlingszwiebelstücke und einen großen Teil des Dills zum Fisch in die Pfanne und schwenke sie 30 bis 60 Sekunden mit, bis sie gerade zusammenfallen, aber noch hellgrün sind. Dill verliert in der Hitze sehr schnell sein Aroma, deshalb darf er nur kurz erhitzt werden. Der Duft nach frischem Dill und Kurkuma ist das Markenzeichen des Gerichts. Zum Schluss gibst du einen Spritzer Limette dazu.","dauer":1,"tipp":""},{"titel":"Servieren am Tisch","aktion":"anrichten","text":"Bringe die Pfanne direkt auf den Tisch (auf einem Stövchen oder Gaskocher) und stelle Nudeln, Erdnüsse, Kräuter und Dipsauce daneben. Jeder nimmt Nudeln in seine Schüssel, legt Fisch mit Dill darauf, streut Erdnüsse und Kräuter darüber und gibt Dipsauce nach Belieben dazu. Das Gericht lebt von diesem Zusammenspiel: weicher Fisch, knusprige Erdnüsse, frische Kräuter und die salzig-scharfe Sauce.","dauer":0,"tipp":""}],"profitipps":["Dill nicht sparen – in Hanoi bedeckt er den Fisch fast komplett.","Marinadepaste vor dem Braten abstreifen, sonst verbrennt die Kurkuma.","Wels, Zander oder Seeteufel bleiben beim Braten fest; zartes Filet zerfällt.","Das Gericht schmeckt am besten frisch aus der Pfanne am Tisch.","Dipsauce vorher abschmecken – süß-sauer-salzig muss im Gleichgewicht sein."],"varianten":["Chả Cá Thăng Long: ähnliche Fassung mit Zitronengras und Chili","Gegrillt über Holzkohle statt gebraten","Mit Mắm Tôm-Dip nach Hanoier Art","Als Reisbowl mit Gurke und Salat"],"beilagen":["Reisvermicelli (Bún)","geröstete Erdnüsse","frische Kräuter","Nước Chấm"],"getraenk":"Bia Hơi oder ein kühler Pinot Gris","koeche":[{"name":"Luke Nguyen","bezug":"Der australisch-vietnamesische Koch hat bei SBS eine Fassung mit Kurkuma, Curry, Joghurt und Dill veröffentlicht, die den Fisch mariniert, anbrät und mit Nudeln und Sprossen serviert.","quelle":"https://www.sbs.com.au/food/recipe/fish-pan-fried-with-turmeric-and-dill-cha-ca-hanoi/1g1k42zfy"}],"quellen":[{"titel":"SBS Food – Fish pan-fried with turmeric and dill (Chả Cá Hanoi), Luke Nguyen","url":"https://www.sbs.com.au/food/recipe/fish-pan-fried-with-turmeric-and-dill-cha-ca-hanoi/1g1k42zfy"},{"titel":"Kvalifood – Chả Cá Lã Vọng","url":"https://kvalifood.com/posts/cha-ca-la-vong-hanoi-turmeric-fish/"},{"titel":"Posh Journal – Cha Ca Vietnamese Turmeric Fish","url":"https://poshjournal.com/cha-ca-vietnamese-turmeric-fish"}],"bild":"fisch","farben":["#e8b82a","#7a9a3c","#f1ead0"],"schlagworte":["Hanoi","Kurkuma","Dill","Pfannengericht"],"vegetarisch_moeglich":false},{"id":"vietnam-banh-xeo","name":"Bánh Xèo (Knusprige Reismehl-Crêpes)","originalname":"Bánh xèo","kueche":"vietnam","region":"Südvietnam (Mekong-Delta) und Zentralvietnam","beliebtheit":80,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Goldgelbe, am Rand splitternd knusprige Crêpes aus Reismehl und Kokosmilch, gefüllt mit Schweinebauch, Garnelen und Sprossen – gewickelt in Salat und Kräuter und in Nước chấm getunkt.","hintergrund":"Bánh xèo bedeutet „zischender Pfannkuchen“, benannt nach dem Geräusch, das der Teig beim Hineingießen in die heiße Pfanne macht. Die Crêpe wird aus Reismehl, Wasser, Kokosmilch und Kurkuma zubereitet, was ihr die gelbe Farbe gibt, und mit Schweinebauch, Garnelen, Zwiebel und Mungobohnensprossen gefüllt. In Südvietnam sind die Pfannkuchen groß und dünn, in Zentralvietnam kleiner und dicker; die Huế-Variante heißt Bánh khoai. Gegessen wird mit den Händen: Man bricht ein Stück ab, wickelt es mit frischen Kräutern in ein Salat- oder Senfblatt und taucht es in süßsaure Fischsauce. Die Kombination aus knuspriger Kruste, saftiger Füllung und frischen Kräutern ist das Besondere.","portionen":4,"zeit":{"vorbereitung":40,"garen":45,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig (ca. 8 Crêpes)","liste":[{"menge":200,"einheit":"g","name":"Reismehl","hinweis":"kein Klebreismehl"},{"menge":2,"einheit":"EL","name":"Speisestärke oder Tapiokastärke","hinweis":"für mehr Knusprigkeit"},{"menge":1,"einheit":"TL","name":"Kurkumapulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":200,"einheit":"ml","name":"Kokosmilch","hinweis":"ungesüßt, gut geschüttelt"},{"menge":300,"einheit":"ml","name":"kaltes Wasser oder Sodawasser","hinweis":"Sodawasser macht den Teig luftiger"},{"menge":3,"einheit":"Stück","name":"Frühlingszwiebeln, in feine Ringe","hinweis":""}]},{"gruppe":"Für die Füllung","liste":[{"menge":250,"einheit":"g","name":"Schweinebauch ohne Schwarte, dünn aufgeschnitten","hinweis":"angefroren lässt er sich leichter schneiden"},{"menge":250,"einheit":"g","name":"Garnelen, geschält","hinweis":"halbiert"},{"menge":1,"einheit":"Stück","name":"Zwiebel, in dünne Ringe","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, gehackt","hinweis":""},{"menge":200,"einheit":"g","name":"Mungobohnensprossen","hinweis":""},{"menge":80,"einheit":"g","name":"gelbe Mungbohnenkerne, gekocht","hinweis":"optional"},{"menge":1,"einheit":"EL","name":"Fischsauce","hinweis":"zum Würzen der Füllung"},{"menge":6,"einheit":"EL","name":"neutrales Öl","hinweis":"zum Ausbacken"}]},{"gruppe":"Zum Wickeln und Dippen","liste":[{"menge":1,"einheit":"Stück","name":"grüner Salat oder Senfblätter","hinweis":"zum Wickeln"},{"menge":1,"einheit":"Bund","name":"Minze, Koriander, Thai-Basilikum, Perilla","hinweis":"gemischt"},{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":"für Nước chấm"},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":"für Nước chấm"},{"menge":3,"einheit":"EL","name":"Limettensaft","hinweis":"für Nước chấm"},{"menge":100,"einheit":"ml","name":"Wasser","hinweis":"für Nước chấm"},{"menge":1,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":"für Nước chấm"},{"menge":1,"einheit":"Stück","name":"Chilischote, gehackt","hinweis":"optional"}]}],"ausruestung":["beschichtete oder gut eingebrannte Pfanne (ca. 24 cm) mit Deckel","Schneebesen","Schöpfkelle","Pfannenwender","Teller oder Backblech zum Warmhalten"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Reismehl, Stärke und Gewürze ab und stelle Kokosmilch und Wasser bereit. Schneide den Schweinebauch in dünne, 3 mm starke Scheiben und halbiere die Garnelen längs. Hacke Knoblauch, schneide Zwiebel in Ringe und Frühlingszwiebeln in feine Ringe. Wasche Kräuter, Salat und Sprossen und tupfe sie trocken. Das Backen geht schnell: Alle Zutaten müssen griffbereit am Herd liegen.","dauer":0,"tipp":"Fleisch und Garnelen portionsweise abgetrennt bereitlegen, damit du für jeden Crêpe zügig füllen kannst."},{"titel":"Teig anrühren und ruhen lassen","aktion":"mischen","text":"Vermische Reismehl, Stärke, Kurkuma und Salz in einer Schüssel und rühre Kokosmilch und Wasser nach und nach mit dem Schneebesen ein, bis ein glatter, dünnflüssiger Teig entsteht, der wie Sahne vom Löffel läuft. Rühre Frühlingszwiebeln unter. Lass den Teig mindestens 30 Minuten ruhen, damit das Mehl quillt und der Teig geschmeidiger wird; rühre vor dem Backen noch einmal kräftig um, weil sich das Reismehl absetzt.","dauer":30,"tipp":"Ist der Teig zu dick, wird der Crêpe zäh; lieber etwas Wasser zugeben."},{"titel":"Füllung vorbereiten","aktion":"anbraten","text":"Erhitze 1 EL Öl in einer Pfanne bei hoher Hitze und brate den Schweinebauch 2 bis 3 Minuten, bis er am Rand braun wird und Fett abgibt. Gib Knoblauch und Fischsauce dazu, rühre kurz um und nimm das Fleisch heraus. Brate die Garnelen in derselben Pfanne 1 bis 2 Minuten, bis sie rosa sind, und nimm sie ebenfalls heraus. Das Vorbraten würzt die Füllung und sorgt dafür, dass sie später im Crêpe nicht zu lange gart.","dauer":8,"tipp":"Das ausgetretene Fett kann in der Pfanne bleiben: Es gibt dem ersten Crêpe Geschmack."},{"titel":"Nước chấm anrühren","aktion":"mischen","text":"Löse den Zucker im Wasser auf, rühre Fischsauce und Limettensaft ein und gib Knoblauch und Chili dazu. Probiere: Die Sauce soll süß, sauer, salzig und leicht scharf schmecken. Stelle sie beiseite, damit sich die Aromen verbinden. Sie ist der Begleiter zu allem Knusprigen, denn sie bringt Säure, die das Fett ausgleicht.","dauer":5,"tipp":"Frische Limette statt Zitrone verwenden; sie bringt das typische Aroma."},{"titel":"Pfanne vorheizen und Teig eingießen","aktion":"braten","text":"Erhitze die Pfanne bei mittlerer bis hoher Hitze, bis ein Wassertropfen sofort zischt, und gib 1 EL Öl hinein. Rühre den Teig um, gieße etwa 100 ml (eine halbe Schöpfkelle) hinein und schwenke die Pfanne sofort, damit der Teig dünn verläuft. Es zischt laut, daher der Name. Verteile einige Schweinebauchscheiben, Garnelen, Zwiebelringe und eine Handvoll Sprossen auf einer Hälfte des Crêpes.","dauer":2,"tipp":"Die Pfanne muss wirklich heiß sein; in einer kühlen Pfanne klebt der Teig."},{"titel":"Knusprig backen","aktion":"braten","text":"Setze den Deckel auf und lass den Crêpe 2 Minuten dämpfen, damit die Füllung gar wird. Nimm den Deckel ab, reduziere die Hitze auf mittel und brate den Crêpe 3 bis 5 Minuten weiter, bis der Rand sich löst und goldbraun und knusprig ist. Träufle bei Bedarf etwas Öl am Rand entlang, damit er schön knackig wird. Es duftet nach Kokos und Kurkuma. Der Boden sollte gleichmäßig goldbraun sein.","dauer":6,"tipp":"Nicht zu früh bewegen: Der Crêpe löst sich von selbst, wenn er knusprig ist."},{"titel":"Falten und herausnehmen","aktion":"fuellen","text":"Klappe die unbelegte Hälfte des Crêpes mit einem Pfannenwender über die Füllung und schiebe ihn vorsichtig auf einen Teller. Halte ihn bis zum Servieren im Ofen bei 80 °C warm, damit er nicht weich wird. Wische die Pfanne mit etwas Öl aus und wiederhole den Vorgang mit dem restlichen Teig, bis alle acht Crêpes fertig sind. Der erste Crêpe misslingt oft; er dient dazu, die Hitze zu justieren.","dauer":20,"tipp":"Crêpes nicht stapeln, sonst werden sie weich; nebeneinander im Ofen warm halten."},{"titel":"Servieren und essen","aktion":"anrichten","text":"Serviere die Crêpes sofort mit Salatblättern, Kräutern und Nước chấm. Gegessen wird mit den Händen: Reiße ein Stück Crêpe ab, lege es in ein Salatblatt, füge Kräuter hinzu, wickle alles zusammen und tauche es in die Sauce. Die Kombination aus knuspriger Kruste, saftiger Füllung, frischen Kräutern und süßsaurer Sauce ist das Besondere. Achte darauf, dass die Crêpes heiß sind, wenn sie auf den Tisch kommen.","dauer":0,"tipp":"Wer mag, ergänzt Erdnüsse oder Röstzwiebeln zum Bestreuen."}],"profitipps":["Teig ruhen lassen und vor dem Backen umrühren: Das Reismehl setzt sich ab.","Pfanne richtig heiß machen: Der Teig muss beim Eingießen laut zischen.","Den Deckel zu Beginn aufsetzen, damit die Füllung gart, dann ohne Deckel knusprig braten.","Dünn gießen: Dicke Crêpes werden zäh statt knusprig.","Crêpes warm halten, aber nicht stapeln.","Mit frischen Kräutern und Salat servieren, das gehört zum Gericht."],"varianten":["Bánh khoai (Huế): kleiner, dicker, mit Hoisin-Erdnuss-Sauce","Bánh xèo miền Tây: groß und dünn, Mekong-Delta-Stil","Bánh xèo chay: vegetarisch mit Pilzen und Tofu","Bánh xèo tôm nhảy: mit kleinen Garnelen in der Schale"],"beilagen":["Salat und Kräuterplatte","Nước chấm","eingelegte Möhren und Rettich"],"getraenk":"Leichtes Pils, Eistee oder Zuckerrohrsaft","koeche":[{"name":"Luke Nguyen","bezug":"Zeigt auf SBS Food die Hue-Version der Reismehl-Pfannkuchen (Bánh khoai) mit Kurkuma-Teig aus Reismehl und Kokosrahm, gefüllt mit Garnelen, Schweinebauch und Sprossen, dazu eine Hoisin-Erdnuss-Sauce; die Crêpe wird in etwa 2 Minuten knusprig gebraten und gefaltet.","quelle":"https://www.sbs.com.au/food/recipes/hue-pancake-banh-khoai"}],"quellen":[{"titel":"Hue pancake (banh khoai) – Luke Nguyen, SBS Food","url":"https://www.sbs.com.au/food/recipes/hue-pancake-banh-khoai"},{"titel":"Luke Nguyen's Vietnam, Season 2 – Episode guide, SBS Food","url":"https://www.sbs.com.au/food/article/luke-nguyens-vietnam-s2-episode-guide/e9jy4bx38"}],"bild":"pfannkuchen","farben":["#e5b83a","#f4e3a8","#6fa04b"],"schlagworte":["Crêpe","Kokos","Kurkuma","Streetfood","Kräuter"],"vegetarisch_moeglich":true},{"id":"vietnam-bun-thit-nuong","name":"Bún Thịt Nướng","originalname":"Bún thịt nướng","kueche":"vietnam","region":"Südvietnam / Saigon","beliebtheit":78,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Die südvietnamesische Nudelschüssel: Zitronengras-Schwein vom Grill auf kalten Reisnudeln, Salat, Kräutern und Gurke, bestreut mit Erdnüssen und Röstzwiebeln und mit süßsaurer Fischsauce übergossen.","hintergrund":"Bún thịt nướng ist das Saigoner Gegenstück zum Hanoier Bún chả: Das gegrillte Fleisch liegt hier nicht in einer warmen Brühe, sondern auf einer Schüssel aus kalten Reisnudeln, Salat und frischen Kräutern, und die Nước chấm wird zum Schluss darübergegossen. Die Marinade mit Zitronengras, Knoblauch, Schalotten und Zucker karamellisiert beim Grillen zu einer glänzenden, leicht süßen Kruste. Erdnüsse, Röstzwiebeln und Frühlingszwiebelöl geben Biss und Duft, und oft liegen in der Schüssel auch Stücke von frittierten Frühlingsrollen (Chả giò). Das Gericht gilt als beliebtes Mittagessen: leicht, frisch und doch sättigend.","portionen":4,"zeit":{"vorbereitung":40,"garen":15,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Fleisch","liste":[{"menge":600,"einheit":"g","name":"Schweinenacken, in 4 mm dünne Scheiben geschnitten","hinweis":"ersatzweise Schweineschulter oder Bauch"},{"menge":2,"einheit":"Stange","name":"Zitronengras, nur das Weiße, sehr fein gehackt","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Schalotten, fein gehackt","hinweis":""},{"menge":2,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Sojasauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Austernsauce","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"EL","name":"Honig","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":""},{"menge":1,"einheit":"EL","name":"neutrales Öl","hinweis":""}]},{"gruppe":"Für die Schüssel","liste":[{"menge":400,"einheit":"g","name":"Reisvermicelli (Bún)","hinweis":""},{"menge":1,"einheit":"Stück","name":"Kopfsalat oder Eisbergsalat, in Streifen","hinweis":""},{"menge":1,"einheit":"Stück","name":"Salatgurke, in dünne Streifen","hinweis":""},{"menge":200,"einheit":"g","name":"Mungobohnensprossen","hinweis":""},{"menge":1,"einheit":"Bund","name":"Minze, Perilla und Thai-Basilikum","hinweis":"gemischt"},{"menge":100,"einheit":"g","name":"Möhren und Rettich, in feine Streifen","hinweis":"für schnelle Pickles"},{"menge":50,"einheit":"g","name":"geröstete Erdnüsse, grob gehackt","hinweis":""},{"menge":3,"einheit":"EL","name":"Röstzwiebeln","hinweis":"fertig aus der Tüte oder selbst frittiert"},{"menge":3,"einheit":"Stück","name":"Frühlingszwiebeln, fein geschnitten","hinweis":"für das Frühlingszwiebelöl"},{"menge":3,"einheit":"EL","name":"neutrales Öl","hinweis":"für das Frühlingszwiebelöl"}]},{"gruppe":"Für die Nước chấm","liste":[{"menge":4,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":4,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":4,"einheit":"EL","name":"Limettensaft","hinweis":""},{"menge":200,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch, gehackt","hinweis":""},{"menge":1,"einheit":"Stück","name":"Chilischote, in Ringen","hinweis":""},{"menge":1,"einheit":"EL","name":"Reisessig","hinweis":"für die Pickles"}]}],"ausruestung":["Grillpfanne oder Holzkohlegrill","Topf für Nudeln","kleine Pfanne zum Rösten der Erdnüsse","Schalen für die Zutaten","Einmachglas für die Pickles"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Fleisch quer zur Faser in 4 mm dünne Scheiben; angefroren geht das leichter. Hacke Zitronengras, Knoblauch und Schalotten sehr fein. Wasche Salat, Kräuter und Sprossen, schleudere sie trocken und schneide den Salat in Streifen. Schneide Gurke und Möhren in feine Streifen. Stelle alle Zutaten in Schalen bereit, denn die Schüssel wird am Ende in wenigen Minuten zusammengesetzt.","dauer":0,"tipp":"Von Zitronengras nur das untere Drittel verwenden; die oberen Blätter sind holzig."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Vermische Zitronengras, Knoblauch, Schalotten, Fischsauce, Sojasauce, Austernsauce, Zucker, Honig, Pfeffer und Öl und knete die Mischung in die Fleischscheiben, bis alle Stücke rundum bedeckt sind. Lass das Fleisch abgedeckt mindestens 2 Stunden, besser über Nacht, im Kühlschrank ziehen. Die Marinade würzt tief und der Zucker sorgt später für eine glänzende, karamellisierte Kruste. Nimm das Fleisch 20 Minuten vor dem Grillen heraus.","dauer":120,"tipp":"Nicht länger als 24 Stunden marinieren, sonst wird das Fleisch durch die Fischsauce zu salzig."},{"titel":"Schnelle Pickles ansetzen","aktion":"einlegen","text":"Knete Möhren und Rettich mit 1 TL Salz und 1 TL Zucker 2 Minuten, bis sie Wasser abgeben, spüle sie ab und drücke sie trocken. Übergieße sie in einem Glas mit 100 ml Wasser, 1 EL Reisessig und 1 EL Zucker. Lass sie 30 Minuten durchziehen. Die Pickles bringen eine knackige, süßsaure Note, die das fette Fleisch ausgleicht, und sind ein typischer Bestandteil der südvietnamesischen Nudelschüssel.","dauer":30,"tipp":"Die Pickles halten im Kühlschrank mehrere Wochen."},{"titel":"Nước chấm anrühren","aktion":"mischen","text":"Löse Zucker im Wasser auf, rühre Fischsauce und Limettensaft ein und füge Knoblauch und Chili hinzu. Probiere: Die Sauce soll mild-süß, sauer und salzig sein und deutlich dünner als pure Fischsauce. In diesem Gericht wird sie großzügig über die Nudeln gegossen, deshalb darf sie etwas milder sein als beim Dippen. Stelle sie bis zum Servieren kühl.","dauer":5,"tipp":"Wer es milder möchte, nimmt mehr Wasser und weniger Fischsauce."},{"titel":"Nudeln und Beilagen vorbereiten","aktion":"blanchieren","text":"Koche die Reisvermicelli nach Packungsanleitung (meist 3 bis 5 Minuten), bis sie weich sind, und spüle sie kalt ab. Lass sie gut abtropfen. Röste die Erdnüsse in einer trockenen Pfanne 3 Minuten, bis sie duften, und hacke sie grob. Bereite das Frühlingszwiebelöl zu: Gib Frühlingszwiebeln und eine Prise Salz in eine Schale und gieße heißes Öl darüber, bis es zischt. Rühre um und stelle alles beiseite.","dauer":15,"tipp":"Nudeln nach dem Abspülen mit etwas Öl vermengen, damit sie nicht zusammenkleben."},{"titel":"Fleisch grillen","aktion":"grillen","text":"Heize Grillpfanne oder Holzkohlegrill auf mittlere bis hohe Hitze und tupfe überschüssige Marinade ab, damit der Zucker nicht verbrennt. Grille die Fleischscheiben 2 bis 3 Minuten pro Seite, bis sie dunkel karamellisiert und leicht angekohlt sind. Es duftet nach Zitronengras und Karamell. Lege das Fleisch auf einen Teller und lass es 2 Minuten ruhen. Schneide es bei Bedarf in mundgerechte Stücke.","dauer":12,"tipp":"Fleisch in zwei Durchgängen grillen, damit die Pfanne nicht überfüllt wird und die Scheiben bräunen statt dämpfen."},{"titel":"Schüsseln zusammenstellen","aktion":"schichten","text":"Gib in jede Schüssel zuerst Salat, Gurke und Sprossen, darauf eine Portion Nudeln, dann Kräuter und Pickles. Lege das gegrillte Fleisch obenauf und streue Erdnüsse und Röstzwiebeln darüber. Träufle Frühlingszwiebelöl darüber. Wer hat, legt einige Stücke Chả giò dazu. Die Schichtung ist wichtig: unten das Frische, oben das Warme, damit die Salate nicht welken.","dauer":0,"tipp":""},{"titel":"Servieren und mischen","aktion":"anrichten","text":"Gieße die Nước chấm großzügig über die Schüssel, etwa 4 bis 5 Esslöffel pro Portion. Mische alles mit Stäbchen oder Gabel, sodass Nudeln, Fleisch, Salat und Kräuter mit Sauce überzogen sind. Das Ergebnis soll nass, aber nicht schwimmend sein. Genieße es sofort: Der Kontrast zwischen warmem Fleisch, kalten Nudeln, frischen Kräutern, knusprigen Erdnüssen und süßsaurer Sauce ist das Besondere.","dauer":0,"tipp":"Sauce nach und nach zugeben und zwischendurch probieren."}],"profitipps":["Fleisch dünn schneiden und stark marinieren: So karamellisiert es schnell und wird nicht trocken.","Nudeln nach dem Kochen kalt abspülen und gut abtropfen lassen.","Schüssel in Schichten bauen: Frisches unten, Warmes oben.","Nước chấm erst am Tisch über die Schüssel gießen, damit die Nudeln nicht aufweichen.","Erdnüsse selbst rösten und frisch hacken: Sie duften besser als fertig gekaufte.","Frühlingszwiebelöl macht den Unterschied: Nicht weglassen."],"varianten":["Mit Nem nướng (gegrillte Schweinewurst aus Nha Trang) statt Scheiben","Bún thịt nướng chả giò: Kombination aus gegrilltem Schwein und Frühlingsrollen","Bún gà nướng: mit gegrilltem Hähnchen","Bún tôm nướng: mit gegrillten Garnelen"],"beilagen":["frittierte Frühlingsrollen (Chả giò)","eingelegte Möhren und Rettich","Nước chấm extra"],"getraenk":"Eistee, Zuckerrohrsaft oder ein leichtes Pils","koeche":[],"quellen":[{"titel":"Bun cha (char-grilled pork, noodles and nuoc cham) – Luke Nguyen, SBS Food (Kontext: Hanoier Verwandte)","url":"https://www.sbs.com.au/food/recipes/bun-cha-char-grilled-pork-noodles-and-nuoc-cham"},{"titel":"14 Vietnamese dishes listed among world's 100 best rated noodles – Nhân Dân (Kontext: Nudelgerichte im TasteAtlas-Ranking)","url":"https://en.cand.vn/culture-travel/14-vietnamese-dishes-listed-among-worlds-100-best-rated-noodles-i594053"}],"bild":"nudeln","farben":["#b8742a","#f2e8c9","#6fa04b"],"schlagworte":["Saigon","Nudelschüssel","Grill","kalt-warm","Streetfood"],"vegetarisch_moeglich":false},{"id":"vietnam-bun-rieu","name":"Bún Riêu – Krabben-Tomaten-Nudelsuppe","originalname":"Bún Riêu Cua","kueche":"vietnam","region":"Nordvietnam / Hanoi","beliebtheit":76,"hauptkategorie":"fisch","fischsorte":"gemischt","gang":"suppe","kurz":"Rötliche, leicht säuerliche Tomatenbrühe mit weichen Krabben-Hack-Bällchen, frittiertem Tofu und Reisnudeln, serviert mit einem Berg frischer Kräuter. Eine der beliebtesten Nudelsuppen Vietnams.","hintergrund":"Bún Riêu stammt aus Nordvietnam und wird dort traditionell mit Süßwasserkrabben (Cua Đồng) zubereitet, die samt Panzer zerstoßen und durchgesiebt werden. Das Wort „riêu“ bezeichnet die flockigen Klöße aus Krabbenmasse, die in der Brühe stocken. Tomaten geben der Suppe Farbe und Frische, Tamarinde oder Essig die Säure. Dazu gehören gebratener Tofu, Blutwürfel (Huyết) oder Schweinefleisch und viele Beilagen aus Wasserspinat, Salat und Kräutern. Typisch ist die kleine Schale Mắm Tôm, die manche zum Abschmecken dazugeben. Jede Straßenküche pflegt ihre eigene Version.","portionen":4,"zeit":{"vorbereitung":40,"garen":40,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Riêu (Krabbenmasse)","liste":[{"menge":250,"einheit":"g","name":"Krabbenfleisch (frisch oder TK) oder kleine Garnelen","hinweis":"Original: Süßwasserkrabben; hierzulande Taschenkrebsfleisch oder Garnelen"},{"menge":200,"einheit":"g","name":"Schweinehack","hinweis":"mager bis mittel"},{"menge":3,"einheit":"Stück","name":"Eier","hinweis":""},{"menge":2,"einheit":"Stück","name":"Schalotten, fein gehackt","hinweis":""},{"menge":1,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Pfeffer","hinweis":""},{"menge":20,"einheit":"g","name":"getrocknete Garnelen, eingeweicht und fein gehackt","hinweis":"für Umami, Asia-Laden"}]},{"gruppe":"Brühe","liste":[{"menge":1.5,"einheit":"l","name":"Hühner- oder Schweinebrühe","hinweis":"ungesalzen"},{"menge":600,"einheit":"g","name":"reife Tomaten, geviertelt","hinweis":"oder 1 Dose Tomaten für Wintergemüse"},{"menge":3,"einheit":"EL","name":"Öl mit Annatto-Samen oder Paprikapulver","hinweis":"für die rote Farbe"},{"menge":2,"einheit":"Stück","name":"Schalotten, in Scheiben","hinweis":""},{"menge":2,"einheit":"EL","name":"Tamarindenpaste","hinweis":"oder 2 EL Weißweinessig"},{"menge":2,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":""},{"menge":2,"einheit":"Stück","name":"Knoblauchzehen","hinweis":""}]},{"gruppe":"Einlage und Beilagen","liste":[{"menge":400,"einheit":"g","name":"frische Reisvermicelli (Bún)","hinweis":"oder getrocknete, 300 g"},{"menge":200,"einheit":"g","name":"Tofu, in Würfeln und frittiert","hinweis":"oder fertig frittierter Tofu"},{"menge":100,"einheit":"g","name":"Sojasprossen","hinweis":""},{"menge":1,"einheit":"Bund","name":"Perilla, Vietnamesischer Koriander, Minze","hinweis":""},{"menge":2,"einheit":"Stück","name":"Limetten, in Spalten","hinweis":""},{"menge":2,"einheit":"Stück","name":"Chilis","hinweis":""},{"menge":2,"einheit":"EL","name":"Mắm Tôm (Garnelenpaste)","hinweis":"optional, sehr kräftig"}]}],"ausruestung":["großer Suppentopf","Schüssel","Pfanne","Sieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Weiche die getrockneten Garnelen 15 Minuten in warmem Wasser ein und hacke sie sehr fein. Viertele die Tomaten, schneide Schalotten in dünne Scheiben und Knoblauch in feine Würfel. Wasche die Kräuter, tupfe sie trocken und richte sie mit Sojasprossen, Limettenspalten und Chilis als Beilagenplatte an. Schneide den Tofu in 2 cm Würfel und tupfe ihn gründlich trocken, damit er später beim Frittieren nicht spritzt und knusprig wird.","dauer":15,"tipp":""},{"titel":"Tofu frittieren","aktion":"frittieren","text":"Erhitze in einer Pfanne 2 cm hoch Öl auf etwa 170 °C. Brate die Tofuwürfel in zwei Portionen 4 bis 5 Minuten, bis sie rundum goldbraun und leicht aufgeblasen sind. Der Tofu soll außen eine feste Kruste haben, die später in der Brühe nicht zerfällt, und innen weich bleiben. Lasse ihn auf Küchenpapier abtropfen.","dauer":8,"tipp":""},{"titel":"Krabbenmasse anrühren","aktion":"mischen","text":"Vermische Hack, Krabbenfleisch, die gehackten eingeweichten Garnelen, Schalotten, Fischsauce und Pfeffer in einer Schüssel und verrühre alles mit einer Gabel zu einer lockeren, noch groben Masse. Schlage dann die Eier hinein und rühre gerade so lange, bis alles verbunden ist. Zu intensives Rühren macht die Masse zu fest, sie soll später in der Brühe in weichen, flockigen Stücken stocken wie eine fluffige Eiermasse und nicht als feste Klöße.","dauer":0,"tipp":"Krabben nicht pürieren, sie sollen grob zerzupft bleiben – das macht die typische Textur."},{"titel":"Tomatensugo ansetzen","aktion":"anbraten","text":"Erhitze das gefärbte Öl in einem großen Topf bei mittlerer Hitze, gib Schalotten und Knoblauch hinein und brate sie 1 bis 2 Minuten, bis sie weich und duftend sind. Gib die Tomaten dazu und schmore sie 8 bis 10 Minuten, bis sie zerfallen und das Öl sich rötlich absetzt. Zerdrücke sie mit dem Löffel. Dieser kurze Schmorvorgang macht die Brühe süßlich-tief und gibt die intensive rote Farbe.","dauer":10,"tipp":""},{"titel":"Brühe aufgießen und würzen","aktion":"koecheln","text":"Gieße die Brühe zu den Tomaten, bringe sie zum Sieden und lasse sie bei kleiner Hitze 10 Minuten köcheln. Würze mit Fischsauce, Zucker und Tamarindenpaste, bis sie süß-säuerlich und leicht salzig schmeckt; die Tomatensäure soll vorne stehen. Zum Schluss soll die Suppe klar und rötlich leuchten, nicht trüb.","dauer":10,"tipp":""},{"titel":"Riêu garen","aktion":"koecheln","text":"Reduziere die Hitze, bis die Brühe nur noch sanft siedet, und lasse die Krabben-Ei-Masse löffelweise in die Brühe gleiten. Rühre nicht um und lass die Hitze niedrig: Nach 5 bis 8 Minuten stockt die Masse zu flockigen, hellorangen Wolken, die an die Oberfläche steigen. Würde die Brühe sprudeln, zerfällt die Masse zu Krümeln und die Suppe wird trüb. Schöpfe Schaum ab, falls sich welcher bildet.","dauer":8,"tipp":"Eine Brühe, die nur leicht „zittert“, ist ideal; sprudelndes Kochen zerstört das Riêu."},{"titel":"Nudeln vorbereiten","aktion":"kochen","text":"Koche getrocknete Reisnudeln nach Packung in reichlich Wasser, bis sie weich, aber noch leicht bissfest sind, und spüle sie kalt ab, damit die Stärke weggeht. Frische Nudeln brauchst du nur kurz zu überbrühen. Verteile sie auf vier große Schalen, sodass die Brühe sie später gut umspült, ohne zu verkleben.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Lege in jede Schale Nudeln, einige Würfel Tofu und mehrere Stücke der Krabbenmasse. Gieße die heiße Brühe mit den Tomatenstückchen darüber und serviere sofort. Der Gast würzt selbst nach: Limettensaft, Chili und einen halben Teelöffel Mắm Tôm einrühren, Kräuter und Sojasprossen darauflegen. Die erste Kostprobe sollte säuerlich, salzig und leicht süß sein.","dauer":0,"tipp":""}],"profitipps":["Die Brühe nur sanft sieden lassen, damit die Krabbenmasse in großen Flocken stockt.","Reife Tomaten sind wichtiger als teures Krabbenfleisch; im Winter helfen Dosentomaten.","Getrocknete Garnelen sind der Umami-Booster, den man nicht weglassen sollte.","Mắm Tôm erst am Tisch einrühren; sie riecht streng, schmeckt aber hervorragend.","Nudeln getrennt kochen, sonst wird die Brühe trüb und stärkig."],"varianten":["Bún Riêu Ốc: mit Schnecken statt Krabbe (Hanoi)","Bún Riêu Cá: mit Fisch in der Masse (Süden)","Mit Blutwürfeln (Huyết) und Schweinefuß wie in den Straßenküchen","Vegetarisch mit Tofu und Pilzen"],"beilagen":["Kräuterteller","Sojasprossen","Limette und Chili"],"getraenk":"Eistee, Bia Hơi oder ein leichter Pils","koeche":[],"quellen":[{"titel":"Vicky Pham – Bún Riêu from Scratch","url":"https://www.vickypham.com/blog/bun-rieu-scratch"},{"titel":"Local Vietnam – Bun rieu explained","url":"https://localvietnam.com/culture/cuisine/bun-rieu/"},{"titel":"Red Lantern – Blue swimmer crab and tomato vermicelli noodle soup (Bún Riêu)","url":"https://redlantern.com.au/complimentary-recipes/bun-rieu"}],"bild":"suppe","farben":["#d9482b","#f3d9a8","#7a9a3c"],"schlagworte":["Nudelsuppe","Krabbe","Tomaten","Hanoi"],"vegetarisch_moeglich":false},{"id":"vietnam-ca-kho-to","name":"Cá Kho Tộ (Karamellisierter Fisch im Tontopf)","originalname":"Cá kho tộ","kueche":"vietnam","region":"Südvietnam / Mekong-Delta","beliebtheit":76,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Wels-Steaks, in dunklem Karamell, Fischsauce, Pfeffer und Ingwer im Tontopf geschmort, bis eine glänzende, würzige Sauce entsteht – dazu viel weißer Reis.","hintergrund":"Cá kho tộ ist ein Alltagsklassiker der südvietnamesischen Hausküche: Fisch, meist Wels (Cá basa oder Cá lóc), wird in einem Tontopf (tộ) mit einem Karamell aus Zucker, Fischsauce, Pfeffer und Frühlingszwiebeln geschmort. Die Technik „kho“ bedeutet, etwas langsam in einer salzig-süßen Sauce einzukochen, bis diese fast sirupartig wird. Das Gericht wird bewusst kräftig gewürzt, weil es zu viel einfachem Reis gegessen wird, dazu gibt es oft eine Schüssel saure Suppe und frisches Gemüse. Der leicht bittere Karamell und der schwarze Pfeffer sind die Seele des Gerichts; je dunkler und intensiver die Sauce, desto besser.","portionen":4,"zeit":{"vorbereitung":20,"garen":40,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Fisch","liste":[{"menge":700,"einheit":"g","name":"Welssteaks oder Welsfilet-Stücke, 2–3 cm dick","hinweis":"alternativ Pangasius, Lachs- oder Kabeljausteaks"},{"menge":2,"einheit":"EL","name":"Fischsauce","hinweis":"für die Marinade"},{"menge":1,"einheit":"TL","name":"Zucker","hinweis":"für die Marinade"},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer, grob gemahlen","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Schalotten, fein gehackt","hinweis":""}]},{"gruppe":"Für die Schmorsauce","liste":[{"menge":45,"einheit":"g","name":"Zucker","hinweis":"für den Karamell"},{"menge":2,"einheit":"EL","name":"Wasser","hinweis":"für den Karamell"},{"menge":250,"einheit":"ml","name":"Kokoswasser (ungesüßt) oder Wasser","hinweis":"Kokoswasser gibt mehr Süße und Tiefe"},{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":20,"einheit":"g","name":"Ingwer, in feinen Streifen","hinweis":""},{"menge":2,"einheit":"Stück","name":"rote Chilischoten, ganz oder halbiert","hinweis":"optional"},{"menge":3,"einheit":"Stück","name":"Frühlingszwiebeln, in 3 cm lange Stücke","hinweis":""},{"menge":1,"einheit":"EL","name":"neutrales Öl","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":320,"einheit":"g","name":"Jasminreis (roh)","hinweis":""},{"menge":1,"einheit":"Stück","name":"Salatgurke, in Scheiben","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":""},{"menge":null,"einheit":"","name":"frisch gemahlener Pfeffer","hinweis":"zum Bestreuen"}]}],"ausruestung":["Tontopf (Claypot) oder kleiner Schmortopf mit Deckel","kleiner Topf für Karamell","Pfannenwender","Reiskocher oder Topf für Reis"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche die Fischstücke unter kaltem Wasser ab und tupfe sie sehr gut trocken. Schneide große Stücke in gleich dicke Steaks von 2 bis 3 cm, damit sie gleichmäßig garen. Hacke Knoblauch und Schalotten fein, schneide Ingwer in feine Streifen und Frühlingszwiebeln in Stücke. Stelle Zucker, Fischsauce und Kokoswasser griffbereit, denn der Karamell erfordert Aufmerksamkeit und keine Unterbrechung.","dauer":0,"tipp":"Wels hat oft einen leicht erdigen Geruch; ein kurzes Abspülen mit Salzwasser und gründliches Trocknen mildert ihn."},{"titel":"Fisch marinieren","aktion":"marinieren","text":"Vermische Fischsauce, 1 TL Zucker, Pfeffer, die Hälfte von Knoblauch und Schalotten und lege die Fischstücke hinein. Wende sie vorsichtig, damit sie gleichmäßig bedeckt sind, und lass sie 30 Minuten im Kühlschrank ziehen. Die Marinade würzt den Fisch von innen und mildert seinen Eigengeschmack. Zu langes Marinieren macht das Fleisch durch die Fischsauce fest, daher nicht länger als 1 Stunde.","dauer":30,"tipp":"Fisch beim Marinieren nicht pressen: Er zerfällt leicht."},{"titel":"Karamell herstellen","aktion":"reduzieren","text":"Gib Zucker und Wasser in den Tontopf oder einen kleinen Topf und erhitze bei mittlerer Hitze, ohne zu rühren, bis der Zucker schmilzt und goldbraun wird. Schwenke den Topf gelegentlich. Der Moment ist entscheidend: Der Karamell soll tief bernsteinfarben sein und leicht rauchen, aber nicht schwarz und nicht bitter verbrannt riechen. Das dauert etwa 5 bis 8 Minuten. Nimm den Topf sofort vom Herd, wenn er die gewünschte Farbe hat; Karamell dunkelt nach.","dauer":8,"tipp":"Wenn der Karamell schwarz riecht, verwirf ihn: Verbranntes lässt sich nicht retten."},{"titel":"Ablöschen und aromatisieren","aktion":"kochen","text":"Gieße das Kokoswasser vorsichtig in den heißen Karamell; er zischt und spritzt, daher Abstand halten und den Deckel als Schutz bereithalten. Rühre, bis sich der Karamell vollständig gelöst hat, und gib Fischsauce, Ingwer, die restlichen Schalotten und den Knoblauch dazu. Bringe die Flüssigkeit zum leichten Köcheln. Probiere: Sie soll süß, salzig und leicht bitter schmecken; sie ist noch sehr kräftig, aber die Fischstücke werden sie später aufnehmen.","dauer":5,"tipp":"Kokoswasser vorher erwärmen: Kaltes Wasser lässt den Karamell hart werden."},{"titel":"Fisch zugeben","aktion":"schmoren","text":"Lege die Fischstücke in einer Lage in die köchelnde Sauce; sie sollen etwa zu zwei Dritteln bedeckt sein. Löffle etwas Sauce über die Oberseite, setze den Deckel auf und lass alles bei kleiner Hitze 10 Minuten schmoren. Die Haut färbt sich dunkel, das Fleisch wird fest. Wende die Stücke nur einmal, mit einem Pfannenwender oder Löffel, weil Welsfleisch leicht zerfällt.","dauer":10,"tipp":"Nicht rühren, nur schwenken: Rühren zerbricht den Fisch."},{"titel":"Einkochen","aktion":"reduzieren","text":"Nimm den Deckel ab, erhöhe die Hitze leicht und lass die Sauce 10 bis 15 Minuten einkochen, bis sie sirupartig und glänzend ist und etwa ein Drittel der ursprünglichen Menge übrig bleibt. Schöpfe die Sauce regelmäßig über den Fisch. Sie wird dunkler und dicker, der Duft nach Karamell und Fisch wird intensiv. Probiere: Wenn sie zu salzig ist, gib einen Schuss Wasser dazu; zu süß, einen Tropfen Fischsauce.","dauer":15,"tipp":"Der Fisch ist fertig, wenn er sich mit einer Gabel leicht teilen lässt, aber noch zusammenhält."},{"titel":"Reis kochen","aktion":"kochen","text":"Koche den Jasminreis nach Packungsanleitung oder im Reiskocher, damit er fertig ist, wenn der Fisch aus dem Topf kommt. Spüle den Reis zuvor in mehreren Wassern, bis es klar bleibt, und gib ihn im Verhältnis 1 zu 1,3 mit Wasser in den Topf. Lass ihn nach dem Garen 10 Minuten zugedeckt ruhen. Der Reis soll weich und leicht klebrig sein, denn er nimmt die kräftige Sauce auf.","dauer":25,"tipp":"Reis und Fisch gleichzeitig fertigstellen, damit beides heiß auf den Tisch kommt."},{"titel":"Abschmecken und fertigstellen","aktion":"abschmecken","text":"Gib Frühlingszwiebeln und Chili in den Topf und lass sie 1 Minute mitziehen. Würze mit frisch gemahlenem Pfeffer. Die Sauce soll jetzt dunkelbraun, glänzend und kräftig sein: süß, salzig, leicht bitter und scharf. Nimm den Topf vom Herd und lass den Fisch 5 Minuten ruhen, damit die Aromen sich verbinden. Der Fisch soll saftig und fest sein, die Sauce dick genug, um am Löffel zu haften.","dauer":5,"tipp":"Die Sauce darf ruhig kräftig sein: Sie wird mit viel Reis gegessen."},{"titel":"Servieren","aktion":"anrichten","text":"Serviere den Fisch im Tontopf direkt am Tisch, damit er heiß bleibt, mit Reis, Gurkenscheiben und frischem Koriander. Gieße Sauce über den Reis und esse jeden Bissen Fisch mit Sauce und Reis. In Vietnam isst man dazu oft eine klare, saure Suppe (Canh chua) oder einfaches gedünstetes Gemüse, das die Würze ausgleicht. Frisch gemahlener Pfeffer und etwas Chili am Tisch runden ab.","dauer":0,"tipp":"Reste schmecken am nächsten Tag noch besser, weil der Fisch die Sauce aufsaugt."}],"profitipps":["Karamell tief bernsteinfarben, aber nie schwarz werden lassen.","Kokoswasser statt Wasser gibt Süße und Tiefe.","Fisch nur einmal wenden und nicht rühren, sonst zerfällt er.","Sauce am Ende offen einkochen, bis sie sirupartig und glänzend ist.","Fisch gründlich trocknen und kurz marinieren.","Sehr viel Reis servieren: Die Sauce ist als Würze für den Reis gedacht."],"varianten":["Cá kho riềng: mit Galgant statt Ingwer","Cá kho tiêu: mit besonders viel schwarzem Pfeffer","Cá kho thịt: Fisch gemeinsam mit Schweinebauch geschmort","Cá kho mit Ananas und Tomaten"],"beilagen":["Jasminreis","Canh chua (saure Suppe)","gedünstetes Gemüse","frische Gurke"],"getraenk":"Eistee, Jasmintee oder ein kräftiges Pils","koeche":[],"quellen":[{"titel":"Caramelised pork belly – Luke Nguyen, SBS Food (Kontext: gleiche Karamell-Technik, andere Hauptzutat)","url":"https://www.sbs.com.au/food/recipes/caramelised-pork-belly"},{"titel":"Luke Nguyen's Vietnam, Season 2 – Episode guide, SBS Food (Kontext: regionale Schmorgerichte)","url":"https://www.sbs.com.au/food/article/luke-nguyens-vietnam-s2-episode-guide/e9jy4bx38"}],"bild":"fisch","farben":["#6b3a1e","#c9843a","#e8d5a8"],"schlagworte":["Schmorgericht","Tontopf","Karamell","Fisch","Hausmannskost"],"vegetarisch_moeglich":false},{"id":"vietnam-canh-chua","name":"Canh Chua (Süßsaure Fischsuppe)","originalname":"Canh chua cá","kueche":"vietnam","region":"Mekong-Delta / Südvietnam","beliebtheit":74,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"suppe","kurz":"Die Suppe des Mekong-Deltas: Tamarinde, Ananas und Tomate sorgen für süßsaure Frische, dazu zarter Fisch, Okra, Sprossen und ein Duft nach Reisfeldkraut und Knoblauch.","hintergrund":"Canh chua ist die klassische Suppe des Mekong-Deltas, wo Flüsse und Reisfelder frischen Fisch und tropisches Obst liefern. Der Name bedeutet „saure Suppe“, die Säure kommt aus Tamarinde, abgerundet von Ananas, Tomate und etwas Zucker, die Würze von Fischsauce. Typische Zutaten sind Wels oder Schlangenkopffisch, Okra, Taroblattstiele (Bạc hà), Sprossen und Kräuter wie Reisfeldkraut (Ngò om) und Sägekoriander. In Vietnam wird die Suppe im Alltag zu Reis gegessen, häufig zusammen mit einem kräftig geschmorten Gericht wie Cá kho tộ, weil ihre Säure und Frische das Fett und die Salzigkeit ausgleichen. Die Balance aus sauer, süß und salzig bestimmt die Qualität.","portionen":4,"zeit":{"vorbereitung":30,"garen":30,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Brühe","liste":[{"menge":1.3,"einheit":"l","name":"Fischfond oder Wasser","hinweis":"mit Fischkarkassen aufgekocht gibt es mehr Geschmack"},{"menge":40,"einheit":"g","name":"Tamarindenpulpe (Block)","hinweis":"in 150 ml heißem Wasser eingeweicht; alternativ 2 EL Tamarindenpaste"},{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":"nach Geschmack"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""}]},{"gruppe":"Für den Fisch","liste":[{"menge":500,"einheit":"g","name":"Welssteaks oder festes Weißfischfilet, in 3 cm Stücken","hinweis":"alternativ Garnelen oder Kabeljau"},{"menge":1,"einheit":"EL","name":"Fischsauce","hinweis":"zum Marinieren"},{"menge":1,"einheit":"Prise","name":"weißer Pfeffer","hinweis":""}]},{"gruppe":"Gemüse und Obst","liste":[{"menge":250,"einheit":"g","name":"frische Ananas, in dünne Stücke","hinweis":"oder aus der Dose, abgetropft"},{"menge":3,"einheit":"Stück","name":"Tomaten, in Spalten","hinweis":"reife, aromatische Tomaten"},{"menge":6,"einheit":"Stück","name":"Okraschoten, schräg halbiert","hinweis":""},{"menge":2,"einheit":"Stange","name":"Staudensellerie, schräg geschnitten","hinweis":"ersetzt Taro-Stängel (Bạc hà)"},{"menge":150,"einheit":"g","name":"Mungobohnensprossen","hinweis":""}]},{"gruppe":"Zum Finish","liste":[{"menge":3,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":"für Knoblauchöl"},{"menge":1,"einheit":"EL","name":"neutrales Öl","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander, Thai-Basilikum und Sägekoriander","hinweis":"gemischt; Reisfeldkraut (Ngò om) wenn vorhanden"},{"menge":2,"einheit":"Stück","name":"rote Chilischoten, in Ringen","hinweis":""},{"menge":320,"einheit":"g","name":"Jasminreis (roh)","hinweis":"zum Servieren"}]}],"ausruestung":["mittelgroßer Topf","Sieb für das Tamarindenwasser","kleine Pfanne für das Knoblauchöl","Schaumlöffel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide Ananas, Tomaten, Okra und Sellerie zurecht und halte die Zutaten in getrennten Schalen bereit, denn sie kommen nacheinander in den Topf. Würfele den Fisch in 3 cm große Stücke, tupfe ihn trocken und mariniere ihn mit Fischsauce und einer Prise weißem Pfeffer. Hacke Knoblauch fein und wasche die Kräuter. Das Garen geht schnell, daher muss alles vor dem Kochen fertig sein.","dauer":0,"tipp":"Fisch trocken tupfen: Nasses Fleisch gibt Schaum und trübt die Brühe."},{"titel":"Tamarindenwasser herstellen","aktion":"mischen","text":"Weiche die Tamarindenpulpe in 150 ml heißem Wasser 10 Minuten ein und zerdrücke sie mit den Fingern oder einem Löffel, bis sie sich auflöst. Streiche die Masse durch ein Sieb und drücke das Fruchtfleisch gut aus, sodass Kerne und Fasern im Sieb bleiben. Das Ergebnis ist ein bräunliches, säuerliches Wasser, das der Suppe ihre Säure und ihre Farbe gibt. Probiere es: Es sollte deutlich sauer, aber nicht scharf sein.","dauer":12,"tipp":"Fertige Tamarindenpaste ist stärker: Nimm 1 EL und probiere, bevor du mehr zugibst."},{"titel":"Brühe aufsetzen","aktion":"kochen","text":"Gib Fond oder Wasser, Tamarindenwasser, Fischsauce, Zucker und Ananas in den Topf und bringe alles zum Kochen. Lass es 5 Minuten leicht köcheln, damit die Ananas ihre Süße abgibt und sich mit der Säure verbindet. Probiere: Sauer, süß und salzig sollen sich die Waage halten; dies ist die Grundlage der Suppe. Wenn sie zu sauer ist, gib etwas Zucker dazu, zu süß: mehr Tamarinde oder Limette.","dauer":8,"tipp":"Die Brühe soll klar bleiben: bei mittlerer Hitze köcheln, nicht stark sprudeln lassen."},{"titel":"Fisch pochieren","aktion":"koecheln","text":"Gib die Fischstücke vorsichtig in die köchelnde Brühe, bringe sie noch einmal kurz zum Köcheln und schöpfe Schaum ab. Lass den Fisch 5 bis 6 Minuten garen, bis er undurchsichtig ist und sich leicht teilen lässt. Rühre nicht, sonst zerfällt er; schwenke den Topf lieber leicht. Fisch, der zu lange gart, wird trocken und fällt auseinander. Hebe ihn bei Bedarf kurz heraus, wenn du das Gemüse fertig garen willst.","dauer":6,"tipp":"Wels bleibt auch beim Köcheln fest; Kabeljau ist empfindlicher und braucht weniger Zeit."},{"titel":"Gemüse in der richtigen Reihenfolge zugeben","aktion":"koecheln","text":"Gib zuerst Sellerie und Okra in die Brühe und lass sie 2 bis 3 Minuten köcheln, dann die Tomaten für 1 bis 2 Minuten, bis sie leicht weich werden, aber noch Form haben. Zuletzt kommen die Sprossen: Sie dürfen nur 30 Sekunden ziehen, damit sie knackig bleiben. Die Reihenfolge ist wichtig, damit alles den richtigen Biss hat. Schalte den Herd aus, sobald die Sprossen eingefallen sind.","dauer":6,"tipp":"Tomaten nicht zu lange kochen: Sie zerfallen und trüben die Brühe."},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere die Suppe jetzt sorgfältig. Sie soll vor allem sauer-fruchtig schmecken, mit einer klaren Süße von Ananas und Zucker und ausreichend Salzigkeit von der Fischsauce. Korrigiere mit kleinen Mengen: etwas Fischsauce für Tiefe, ein Spritzer Limette für Säure, eine Prise Zucker für Rundung. Die Suppe wird zu Reis gegessen, daher darf sie ruhig kräftig sein.","dauer":3,"tipp":"Immer in kleinen Schritten würzen; mehr kann man jederzeit zugeben, weniger nicht."},{"titel":"Knoblauchöl herstellen","aktion":"braten","text":"Erhitze das Öl in einer kleinen Pfanne bei mittlerer Hitze und gib den gehackten Knoblauch hinein. Brate ihn 1 bis 2 Minuten unter Rühren, bis er goldgelb ist und intensiv duftet; sobald er braun wird, wird er bitter. Nimm die Pfanne sofort vom Herd und gieße Öl und Knoblauch über die Suppe. Der Duft nach geröstetem Knoblauch ist das Finish.","dauer":3,"tipp":"Knoblauch beim Braten nicht aus den Augen lassen; er verbrennt in Sekunden."},{"titel":"Kräuter und Reis servieren","aktion":"garnieren","text":"Streue gehackte Kräuter und Chili über die Suppe und serviere sie sofort in vorgewärmten Schalen. Koche den Reis nach Packungsanleitung und reiche ihn separat. In Vietnam gehört die Suppe zu einem Reisessen mit mehreren Gerichten: Man löffelt Brühe und Fisch abwechselnd mit Reis und anderen Speisen. Die Kräuter sollten erst im Teller landen, damit sie ihre Frische behalten.","dauer":0,"tipp":"Einige Limettenspalten und Chili am Tisch lassen jeden nachwürzen."}],"profitipps":["Tamarinde ist die Seele der Suppe: Frische Pulpe selbst einweichen schmeckt besser als Paste.","Sauer, süß und salzig im Gleichgewicht halten; Ananas liefert die Frucht, Zucker die Rundung.","Gemüse nacheinander zugeben: erst fest, dann weich, zuletzt Sprossen.","Fisch nur kurz pochieren und nicht rühren.","Knoblauchöl erst am Ende zugeben, damit der Duft frisch bleibt.","Die Suppe wird zu Reis gegessen: ruhig kräftig würzen."],"varianten":["Canh chua tôm: mit Garnelen statt Fisch","Canh chua cá lóc: mit Schlangenkopffisch, die Delta-Originalversion","Canh chua mit Taro-Stängeln (Bạc hà) und Reisfeldkraut","Canh chua chay: vegetarisch mit Tofu und Pilzen"],"beilagen":["Jasminreis","Cá kho tộ (Schmorfisch)","Fisch mit Chilisauce zum Dippen"],"getraenk":"Eistee, Zuckerrohrsaft oder ein trockener Riesling","koeche":[{"name":"Luke Nguyen","bezug":"Seine SBS-Rezeptversion einer süßsauren Tamarinden-Fischsuppe (Canh hải sản măng chua) kombiniert Tamarindenwasser, Ananas, eingelegten Bambus, Tomate, Okra und Meeresfrüchte; die Reihenfolge beim Garen (erst Brühe, dann Meeresfrüchte, zuletzt Gemüse) bildet die Grundlogik der Suppe. Das ist eine verwandte Suppe aus Vĩnh, keine reine Canh chua.","quelle":"https://www.sbs.com.au/food/recipes/pickled-bamboo-and-tamarind-seafood-soup-canh-hai-san-mang-chua"}],"quellen":[{"titel":"Pickled bamboo and tamarind seafood soup (canh hai san mang chua) – Luke Nguyen, SBS Food","url":"https://www.sbs.com.au/food/recipes/pickled-bamboo-and-tamarind-seafood-soup-canh-hai-san-mang-chua"},{"titel":"Luke Nguyen's Vietnam, Season 2 – Episode guide, SBS Food","url":"https://www.sbs.com.au/food/article/luke-nguyens-vietnam-s2-episode-guide/e9jy4bx38"}],"bild":"suppe","farben":["#c95a2b","#e8c36a","#6fa04b"],"schlagworte":["Mekong-Delta","sauer","Tamarinde","Suppe","Fisch"],"vegetarisch_moeglich":true},{"id":"vietnam-tom-rang-me","name":"Tôm Rang Me – Garnelen in Tamarindensauce","originalname":"Tôm Rang Me","kueche":"vietnam","region":"Südvietnam / Saigon","beliebtheit":72,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"hauptgericht","kurz":"Garnelen, in einer klebrigen Sauce aus Tamarinde, Knoblauch, Fischsauce und Zucker geschwenkt – süß, sauer, salzig und tiefbraun glänzend.","hintergrund":"Tôm Rang Me ist ein Klassiker der südvietnamesischen Küche und steht in Saigon auf vielen Speisekarten der Seafood-Restaurants. Das Prinzip ist einfach: Garnelen werden mit Schale scharf angebraten, dann in einer Sauce aus Tamarindenmark, Fischsauce und Zucker eingekocht, bis sie wie lackiert glänzen. Die Säure der Tamarinde kontrastiert die Süße und lässt das Gericht frisch wirken. Gegessen wird es mit Reis, wobei viele Gäste die Schale mitessen oder mit den Fingern aussaugen. Das Gericht ist eng verwandt mit Tôm Rim, der karamellisierten Garnelen-Variante.","portionen":3,"zeit":{"vorbereitung":20,"garen":12,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Garnelen","liste":[{"menge":500,"einheit":"g","name":"große Garnelen mit Schale (ca. 16/20)","hinweis":"TK-Ware aus ASC-Zucht; frisch auftauen"},{"menge":1,"einheit":"EL","name":"Speisestärke","hinweis":"für knusprigeren Überzug, optional"}]},{"gruppe":"Tamarindensauce","liste":[{"menge":3,"einheit":"EL","name":"Tamarindenpaste (Mark ohne Kerne)","hinweis":"aus Block oder fertige Paste; nicht Konzentrat mit Zucker"},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":2,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":60,"einheit":"ml","name":"Wasser","hinweis":""}]},{"gruppe":"Aromaten","liste":[{"menge":3,"einheit":"EL","name":"neutrales Öl","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch, gehackt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Schalotten, gehackt","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Chili, gehackt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Frühlingszwiebeln, in Ringen","hinweis":""},{"menge":1,"einheit":"Handvoll","name":"Koriander","hinweis":""}]}],"ausruestung":["großer Wok oder weite Pfanne","kleine Schüssel","Schere"],"schritte":[{"titel":"Garnelen vorbereiten","aktion":"vorbereiten","text":"Schneide mit der Küchenschere Fühler, Beinchen und die spitze Kopfspitze ab, damit nichts anbrennt, und schneide den Rücken entlang der Schale ein, um den dunklen Darm zu entfernen. Lasse die Schale dran: Sie schützt das Fleisch vor dem Austrocknen, nimmt die Sauce auf und gibt Geschmack. Tupfe die Garnelen gründlich trocken, denn Feuchtigkeit verhindert das Anbraten, und mische sie mit der Stärke.","dauer":0,"tipp":""},{"titel":"Tamarindenmark vorbereiten","aktion":"mischen","text":"Löse die Tamarindenpaste in 60 ml warmem Wasser auf und drücke sie mit dem Löffel durch ein Sieb, um Fasern und Kerne zu entfernen. Rühre Zucker und Fischsauce ein, bis sich die Kristalle gelöst haben. Probiere: Die Mischung soll kräftig sauer, deutlich süß und salzig sein, denn sie verdichtet sich im Wok und wird dabei milder.","dauer":0,"tipp":""},{"titel":"Mise en place der Aromaten","aktion":"schneiden","text":"Hacke Knoblauch, Schalotten und Chili fein und schneide die Frühlingszwiebeln in feine Ringe. Alles stellst du in Schüsseln direkt neben den Herd, weil der Wok sehr heiß ist und später keine Zeit zum Schneiden bleibt. Zupfe den Koriander ab und lege ihn zur Seite. Die Aromaten sollen etwa gleich fein sein, damit sie im selben Moment Duft abgeben und keine groben Stücke verbrennen, während feine noch roh sind.","dauer":0,"tipp":""},{"titel":"Garnelen scharf anbraten","aktion":"wok","text":"Erhitze den Wok stark, gib 2 EL Öl dazu und warte, bis es leicht raucht. Gib die Garnelen in einer Lage hinein und lasse sie 1 bis 2 Minuten ungestört braten, bis die Schalen sich orangerot färben; wende sie dann und brate die andere Seite 1 Minute an. Sie sollen noch nicht ganz gar sein, denn sie garen in der Sauce weiter. Nimm sie auf einen Teller und halte sie warm.","dauer":3,"tipp":"Garnelen in zwei Chargen braten, sonst kühlt der Wok ab und sie kochen im eigenen Saft."},{"titel":"Aromaten anschwitzen","aktion":"wok","text":"Stelle die Hitze auf mittel, gib das restliche Öl in den Wok und brate Knoblauch, Schalotten und Chili 30 bis 40 Sekunden unter Rühren, bis sie goldgelb duften. Knoblauch darf nicht dunkel werden, er wird sonst bitter und überdeckt die Frische der Tamarinde. Wenn der Wok zu heiß ist, gieße einen Schuss Wasser nach.","dauer":1,"tipp":""},{"titel":"Sauce einkochen","aktion":"reduzieren","text":"Gieße die Tamarindenmischung in den Wok und lasse sie bei starker Hitze 2 bis 3 Minuten sprudelnd einkochen, bis sie dicklich wird und große Blasen wirft. Sie soll sirupartig sein und von einem Löffel langsam tropfen. Der Duft ist jetzt süß-sauer und leicht karamellig. Zu langes Kochen lässt den Zucker karamellisieren und bitter werden.","dauer":3,"tipp":""},{"titel":"Garnelen glasieren","aktion":"wok","text":"Gib die Garnelen zurück in den Wok und schwenke sie 1 bis 2 Minuten, bis jede Garnele vollständig von der glänzenden Sauce überzogen ist und sich das Fleisch fest anfühlt. Garnelen sind gar, wenn sie ein C bilden und das Fleisch weiß-opak ist; ein enger O-Ring deutet auf Übergaren hin. Zum Schluss gibst du Frühlingszwiebeln und Koriander dazu.","dauer":2,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Richte die Garnelen sofort mit der Sauce auf einer vorgewärmten Platte an und serviere sie mit Jasminreis, gedämpftem Gemüse oder einem Gurkensalat. Fingerschalen und Servietten sollten bereitstehen: Die Schalen löst man mit den Fingern und saugt die klebrige Sauce ab. Die Sauce schmeckt kräftig, daher passt Reis als neutraler Gegenpart hervorragend.","dauer":0,"tipp":""}],"profitipps":["Mit Schale braten: sie schützt das Fleisch und gibt Aroma an die Sauce.","Tamarindenmark immer selbst absieben, Fertigsaucen sind meist zu süß.","Sauce vor dem Zurückgeben der Garnelen einkochen, sonst werden die Garnelen zäh.","Der Wok muss wirklich heiß sein; kalte Pfanne = gekochte Garnelen.","Nach Belieben mit Chilischoten kräftiger machen."],"varianten":["Tôm Rim: dunkelbraun karamellisiert mit Schweinebauch","Cua Rang Me: Krabben in Tamarindensauce (Saigon-Spezialität)","Mit Tintenfischringen","Mit Kokoswasser aufgegossen für eine milder-süße Sauce"],"beilagen":["Jasminreis","Gurkensalat","Wasserspinat (Rau Muống)"],"getraenk":"Frisches Bier oder ein trockener Riesling","koeche":[{"name":"Andrea Nguyen","bezug":"Die US-vietnamesische Kochbuchautorin bietet in ihrem Newsletter „Pass the Fish Sauce“ ein Rezept für Tamarindengarnelen mit Gemüse aus dem Wok.","quelle":"https://andreanguyen.substack.com/p/tamarind-shrimp-vegetable-stir-fry-recipe"}],"quellen":[{"titel":"Andrea Nguyen – Tamarind Shrimp Vegetable Stir-Fry","url":"https://andreanguyen.substack.com/p/tamarind-shrimp-vegetable-stir-fry-recipe"},{"titel":"Viet Nam News – Prawns with tamarind sauce","url":"https://vietnamnews.vn/sunday/ong-taos-kitchen/522869/prawns-with-tamarind-sauce.html"}],"bild":"meeresfruechte","farben":["#a8441c","#e8b86a","#4f7a2b"],"schlagworte":["Garnelen","Tamarinde","Saigon","süß-sauer"],"vegetarisch_moeglich":false},{"id":"vietnam-ga-kho-gung","name":"Gà Kho Gừng (Hähnchen mit Ingwer geschmort)","originalname":"Gà kho gừng","kueche":"vietnam","region":"Süd- und Nordvietnam (Hausmannskost)","beliebtheit":70,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Hähnchenstücke, in Fischsauce und viel frischem Ingwer geschmort, bis eine dunkle, glänzende, würzige Sauce entsteht – ein Alltagsgericht, das nach Zuhause schmeckt.","hintergrund":"Gà kho gừng gehört zu den „kho“-Gerichten, bei denen Fleisch oder Fisch in einer salzig-süßen Sauce langsam eingekocht wird. Das Gericht ist ein Alltagsessen der vietnamesischen Familienküche und wird mit viel Reis serviert. Die Schärfe und Wärme des Ingwers harmoniert mit Fischsauce, Zucker und schwarzem Pfeffer; je nach Region und Haushalt wird ein dunkler Karamell (Nước màu) zugegeben oder die Sauce nur durch Zucker und Einkochen dunkel. Luke Nguyen zeigt in seiner Fernsehreihe eine Variante aus Bắc Hà in den Bergen des Nordens, in der Hühnchen mit Ingwer, Fischsauce und etwas Zucker mariniert, angebraten und in Brühe geschmort wird.","portionen":4,"zeit":{"vorbereitung":20,"garen":40,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Für das Hähnchen","liste":[{"menge":900,"einheit":"g","name":"Hähnchenschenkel (Ober- und Unterschenkel), mit Knochen, in 5 cm Stücke gehackt","hinweis":"vom Metzger zerteilen lassen; Knochen geben Geschmack"},{"menge":60,"einheit":"g","name":"frischer Ingwer, in dünne Streifen geschnitten","hinweis":"großzügig dosieren: Er ist das Hauptaroma"},{"menge":4,"einheit":"Zehe","name":"Knoblauch, fein gehackt","hinweis":""},{"menge":3,"einheit":"Stück","name":"Schalotten, fein gehackt","hinweis":""}]},{"gruppe":"Für die Marinade","liste":[{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Austernsauce","hinweis":""},{"menge":0.5,"einheit":"TL","name":"schwarzer Pfeffer, grob gemahlen","hinweis":""}]},{"gruppe":"Für die Schmorsauce","liste":[{"menge":2,"einheit":"EL","name":"Zucker","hinweis":"für den Karamell"},{"menge":1,"einheit":"EL","name":"Wasser","hinweis":"für den Karamell"},{"menge":2,"einheit":"EL","name":"neutrales Öl","hinweis":""},{"menge":250,"einheit":"ml","name":"Hühnerbrühe oder Wasser","hinweis":""},{"menge":3,"einheit":"Stück","name":"Frühlingszwiebeln, in 4 cm Stücken","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Chilischote, in Ringen","hinweis":"optional"}]},{"gruppe":"Zum Servieren","liste":[{"menge":320,"einheit":"g","name":"Jasminreis (roh)","hinweis":""},{"menge":1,"einheit":"Stück","name":"Salatgurke, in Scheiben","hinweis":""},{"menge":null,"einheit":"","name":"frisch gemahlener schwarzer Pfeffer","hinweis":"zum Bestreuen"}]}],"ausruestung":["schwerer Schmortopf oder Tontopf mit Deckel","kleiner Topf für Karamell","Schaumlöffel","Reiskocher oder Topf für Reis"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Lasse die Hähnchenschenkel vom Metzger in 5 cm große Stücke hacken oder zerteile sie selbst mit einem schweren Messer; die Knochen bleiben dran, sie geben der Sauce Körper. Schneide den Ingwer in dünne Streifen, hacke Knoblauch und Schalotten und stelle Zucker, Fischsauce und Brühe bereit. Tupfe das Fleisch trocken, damit es später Röstaromen bekommt. Wenn du magst, schneide die Frühlingszwiebeln und Chili schon jetzt und lege sie beiseite.","dauer":0,"tipp":"Knochenstücke nicht entfernen: Sie machen die Sauce voller und das Fleisch saftiger."},{"titel":"Hähnchen marinieren","aktion":"marinieren","text":"Vermische Fischsauce, 1 EL Zucker, Austernsauce, Pfeffer, die Hälfte des Ingwers sowie Knoblauch und Schalotten und massiere die Mischung in die Hähnchenstücke, bis alle Seiten benetzt sind. Lass das Fleisch zugedeckt 30 Minuten im Kühlschrank durchziehen, besser bis zu 2 Stunden. Der Zucker unterstützt später die Bräunung, die Fischsauce würzt tief, der Ingwer beginnt schon jetzt Aroma abzugeben.","dauer":30,"tipp":"Nicht länger als 4 Stunden marinieren; Fischsauce macht Geflügel sonst fest."},{"titel":"Karamell herstellen","aktion":"reduzieren","text":"Gib 2 EL Zucker und 1 EL Wasser in den Schmortopf und erhitze bei mittlerer Hitze, ohne zu rühren, bis der Zucker schmilzt und hellbraun bis bernsteinfarben wird (etwa 4 bis 6 Minuten). Schwenke den Topf, damit er gleichmäßig färbt. Der Duft wird nussig-süß; riecht er scharf-bitter, ist der Karamell zu dunkel. Nimm den Topf kurz vom Herd, denn Karamell dunkelt nach; er gibt der Sauce später Farbe und Tiefe.","dauer":6,"tipp":"Für ein milderes Gericht nur hell karamellisieren; für ein kräftigeres Aroma bis tief bernsteinfarben gehen."},{"titel":"Aromaten und Hähnchen anbraten","aktion":"anbraten","text":"Gib Öl und den restlichen Ingwer zum Karamell und brate bei mittlerer Hitze 1 Minute, bis der Ingwer duftet. Gib die Hähnchenstücke samt Marinade in den Topf und brate sie bei hoher Hitze unter Wenden 5 bis 6 Minuten, bis sie rundum goldbraun sind und der Karamell sie überzieht. Es duftet nach Ingwer, Karamell und gebratenem Geflügel. Das Anbraten bringt Röstaromen und bildet später die Basis der Sauce.","dauer":7,"tipp":"In zwei Portionen anbraten, wenn der Topf zu klein ist: Zu viel Fleisch kocht statt zu bräunen."},{"titel":"Brühe aufgießen und abschäumen","aktion":"kochen","text":"Gieße die heiße Brühe oder Wasser zum Hähnchen, bis es zu etwa zwei Dritteln bedeckt ist, und bringe es zum Kochen. Schöpfe den aufsteigenden Schaum mit einem Löffel ab, bis die Flüssigkeit klar ist. Das dauert etwa 3 bis 5 Minuten. Reduziere die Hitze auf mittlere Stufe. Die Sauce soll klar und glänzend werden, nicht trüb; Abschäumen sorgt für eine saubere Optik und einen reinen Geschmack.","dauer":5,"tipp":"Heiße Brühe verwenden: Kalte Flüssigkeit kühlt den Topf ab und das Fleisch wird zäh."},{"titel":"Schmoren","aktion":"schmoren","text":"Setze den Deckel schräg auf und lass das Hähnchen bei kleiner bis mittlerer Hitze 20 bis 25 Minuten köcheln, bis das Fleisch gar, zart und leicht vom Knochen lösbar ist. Wende die Stücke einmal in der Mitte der Garzeit. Die Sauce reduziert sich dabei, wird dunkler und dicker und nimmt Aroma des Ingwers an. Prüfe mit einem Messer: Der austretende Saft muss klar sein, die Kerntemperatur 75 °C erreichen.","dauer":25,"tipp":"Wenn die Sauce zu schnell einkocht, gib einen Schuss heißes Wasser dazu."},{"titel":"Sauce einkochen","aktion":"reduzieren","text":"Nimm den Deckel ab, erhöhe die Hitze und lass die Sauce 5 bis 8 Minuten offen einkochen, bis sie sirupartig ist und das Hähnchen glänzend überzieht. Schöpfe sie immer wieder über die Stücke. Probiere: Sie soll kräftig salzig, leicht süß, ingwerscharf und tiefgründig schmecken. Gib bei Bedarf eine Prise Zucker oder einen Spritzer Fischsauce dazu.","dauer":8,"tipp":"Beim Einkochen beobachten: Zuckerreiche Saucen verbrennen am Ende schnell."},{"titel":"Reis kochen","aktion":"kochen","text":"Koche den Jasminreis nach Packungsanleitung oder im Reiskocher, damit er fertig ist, wenn das Gericht auf den Tisch kommt. Spüle den Reis in mehreren Wassern, bis es klar bleibt, und gib ihn im Verhältnis 1 zu 1,3 mit Wasser in den Topf. Lass ihn nach dem Garen 10 Minuten zugedeckt ruhen. Der Reis soll weich und leicht klebrig sein; er nimmt die kräftige Sauce auf.","dauer":25,"tipp":""},{"titel":"Frühlingszwiebeln zugeben und servieren","aktion":"anrichten","text":"Gib Frühlingszwiebeln und Chili in den Topf, rühre um und lass sie 1 Minute mitziehen, damit sie noch frisch und knackig bleiben. Würze mit frisch gemahlenem Pfeffer. Serviere das Hähnchen im Topf oder in einer Schale mit viel Sauce, dazu Reis und Gurkenscheiben. Der Ingwer wird mitgegessen: Er ist weich, süßlich-scharf und ein Highlight. Wer mag, gibt etwas frischen Koriander darüber.","dauer":0,"tipp":"Reste schmecken am nächsten Tag noch besser, wenn die Sauce vollständig eingezogen ist."}],"profitipps":["Ingwer großzügig verwenden, in dünnen Streifen: Er ist das Aroma des Gerichts.","Hähnchen mit Knochen schmoren: Es bleibt saftiger und die Sauce bekommt Körper.","Karamell nur bernsteinfarben werden lassen, nie bitter.","Sauce am Ende offen einkochen, bis sie glänzt und am Fleisch haftet.","Frühlingszwiebeln erst kurz vor Schluss zugeben, damit sie frisch bleiben.","Mit viel Reis servieren: Die Sauce ist als Würze für den Reis gedacht."],"varianten":["Gà kho sả ớt: mit Zitronengras und Chili statt Ingwer","Gà kho nghệ: mit frischem Kurkuma","Gà bản kho gừng (Bắc Hà): Bergvariante mit Brühe, ohne Karamell","Cá kho gừng: dieselbe Technik mit Fisch"],"beilagen":["Jasminreis","gedünstetes Gemüse","klare Suppe","Gurkenscheiben"],"getraenk":"Jasmintee oder ein leichtes Pils","koeche":[{"name":"Luke Nguyen","bezug":"Zeigt auf SBS Food ein Gericht aus Bắc Hà im Norden Vietnams („Chicken cooked in ginger“, Gà bản kho gừng): Hähnchen wird 20 Minuten mit Fischsauce, Austernsauce, Zucker und Ingwer mariniert, mit Knoblauch scharf angebraten und etwa 15 Minuten in Hühnerbrühe geschmort. Diese Version kommt ohne Karamell aus; unser Rezept ergänzt ihn nach südlicher Hausmannsart.","quelle":"https://www.sbs.com.au/food/recipes/chicken-cooked-ginger-ga-ban-kho-gung"}],"quellen":[{"titel":"Chicken cooked in ginger (ga ban kho gung) – Luke Nguyen, SBS Food","url":"https://www.sbs.com.au/food/recipes/chicken-cooked-ginger-ga-ban-kho-gung"},{"titel":"Luke Nguyen's Vietnam, Season 2 – Episode guide, SBS Food","url":"https://www.sbs.com.au/food/article/luke-nguyens-vietnam-s2-episode-guide/e9jy4bx38"}],"bild":"haehnchen","farben":["#8b4a1e","#c9843a","#e8d5a8"],"schlagworte":["Schmorgericht","Ingwer","Hausmannskost","Reisgericht"],"vegetarisch_moeglich":false},{"id":"vietnam-bo-kho","name":"Bò Kho – vietnamesischer Rindfleischeintopf mit Zitronengras und Sternanis","originalname":"Bò kho","kueche":"vietnam","region":"Südvietnam, Saigon","beliebtheit":68,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"eintopf","kurz":"Zartes Rindfleisch und Möhren in einer leuchtend orangeroten, duftenden Brühe aus Zitronengras, Sternanis, Zimt und Tomate – mit knusprigem Baguette zum Tunken oder mit Reisnudeln.","hintergrund":"Bò kho stammt aus dem Süden Vietnams und gilt als Gericht der Kolonialzeit, das vermutlich von französischen Schmorgerichten wie Pot-au-feu oder Boeuf bourguignon inspiriert wurde und mit chinesischen und indischen Einflüssen verfeinert wurde. Anders als viele andere „Kho“-Gerichte (Schmorgerichte mit karamellisierter Sauce, Nước màu) wird es meist ohne Karamell gekocht und hat deshalb eine fruchtig-herzhafte Tomatenbasis. Gewürzt wird mit Zitronengras, Ingwer, Sternanis, Zimt und oft einer Currymischung; Annattoöl färbt die Brühe orange-rot. Man isst Bò kho zum Frühstück oder Mittagessen auf der Straße, entweder mit Bánh mì (Baguette) zum Eintunken oder mit Reisnudeln oder Eiernudeln. Frische Kräuter wie Thai-Basilikum, Koriander und Limette frischen das Ganze auf. In Kambodscha heißt eine verwandte Version Khor ko.","portionen":4,"zeit":{"vorbereitung":40,"garen":150,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Rindfleisch und die Marinade","liste":[{"menge":1,"einheit":"kg","name":"Rinderbrust (Brisket) oder Rinderwade mit Sehnen","hinweis":"kollagenreich, wird schön gelatinös; in 4 cm große Würfel schneiden"},{"menge":2,"einheit":"Stange","name":"Zitronengras, 1 Stange fein gehackt, 1 Stange angeschlagen"},{"menge":4,"einheit":"Zehe","name":"Knoblauch, fein gehackt"},{"menge":3,"einheit":"Stück","name":"Schalotten, fein gehackt"},{"menge":2,"einheit":"EL","name":"Fischsauce"},{"menge":1,"einheit":"EL","name":"Zucker"},{"menge":1,"einheit":"EL","name":"Currypulver (mild, z. B. Madras)"},{"menge":1,"einheit":"TL","name":"Fünf-Gewürze-Pulver"},{"menge":1,"einheit":"TL","name":"gemahlener schwarzer Pfeffer"}]},{"gruppe":"Für den Eintopf","liste":[{"menge":2,"einheit":"EL","name":"Öl","hinweis":"idealerweise mit Annattosamen aromatisiert (siehe Schritt 3)"},{"menge":1,"einheit":"EL","name":"Annattosamen (Annatto, Achiote)","hinweis":"im Asialaden oder Gewürzhandel; ersatzweise 1 TL Paprikapulver (edelsüß) für die Farbe"},{"menge":3,"einheit":"EL","name":"Tomatenmark"},{"menge":2,"einheit":"Stück","name":"Tomaten, gewürfelt"},{"menge":3,"einheit":"Stück","name":"Sternanis"},{"menge":1,"einheit":"Stück","name":"Zimtstange"},{"menge":3,"einheit":"Blatt","name":"Lorbeerblätter"},{"menge":1,"einheit":"Stück","name":"Ingwer (daumengroß), in Scheiben"},{"menge":800,"einheit":"ml","name":"Wasser oder Kokoswasser","hinweis":"Kokoswasser gibt feine Süße"},{"menge":3,"einheit":"Stück","name":"Möhren, in 3-cm-Stücken"},{"menge":0.5,"einheit":"TL","name":"Salz"}]},{"gruppe":"Zum Servieren","liste":[{"menge":4,"einheit":"Stück","name":"Baguettebrötchen (Bánh mì) oder 300 g Reisnudeln"},{"menge":1,"einheit":"Bund","name":"Thai-Basilikum, Koriander, Frühlingszwiebeln"},{"menge":2,"einheit":"Stück","name":"Limetten, in Spalten"},{"menge":2,"einheit":"Stück","name":"Chilis, in Scheiben","hinweis":"optional"}]}],"ausruestung":["schwerer Schmortopf oder Bräter mit Deckel (4 l)","kleine Pfanne für das Annattoöl","feines Sieb","scharfes Messer"],"schritte":[{"titel":"Fleisch schneiden und marinieren","aktion":"marinieren","text":"Schneide die Rinderbrust gegen die Faserrichtung in grobe Würfel von etwa 4 cm; kleinere Stücke würden beim langen Schmoren austrocknen. Lass die Sehnen und Fettanteile dran, denn sie werden weich und geben der Brühe Körper. Vermenge das Fleisch in einer Schüssel mit gehacktem Zitronengras, Knoblauch, Schalotten, Fischsauce, Zucker, Currypulver, Fünf-Gewürze und Pfeffer. Knete die Gewürze kräftig ein und lass alles mindestens 30 Minuten, besser 2 Stunden oder über Nacht im Kühlschrank ziehen. Die Marinade dringt in das Fleisch ein und macht es würziger.","dauer":30,"tipp":"Je länger du marinierst, desto aromatischer wird das Fleisch."},{"titel":"Annattoöl herstellen","aktion":"braten","text":"Erhitze das Öl mit den Annattosamen in einer kleinen Pfanne bei niedriger Hitze etwa 3–4 Minuten, bis das Öl eine leuchtende orangerote Farbe annimmt und leicht nach Erde und Nuss duftet. Die Samen dürfen nicht dunkel werden, sonst schmeckt das Öl bitter. Seihe es durch ein feines Sieb und werfe die Samen weg. Dieses Öl färbt den Bò kho in seinem typischen warmen Orange und gibt ihm einen milden, erdigen Hauch.","dauer":5,"tipp":"Ohne Annatto: 1 TL edelsüßes Paprikapulver in das heiße Öl rühren – gibt eine ähnliche Farbe."},{"titel":"Fleisch anbraten","aktion":"anbraten","text":"Erhitze das Annattoöl in dem schweren Topf bei mittelhoher Hitze. Nimm das marinierte Fleisch aus der Schüssel, tupfe überschüssige Flüssigkeit ab und brate es in zwei Portionen 4–5 Minuten, bis es von allen Seiten Farbe angenommen hat und die Marinade leicht karamellisiert. Dabei darf es ruhig laut zischen und an den Rändern dunkel werden. Das Anbraten bildet Röstaromen, die der Brühe Tiefe geben. Hebe die Stücke zwischendurch heraus, damit der Topf nicht überfüllt wird.","dauer":10,"tipp":"Nicht zu viel Fleisch auf einmal in den Topf – es dünstet sonst, statt zu bräunen."},{"titel":"Aromaten und Tomaten anrösten","aktion":"anbraten","text":"Gib in den Topf die restlichen Aromaten: Ingwer, die zweite angeschlagene Zitronengras-Stange, Sternanis und die Zimtstange. Röste sie 1 Minute unter Rühren, bis sie intensiv duften. Rühre dann das Tomatenmark ein und brate es 2 Minuten, bis es dunkelrot wird und am Boden leicht ansetzt. Gib die gewürfelten Tomaten dazu und lass sie 3 Minuten zerfallen. Löse den Bratensatz mit einem Schuss Wasser vom Topfboden; er ist Geschmack pur.","dauer":8,"tipp":"Tomatenmark immer kurz anrösten, so verliert es die Säure und schmeckt tiefer."},{"titel":"Schmoren","aktion":"schmoren","text":"Lege das Fleisch zurück in den Topf, gieße Wasser oder Kokoswasser darauf, sodass alles knapp bedeckt ist, und füge Lorbeerblätter und Salz hinzu. Bringe alles zum Kochen, schöpfe den Schaum ab, senke die Hitze auf die niedrigste Stufe und lass den Eintopf zugedeckt 90 Minuten sanft schmoren. Die Flüssigkeit darf nur leise blubbern. Nach der Zeit ist das Fleisch fast zart und lässt sich mit einer Gabel leicht eindrücken, aber noch nicht zerfallen.","dauer":90,"tipp":"Wenn die Flüssigkeit zu stark verdampft, gieße heißes Wasser nach."},{"titel":"Möhren zufügen","aktion":"koecheln","text":"Gib nun die Möhren hinzu und lass alles weitere 30–40 Minuten ohne Deckel oder mit halb geöffnetem Deckel köcheln. Die Möhren sind fertig, wenn sie weich sind, aber noch Form haben, und das Fleisch lässt sich ohne Widerstand mit einem Löffel zerdrücken. Die Brühe soll dabei etwas einkochen und leicht sämig werden; sie wirkt jetzt tiefrot-orange und glänzt vom Fett. Probiere und passe Salz oder Fischsauce an, außerdem eine Prise Zucker für Balance.","dauer":40,"tipp":"Zu früh zugegebene Möhren zerfallen und trüben die Brühe."},{"titel":"Ruhen und Fett abschöpfen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lass den Eintopf 15–30 Minuten zugedeckt ruhen. Das Fleisch nimmt dabei noch einmal Saft auf und die Brühe verbindet sich. Schöpfe überschüssiges Fett oben mit einem Löffel ab, ein goldener Rand darf bleiben, denn er trägt Aroma. Entferne die Zitronengrasstange, den Sternanis, die Zimtstange und die Lorbeerblätter, damit niemand darauf beißt. Erwärme den Bò kho vor dem Servieren kurz.","dauer":20,"tipp":"Am nächsten Tag schmeckt Bò kho noch besser – gut vorzubereiten."},{"titel":"Anrichten","aktion":"anrichten","text":"Röste die Baguettebrötchen kurz im Ofen bei 200 °C Ober-/Unterhitze (180 °C Umluft) 3–4 Minuten, bis die Kruste knackt. Schöpfe den Bò kho in tiefe Schalen und garniere mit Thai-Basilikum, Koriander, Frühlingszwiebeln und einer Limettenspalte. Ein Spritzer Limette hebt die Brühe, Chili sorgt für Schärfe. Tunke das Brot in die Brühe und iss das Fleisch mit dem Löffel, oder gib Reisnudeln in die Schale und gieße die Brühe darüber.","dauer":0,"tipp":"Eine kleine Schale Salz-Pfeffer-Limetten-Dip passt gut zum Tunken des Fleischs."}],"profitipps":["Fleischstück mit Bindegewebe wählen (Brust, Wade, Beinscheibe): Mageres Fleisch wird trocken, Kollagen wird weich und gelatinös.","Zitronengras zweifach nutzen: gehackt in der Marinade, angeschlagen im Topf – so kommt Aroma in Fleisch und Brühe.","Annattoöl herstellen: kleine Menge, große Wirkung für Farbe und Geschmack. Nicht überhitzen, sonst bitter.","Langsam schmoren, nie sprudelnd kochen: Das Fleisch bleibt sonst faserig und die Brühe trüb.","Zum Servieren immer frische Kräuter und Limette bereitstellen – ohne Frische wirkt der Eintopf schwer."],"varianten":["Bò kho mit Kokoswasser: etwas süßer und leichter, wie in einer Ho-Chi-Minh-Stadt-Version, die Andrea Nguyen beschreibt.","Bò kho mit Rindersehnen und Innereien: Phá lấu bò, ein verwandtes Gericht.","Mit Reisnudeln (Hủ tiếu) oder Eiernudeln statt Baguette.","Khor ko: kambodschanische Variante."],"beilagen":["Baguette (Bánh mì)","Reisnudeln","Thai-Basilikum, Koriander, Limette","Chilisauce"],"getraenk":"Vietnamesischer Eiskaffee (Cà phê sữa đá), Jasmintee oder ein leichtes Lagerbier (Saigon Beer)","koeche":[{"name":"Andrea Nguyen","bezug":"Die vietnamesisch-amerikanische Kochbuchautorin stellt in einem Milk-Street-Beitrag die Bò-kho-Version einer Köchin aus Ho-Chi-Minh-Stadt vor: Rinderbrust, Zitronengras, Sternanis, Zimt und Karotten, mit Kokoswasser statt Kokosmilch für eine leichtere, frischere Brühe, serviert über zarten Reisnudeln.","quelle":"https://www.177milkstreet.com/stories/ho-chi-minh-city-beef-stew"}],"quellen":[{"titel":"Bò kho – Wikipedia","url":"https://en.wikipedia.org/wiki/B%C3%B2_kho"},{"titel":"In Ho Chi Minh City, Beef Stew Is Fragrant and Bright with Lemon Grass and Star Anise – Milk Street (Andrea Nguyen)","url":"https://www.177milkstreet.com/stories/ho-chi-minh-city-beef-stew"}],"bild":"eintopf","farben":["#c0482a","#e8913c","#f3d9a8"],"schlagworte":["Zitronengras","Sternanis","Baguette","Frühstück Saigon","Schmortopf"],"vegetarisch_moeglich":false},{"id":"vietnam-ca-nuong-la-chuoi","name":"Cá Nướng Lá Chuối – Gegrillter Fisch im Bananenblatt","originalname":"Cá Nướng Lá Chuối","kueche":"vietnam","region":"ganz Vietnam (Mekongdelta)","beliebtheit":68,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Ganze Forelle oder Dorade, mit Zitronengras, Kurkuma und Knoblauch eingerieben, im Bananenblatt über Glut gegrillt und mit Reispapier, Kräutern und Dip gerollt gegessen.","hintergrund":"Gegrillter Fisch im Bananenblatt, Cá Nướng, gehört zu den ältesten und beliebtesten Zubereitungen Vietnams, besonders im Mekongdelta, wo Süßwasserfische wie Schlangenkopf (Cá Lóc) oder Tilapia auf Holzkohle gegart werden. Das Bananenblatt schützt das Fleisch vor der direkten Glut, hält es saftig und gibt einen leicht süß-grasigen Rauchduft ab. Man isst den Fisch gemeinsam am Tisch: Stücke werden mit Salat, Kräutern, Gurke, Vermicelli und einem Dip in Reispapier gerollt. Die Marinade mit Zitronengras und Kurkuma gibt Farbe und Duft.","portionen":4,"zeit":{"vorbereitung":30,"garen":25,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch","liste":[{"menge":2,"einheit":"Stück","name":"ganze Forellen oder Dorade à ca. 400 g, ausgenommen und geschuppt","hinweis":"In Vietnam Tilapia oder Cá Lóc; Fischtheke bitten, Schuppen und Eingeweide zu entfernen"},{"menge":2,"einheit":"Stück","name":"Bananenblätter, ca. 40×40 cm","hinweis":"TK im Asia-Laden; Ersatz: Backpapier + Alufolie"}]},{"gruppe":"Marinade","liste":[{"menge":3,"einheit":"Stange","name":"Zitronengras, unterer Teil, fein gehackt","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":3,"einheit":"Stück","name":"Schalotten","hinweis":""},{"menge":1,"einheit":"TL","name":"Kurkumapulver","hinweis":"oder 2 cm frische Kurkuma"},{"menge":2,"einheit":"EL","name":"Fischsauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":2,"einheit":"Stück","name":"rote Chilis","hinweis":""},{"menge":3,"einheit":"EL","name":"Öl","hinweis":""}]},{"gruppe":"Zum Rollen und Dippen","liste":[{"menge":12,"einheit":"Stück","name":"Reispapier-Blätter","hinweis":""},{"menge":200,"einheit":"g","name":"Reisvermicelli, gekocht","hinweis":""},{"menge":1,"einheit":"Stück","name":"Salatkopf, Gurke, Kräuter (Minze, Koriander, Perilla)","hinweis":""},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":""},{"menge":3,"einheit":"EL","name":"Fischsauce","hinweis":"für Nước Chấm"},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":100,"einheit":"ml","name":"Wasser","hinweis":""}]}],"ausruestung":["Grill (Holzkohle bevorzugt)","Mörser","Pinsel","Küchengarn","Fischzange"],"schritte":[{"titel":"Frische prüfen und Fisch vorbereiten","aktion":"vorbereiten","text":"Prüfe die Fische auf Frische: klare, pralle Augen, rote Kiemen, feste Haut und ein frischer Geruch. Spüle sie innen und außen kalt ab und tupfe sie gründlich trocken. Bitte an der Fischtheke, Schuppen und Eingeweide zu entfernen. Schneide beidseitig drei schräge Schnitte bis fast zur Gräte ein, so kann die Marinade eindringen und die Hitze verteilt sich gleichmäßiger.","dauer":0,"tipp":""},{"titel":"Marinadepaste herstellen","aktion":"hacken","text":"Hacke Zitronengras (nur die weichen unteren Teile), Knoblauch, Schalotten und Chili und zerstoße alles im Mörser zu einer feinen Paste. Je feiner das Zitronengras, desto weniger spürst du Fasern im fertigen Fisch. Rühre Kurkuma, Fischsauce, Zucker und Öl ein; die Paste soll kräftig gelb-orange riechen und leicht körnig sein.","dauer":0,"tipp":""},{"titel":"Fisch einreiben und marinieren","aktion":"marinieren","text":"Verstreiche die Paste in den Einschnitten, auf der Haut und in der Bauchhöhle. Lege die Fische abgedeckt 1 Stunde in den Kühlschrank. Das Salz der Fischsauce würzt, das Zitronengras gibt Aroma. Bei sehr großen Fischen bis zu 2 Stunden marinieren, länger macht das Fleisch durch das Salz fester. Drücke die Paste mit den Fingern fest in die Schnitte, denn dort sitzt später das meiste Aroma.","dauer":60,"tipp":""},{"titel":"Bananenblätter weichmachen","aktion":"vorbereiten","text":"Bananenblätter reißen leicht. Halte sie kurz über die Flamme oder tauche sie 10 Sekunden in heißes Wasser, bis sie dunkelgrün glänzen und geschmeidig sind. Wische sie ab und lege jeweils eins auf die Arbeitsfläche. Ohne Bananenblatt nimmst du Backpapier und schlägst es in Alufolie ein; es fehlt dann der leichte Raucharoma-Effekt, doch der Fisch bleibt saftig.","dauer":0,"tipp":""},{"titel":"Fisch einwickeln","aktion":"formen","text":"Lege jeden Fisch in die Mitte eines Blatts, schlage die Seiten über den Fisch und falte die Enden nach unten. Binde das Paket mit Küchengarn oder Streifen eines Bananenblatts fest. Halte die Naht nach unten. Das Blatt schützt den Fisch vor der direkten Glut und hält ihn saftig; offen gegrillt würde die Marinade verbrennen.","dauer":0,"tipp":""},{"titel":"Grill vorbereiten","aktion":"vorbereiten","text":"Befeuere den Grill so, dass eine mittelstarke Glut entsteht (die Kohle ist grau überzogen, du kannst die Hand etwa 5 Sekunden darüber halten). Bei Gas auf mittlere Hitze (180–200 °C) stellen. Die Glut darf nicht zu heiß sein, sonst verbrennt das Blatt, bevor der Fisch gar ist. Reibe den Rost mit etwas Öl ein.","dauer":10,"tipp":""},{"titel":"Fisch grillen","aktion":"grillen","text":"Lege die Pakete auf den Rost und grille sie 8 bis 10 Minuten pro Seite. Das Blatt wird dunkel und leicht rauchig; ein süß-grasiger Duft zeigt dir an, dass der Fisch gart. Prüfe den Garpunkt durch einen Einstich in die dickste Stelle nahe dem Kopf: Das Fleisch ist gar, wenn es opak-weiß ist und sich leicht von der Gräte lösen lässt, die Kerntemperatur beträgt etwa 62 °C.","dauer":20,"tipp":"Wende Pakete nur einmal und mit zwei Zangen, damit das Blatt nicht reißt."},{"titel":"Dip anrühren","aktion":"mischen","text":"Löse den Zucker im Wasser, rühre Fischsauce, Limettensaft, fein gehackten Knoblauch und Chili hinein. Die Mischung soll süß-sauer-salzig im Gleichgewicht sein. Lass sie kurz ziehen, damit sich das Aroma verbindet. Eine Variante ist Muối Ớt Chanh: grobes Salz, Chili und Limettensaft zum Tupfen. Stelle den Dip in kleinen Schälchen für jeden Gast bereit, damit man die gerollten Happen direkt eintauchen kann.","dauer":0,"tipp":""},{"titel":"Servieren und rollen","aktion":"anrichten","text":"Öffne die Pakete am Tisch und löse das Fleisch in großen Stücken von der Gräte. Weiche Reispapier kurz in warmem Wasser ein, belege es mit Salat, Kräutern, Gurke, Vermicelli und einem Stück Fisch, rolle es fest und tauche es in den Dip. Der Fisch soll zart, saftig und leicht rauchig schmecken, die Marinade mit Zitronengras gibt eine frische Note.","dauer":0,"tipp":""}],"profitipps":["Das Bananenblatt vorher anwärmen, damit es nicht reißt.","Nicht zu heiß grillen – das Blatt verbrennt sonst, bevor der Fisch gar ist.","Ganze Fische bleiben saftiger als Filets; die Gräte schützt das Fleisch.","Zitronengras fein hacken oder im Mörser zerstoßen, sonst bleiben Fasern.","Süßwasserfische wie Forelle brauchen eine kräftige Marinade, weil sie milder schmecken."],"varianten":["Cá Lóc Nướng Trui: Schlangenkopffisch direkt in die Glut gelegt (Mekongdelta)","Cá Nướng Giấy Bạc: in Alufolie mit Zwiebeln und Tomaten gegart","Cá Nướng Muối Ớt: mit Salz-Chili-Kruste","Backofen: bei 220 °C Ober-/Unterhitze (200 °C Umluft) 25–30 Minuten"],"beilagen":["Reispapier und Kräuter","Reisvermicelli","Nước Chấm","Gurke"],"getraenk":"Frisches Pils, Eistee oder ein trockener Riesling","koeche":[{"name":"Luke Nguyen","bezug":"In seinem Buch „Luke Nguyen's Street Food Asia“ hat er eine Seite zu gegrilltem Fisch, in der er Fisch über Glut mit Kräutern zubereitet.","quelle":"https://hardiegrant.com.au/uk/books/news/luke-nguyens-street-food-asia-grilled-fish"}],"quellen":[{"titel":"Hardie Grant – Luke Nguyen's Street Food Asia: Grilled fish","url":"https://hardiegrant.com.au/uk/books/news/luke-nguyens-street-food-asia-grilled-fish"},{"titel":"Dish – Grilled Vietnamese Fish in Banana Leaves","url":"https://dish.co.nz/recipes/grilled-vietnamese-fish-banana-leaves"},{"titel":"The Meatwave – Vietnamese Stuffed Bass Wrapped in Banana Leaf","url":"https://meatwave.com/recipes/grilled-vietnamese-stuffed-bass-wrapped-in-banana-leaf-recipe"}],"bild":"fisch","farben":["#5a7a2b","#d9b84a","#8a5a2b"],"schlagworte":["Grill","Bananenblatt","Forelle","Mekong"],"vegetarisch_moeglich":false},{"id":"vietnam-banh-mi-op-la","name":"Bánh Mì Ốp La – Baguette mit Spiegelei","originalname":"Bánh mì ốp la","kueche":"vietnam","region":"Saigon und ganz Vietnam","beliebtheit":68,"hauptkategorie":"vegetarisch","kurz":"Knuspriges Baguette mit zwei weich gebratenen Spiegeleiern, frisch eingelegtem Gemüse, Gurke, Koriander, Pâté und einem Hauch Sojasauce: das schnelle Frühstück der Vietnamesen.","hintergrund":"Bánh mì ốp la ist die Frühstücksversion des vietnamesischen Baguettes und eines der beliebtesten Morgenessen in Saigon und im Süden des Landes. Das Baguette ist ein Erbe der französischen Kolonialzeit, wurde aber vietnamesisch umgedeutet: Die Kruste ist dünn und splittert, das Innere luftig. Gefüllt wird es mit Spiegelei, süßsauer eingelegtem Gemüse, Gurke, Koriander und manchmal Pâté oder Wurst. Oft wird das Ei in der Pfanne serviert, das Brot taucht man hinein. Auf der Straße gibt es dazu Eiskaffee mit Kondensmilch.","portionen":2,"zeit":{"vorbereitung":20,"garen":8,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Eingelegtes Gemüse (Đồ chua)","liste":[{"menge":1,"einheit":"Stück","name":"Karotte, ca. 100 g","hinweis":"in feine Stifte geschnitten"},{"menge":100,"einheit":"g","name":"Daikon-Rettich","hinweis":"ersatzweise Rettich oder Kohlrabi"},{"menge":120,"einheit":"ml","name":"Wasser","hinweis":"warm"},{"menge":80,"einheit":"ml","name":"Reisessig","hinweis":""},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Sandwich","liste":[{"menge":2,"einheit":"Stück","name":"kleine Baguettes oder Baguettebrötchen","hinweis":"möglichst luftig und knusprig"},{"menge":4,"einheit":"Stück","name":"Eier","hinweis":"frisch"},{"menge":1,"einheit":"EL","name":"Öl","hinweis":"zum Braten"},{"menge":2,"einheit":"EL","name":"Mayonnaise","hinweis":""},{"menge":2,"einheit":"EL","name":"Leberpastete (Pâté)","hinweis":"optional"},{"menge":0.5,"einheit":"Stück","name":"Salatgurke","hinweis":"in Längsstreifen"},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":""},{"menge":2,"einheit":"Stück","name":"Frühlingszwiebeln","hinweis":"in Streifen"},{"menge":1,"einheit":"Stück","name":"rote Chilischote","hinweis":"in Ringen"},{"menge":2,"einheit":"TL","name":"Maggi-Würze oder Sojasauce","hinweis":""},{"menge":null,"einheit":"","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen"}]}],"ausruestung":["Schüssel oder Glas für das eingelegte Gemüse","beschichtete Pfanne oder kleine gusseiserne Pfanne","scharfes Brotmesser"],"schritte":[{"titel":"Gemüse einlegen","aktion":"einlegen","text":"Rühre Wasser, Essig, Zucker und Salz in einer Schüssel, bis sich alles gelöst hat. Schäle Karotte und Daikon und schneide sie in 5 cm lange, streichholzdünne Stifte. Gib das Gemüse in das Glas und gieße die Lösung darüber, bis es bedeckt ist. Lasse es mindestens 30 Minuten ziehen. Es soll knackig bleiben, süßsauer schmecken und leicht durchscheinend werden.","dauer":30,"tipp":"Über Nacht eingelegt schmeckt es noch besser, im Kühlschrank hält es 2 Wochen."},{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche den Koriander und zupfe die Blätter ab, die Stiele kannst du mitverwenden. Schneide die Gurke in lange Streifen von der Länge des Baguettes, die Frühlingszwiebeln in feine Streifen und die Chili in dünne Ringe. Rühre die Mayonnaise mit etwas Sojasauce oder Maggi zu einem würzigen Aufstrich. Stelle Pâté, Eier und Pfanne bereit.","dauer":0,"tipp":""},{"titel":"Baguette aufbacken","aktion":"backen","text":"Erwärme die Baguettes im vorgeheizten Ofen bei 200 °C Ober-/Unterhitze (180 °C Umluft) 4–5 Minuten, bis die Kruste wieder knistert und das Brot duftet. Schneide sie der Länge nach auf, ohne sie ganz zu durchtrennen, und zupfe etwas Krume heraus, damit mehr Platz für die Füllung bleibt. Bestreiche die Innenseiten dünn mit Mayonnaise und, wenn du magst, mit Pâté.","dauer":5,"tipp":"Das Brot muss knusprig sein: Ein Brot aus dem Toaster ersetzt keinen Ofen."},{"titel":"Eier braten","aktion":"braten","text":"Erhitze das Öl in der Pfanne bei mittlerer Hitze, bis es leicht schimmert. Schlage die Eier hinein und brate sie 2–3 Minuten, bis das Eiweiß fest und die Ränder leicht knusprig sind, das Eigelb aber noch flüssig glänzt. Würze mit Pfeffer und einem Spritzer Maggi oder Sojasauce direkt über die Eier. In Vietnam gart das Ei oft mit Deckel, damit das Eigelb oben leicht milchig bleibt. Nimm die Eier sofort aus der Pfanne, wenn das Eiweiß gestockt ist, damit das Eigelb flüssig bleibt.","dauer":3,"tipp":""},{"titel":"Sandwich zusammensetzen","aktion":"schichten","text":"Lege die Gurkenstreifen auf die untere Hälfte des Baguettes, darauf die Spiegeleier. Verteile das abgetropfte eingelegte Gemüse, Frühlingszwiebeln, Koriander und Chili darüber. Klappe das Baguette zu und drücke leicht an. Bei der Reihenfolge gilt: Feuchte Zutaten kommen zwischen Fett und Salat, damit das Brot nicht durchweicht. Das Eigelb darf beim Zubeißen ruhig herauslaufen.","dauer":0,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Serviere das Bánh Mì sofort, solange das Brot warm, die Kruste knusprig und das Eigelb noch flüssig ist. Beiße mit einem Biss durch alle Schichten: knusprig, cremig, säuerlich und frisch. Wer mag, serviert die Eier in der Pfanne dazu und taucht Brotstücke ins Eigelb, wie es auf Saigons Straßen üblich ist. Dazu passt Cà phê sữa đá, eisgekühlter Kaffee mit Kondensmilch, dessen Süße die Säure des Gemüses ausgleicht.","dauer":0,"tipp":""}],"profitipps":["Das Gemüse mindestens 30 Minuten einlegen.","Baguette immer kurz aufbacken, damit die Kruste knusprig ist.","Eigelb flüssig lassen, es ist die Sauce des Sandwiches.","Feuchte Zutaten schichten, damit das Brot nicht aufweicht.","Maggi-Würze gibt den typischen Geschmack."],"varianten":["Mit Pâté und Wurst (Bánh mì thịt)","Eier in der Pfanne mit Wurst und Pâté (Bánh mì chảo)","Mit Käse und Tomaten","Mit Rührei und Frühlingszwiebeln","Vegetarische Version ohne Pâté"],"beilagen":["Cà phê sữa đá","Frisches Obst","Gurkensalat"],"getraenk":"Vietnamesischer Eiskaffee mit Kondensmilch (Cà phê sữa đá) oder Jasmintee.","quellen":[{"titel":"Banh mi op la (Cooking Therapy)","url":"https://www.cooking-therapy.com/banh-mi-op-la/"},{"titel":"Vietnamese breakfast in Saigon (Migrationology)","url":"https://www.migrationology.com/vietnamese-breakfast-saigon/"},{"titel":"Fried Egg with Baguette (Cooking Off the Cuff)","url":"https://cookingoffthecuff.com/recipes/fried-egg-with-baguette"}],"bild":"sandwich","farben":["#d9a441","#f4e2b8","#6aa84f"],"schlagworte":["Saigon","Straßenessen","Baguette","schnell"],"vegetarisch_moeglich":true,"gang":"fruehstueck","fleischsorte":"","koeche":[]},{"id":"vietnam-che-ba-mau","name":"Chè Ba Màu (Dreifarbiges Dessert)","originalname":"Chè ba màu","kueche":"vietnam","region":"Südvietnam / Saigon","beliebtheit":68,"hauptkategorie":"suess","gang":"dessert","kurz":"Das bunte Schichtdessert aus Saigon: süße rote Bohnen, goldgelbe Mungbohnenpaste und grünes Pandan-Gelee, übergossen mit gesalzener Kokoscreme und Crushed Ice.","hintergrund":"Chè ist in Vietnam der Sammelbegriff für süße Suppen, Puddings und Desserts, die oft mit Bohnen, Gelee, Kokosmilch und Eis zubereitet werden. Chè ba màu, „Dessert der drei Farben“, ist eines der beliebtesten Chè-Gerichte im Süden und wird in Straßencafés in hohen Gläsern serviert: unten rote Bohnen, darüber gelbe Mungbohnen und grünes Pandan-Gelee, obenauf Kokosmilch und Eis. Die drei Farben stehen für Fülle und Freude, und die Kombination aus warmen, cremigen, kühlen und festen Texturen macht den Reiz aus. Besonders an heißen Tagen ist es eine beliebte Erfrischung und wird vor dem Essen mit dem langen Löffel durchmischt.","portionen":4,"zeit":{"vorbereitung":40,"garen":90,"ruhen":600},"schwierigkeit":2,"zutaten":[{"gruppe":"Rote Bohnen","liste":[{"menge":150,"einheit":"g","name":"rote Adzukibohnen oder kleine rote Bohnen (getrocknet)","hinweis":"über Nacht eingeweicht"},{"menge":60,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""}]},{"gruppe":"Mungbohnenschicht","liste":[{"menge":150,"einheit":"g","name":"geschälte gelbe Mungbohnen (Mung Dal)","hinweis":"30 Minuten eingeweicht"},{"menge":60,"einheit":"g","name":"Zucker","hinweis":""},{"menge":3,"einheit":"EL","name":"Kokosmilch","hinweis":"für Cremigkeit"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""}]},{"gruppe":"Pandan-Gelee","liste":[{"menge":4,"einheit":"g","name":"Agar-Agar-Pulver","hinweis":"ca. 1,5 TL; nach Packungsangabe für 500 ml"},{"menge":500,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":40,"einheit":"g","name":"Zucker","hinweis":""},{"menge":6,"einheit":"Blatt","name":"Pandanblätter, püriert und ausgepresst","hinweis":"alternativ 1 TL Pandan-Extrakt; im Asialaden, auch tiefgekühlt"}]},{"gruppe":"Kokossauce und Servieren","liste":[{"menge":400,"einheit":"ml","name":"Kokosmilch","hinweis":"ungesüßt, vollfett"},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":0.25,"einheit":"TL","name":"Salz","hinweis":"für den typischen Kontrast"},{"menge":1,"einheit":"TL","name":"Tapiokastärke oder Speisestärke","hinweis":"in 2 EL Wasser angerührt"},{"menge":400,"einheit":"g","name":"Eiswürfel, grob zerstoßen","hinweis":"Crushed Ice"},{"menge":2,"einheit":"EL","name":"geröstete Erdnüsse, grob gehackt","hinweis":"optional"}]}],"ausruestung":["Topf mit Deckel","flache Form für das Gelee (ca. 20 cm)","Stabmixer oder Mörser für die Pandanblätter","Kartoffelstampfer","hohe Gläser","Eiswürfelzerkleinerer oder Gefrierbeutel mit Nudelholz"],"schritte":[{"titel":"Bohnen einweichen","aktion":"einlegen","text":"Wasche die roten Bohnen gründlich unter fließendem Wasser und lege sie in eine große Schüssel mit dem Dreifachen ihres Volumens an kaltem Wasser. Lass sie 8 bis 10 Stunden, am besten über Nacht, einweichen, bis sie deutlich gequollen sind. Das Einweichen verkürzt die Kochzeit und sorgt für gleichmäßig weiche Bohnen. Gieße das Einweichwasser am nächsten Tag ab. Weiche die Mungbohnen erst am nächsten Tag etwa 30 Minuten ein, sie brauchen nicht länger.","dauer":600,"tipp":"Wer die Bohnen schneller braucht, übergießt sie mit kochendem Wasser und lässt sie 2 Stunden quellen."},{"titel":"Rote Bohnen kochen","aktion":"koecheln","text":"Gib die eingeweichten Bohnen in einen Topf, bedecke sie mit frischem Wasser und bringe es zum Kochen. Reduziere die Hitze und lass die Bohnen 45 bis 60 Minuten leise köcheln, bis sie weich sind, aber noch ihre Form behalten. Gib den Zucker erst in den letzten 10 Minuten dazu: Wird er früher zugegeben, bleiben die Schalen hart. Rühre vorsichtig um und lass die Bohnen im Sirup abkühlen. Die Bohnen sollen glänzend, süß und samtig sein, nicht matschig.","dauer":60,"tipp":"Salz erst am Ende zugeben; es betont die Süße."},{"titel":"Mungbohnenschicht herstellen","aktion":"daempfen","text":"Gieße die eingeweichten Mungbohnen ab und dämpfe sie in einer flachen Schale über kochendem Wasser 20 bis 25 Minuten, bis sie weich zerfallen. Alternativ koche sie mit wenig Wasser 15 Minuten. Zerstampfe sie mit dem Stampfer oder püriere sie grob und rühre Zucker, Salz und Kokosmilch ein. Die Masse soll dick, goldgelb und leicht körnig sein, ähnlich einer festen Paste. Lass sie abkühlen; sie wird dabei fester und lässt sich später gut schichten.","dauer":25,"tipp":"Zu trocken? Mit etwas Kokosmilch lockern. Zu flüssig? Kurz einkochen."},{"titel":"Pandan-Gelee zubereiten","aktion":"kochen","text":"Püriere die Pandanblätter mit 100 ml Wasser, seihe den grünen Saft durch ein Tuch und presse die Blätter gut aus. Rühre Agar-Agar mit dem restlichen Wasser an, bringe es unter Rühren zum Kochen und lass es 2 Minuten sprudeln, damit sich das Agar vollständig löst. Gib Zucker und Pandan-Saft dazu und rühre um. Gieße die Mischung in eine flache Form und lass sie bei Raumtemperatur fest werden; sie ist nach etwa 30 Minuten bissfest. Schneide das Gelee dann in Würfel oder Streifen von 1 cm.","dauer":40,"tipp":"Agar geliert schon bei Raumtemperatur; den Kühlschrank nicht zu früh nutzen, sonst bekommt es Risse."},{"titel":"Kokossauce zubereiten","aktion":"binden","text":"Erhitze die Kokosmilch mit Zucker und Salz in einem Topf bei kleiner Hitze unter Rühren, bis sich der Zucker aufgelöst hat; sie darf nicht kochen, sonst wird sie ölig. Rühre die angerührte Stärke ein und erhitze noch 1 Minute, bis die Sauce leicht dickflüssig ist und den Löffel überzieht. Stelle sie zum Abkühlen beiseite. Die Prise Salz ist wichtig: Sie hebt die Süße und gibt der Kokoscreme den typischen vietnamesischen Charakter.","dauer":10,"tipp":"Vor dem Servieren in den Kühlschrank stellen; die Sauce soll kalt sein."},{"titel":"Gläser schichten","aktion":"schichten","text":"Gib in jedes hohe Glas zuerst 3 EL rote Bohnen mit etwas Sirup, darüber 3 EL Mungbohnenpaste und schließlich eine Handvoll Geleewürfel. Drücke jede Schicht leicht an, damit die Farben klar getrennt bleiben. Übergieße alles mit 3 bis 4 EL Kokossauce und füge zuletzt das zerstoßene Eis hinzu. Streue nach Belieben gehackte Erdnüsse darüber. Die drei Farben sollten von der Seite des Glases gut sichtbar sein.","dauer":10,"tipp":"Eis erst im letzten Moment zugeben, sonst verwässert es das Dessert."},{"titel":"Servieren","aktion":"anrichten","text":"Serviere sofort mit einem langen Löffel und Strohhalm. Vor dem Essen werden die Schichten durchmischt, sodass jeder Löffel Bohnen, Paste, Gelee, Kokossauce und Eis enthält. Das Dessert schmeckt süß, cremig, leicht salzig und kühl zugleich; die Texturen von weich, fest und knusprig (Erdnüsse) machen den Reiz aus. Es sollte frisch zubereitet gegessen werden, denn nach einer Viertelstunde schmilzt das Eis und verdünnt alles.","dauer":0,"tipp":"Die Komponenten halten getrennt 2 bis 3 Tage im Kühlschrank; nur das Eis immer frisch."}],"profitipps":["Zucker erst am Ende zu den Bohnen geben, sonst bleiben die Schalen hart.","Agar-Agar muss 2 Minuten sprudelnd kochen, sonst geliert es nicht.","Kokosmilch nur erwärmen, nicht kochen, damit sie nicht ölig wird.","Eine Prise Salz in der Kokossauce hebt die Süße.","Komponenten vorbereiten, Gläser erst kurz vor dem Servieren füllen.","Eis frisch zerstoßen: Fertig zerkleinertes Eis wird nass."],"varianten":["Chè thái: mit Früchten, Jackfrucht und Kokosmilch","Chè đậu xanh: warme Mungbohnensuppe mit Kokosmilch","Chè đậu đỏ: nur rote Bohnen in Sirup","Chè mit Tapiokaperlen und Reismehlkugeln"],"beilagen":["Eiskaffee (Cà phê sữa đá)","frische Früchte wie Mango oder Jackfrucht"],"getraenk":"Grüner Tee, Eiskaffee oder Kokoswasser","koeche":[],"quellen":[{"titel":"Luke Nguyen's Vietnam, Season 2 – Episode guide, SBS Food (Kontext: Überblick vietnamesischer Regionalküche, kein Chè-Rezept)","url":"https://www.sbs.com.au/food/article/luke-nguyens-vietnam-s2-episode-guide/e9jy4bx38"}],"bild":"dessert","farben":["#a8322a","#e8c36a","#6fa04b"],"schlagworte":["Dessert","Kokos","Bohnen","Pandan","Erfrischung","vegan"],"vegetarisch_moeglich":true}]);
